/**
 * ACP WebSocket 瀹㈡埛绔繛鎺ュ寘瑁匼n *
 * 灏佽 WebSocket 瀹㈡埛绔繛鎺ョ殑鐢熷懡鍛ㄦ湡绠＄悊锛屽寘鎷抚瑙ｆ瀽銆佹秷鎭垎鍙戙€佽繛鎺ユ柇寮€澶勭悊銆俓n */

import type { Duplex } from 'stream';
import * as net from 'net';
import { resolveLogger, type ILogger } from '@modules/core';
import {
  OpCode,
  DEFAULT_MAX_MESSAGE_SIZE,
  parseWebSocketFrame,
  encodeWebSocketFrame,
} from './websocket.js';

const logger: ILogger = resolveLogger('acp');

/**
 * ACP 瀹㈡埛绔秷鎭粨鏋刓n */
export interface AcpClientMessage {
  type: string;
  requestId?: string;
  payload?: Record<string, unknown>;
}

/**
 * ACP WebSocket 瀹㈡埛绔繛鎺ュ寘瑁匼n */
export class AcpWsClient {
  readonly id: string;
  private socket: net.Socket | Duplex;
  private onDisconnect: () => void;
  private messageHandlers: Array<(text: string) => void> = [];
  private maxMessageSize: number;

  constructor(
    id: string,
    socket: net.Socket | Duplex,
    onDisconnect: () => void
  ) {
    this.id = id;
    this.socket = socket;
    this.onDisconnect = onDisconnect;
    this.maxMessageSize = DEFAULT_MAX_MESSAGE_SIZE;

    let buffer = Buffer.alloc(0);

    this.socket.on('data', (data: Buffer) => {
      buffer = Buffer.concat([buffer, data]);
      this.processFrames(buffer, (remaining: Buffer) => {
        buffer = Buffer.from(remaining);
      });
    });

    this.socket.on('close', () => {
      this.onDisconnect();
    });

    this.socket.on('error', (err: Error) => {
      logger.warning(`[ACP] 瀹㈡埛绔紓甯? ${this.id}`, err);
    });
  }

  /**
   * 璁剧疆鏈€澶ф秷鎭ぇ灏忥紙瀛楄妭锛塡n   */
  setMaxMessageSize(size: number): void {
    this.maxMessageSize = size;
  }

  /**
   * 娉ㄥ唽娑堟伅澶勭悊鍣╘n   */
  onMessage(handler: (text: string) => void): void {
    this.messageHandlers.push(handler);
  }

  /**
   * 娉ㄥ唽鏂紑澶勭悊鍣╘n   */
  onClose(handler: () => void): void {
    this.socket.on('close', () => {
      handler();
    });
  }

  /**
   * 鍙戦€佹枃鏈秷鎭紙WebSocket 甯х紪鐮侊級
   */
  send(text: string): void {
    if (this.socket.destroyed) return;

    const payload = Buffer.from(text, 'utf-8');
    const frame = encodeWebSocketFrame(OpCode.TEXT, payload);

    try {
      this.socket.write(frame);
    } catch (err) {
      this.socket.destroy();
    }
  }

  /**
   * 鍏抽棴杩炴帴
   */
  close(code?: number, reason?: string): void {
    if (this.socket.destroyed) return;

    const closePayload = Buffer.alloc(
      2 + (reason ? Buffer.byteLength(reason, 'utf-8') : 0)
    );
    closePayload.writeUInt16BE(code || 1000, 0);
    if (reason) {
      closePayload.write(reason, 2, 'utf-8');
    }

    try {
      this.socket.write(encodeWebSocketFrame(OpCode.CLOSE, closePayload));
    } catch (err) {
      // 蹇界暐鍏抽棴鏃剁殑鍐欏叆閿欒
    }

    this.socket.end();
    this.socket.destroy();
  }

  /**
   * 瑙ｆ瀽骞跺鐞嗙紦鍐插尯涓殑 WebSocket 甯n   */
  private processFrames(
    buffer: Buffer,
    onRemaining: (remaining: Buffer) => void
  ): void {
    let offset = 0;

    while (offset < buffer.length) {
      const frame = parseWebSocketFrame(buffer, offset, this.maxMessageSize);
      if (!frame) break;

      const { opcode, payload, totalLength } = frame;

      if (opcode === OpCode.TEXT) {
        const text = payload.toString('utf-8');
        for (const handler of this.messageHandlers) {
          handler(text);
        }
      } else if (opcode === OpCode.CLOSE) {
        this.socket.end();
        this.socket.destroy();
        return;
      } else if (opcode === OpCode.PING) {
        this.socket.write(encodeWebSocketFrame(OpCode.PONG, payload));
      }

      offset += totalLength;
    }

    onRemaining(buffer.subarray(offset));
  }
}

import {
  getAcpRuntimeRegistry,
  type AcpRuntimeRegistry,
} from '../runtime/registry.js';
import {
  formatSessionIdentity,
  type AcpSessionIdentity,
} from '../runtime/session-identity.js';

import { Logger, LogLevel } from '@modules/monitoring';
const logger = new Logger({
  module: 'acp:control-plane:manager.identity-reconcile',
  level: LogLevel.INFO,
});

export interface PendingSessionIdentity {
  sessionKey: string;
  backend: string;
  runtimeSessionName: string;
  registeredAt: number;
}

export interface IdentityReconcileResult {
  reconciled: number;
  errors: string[];
  pendingIdentities: PendingSessionIdentity[];
}

const pendingIdentities = new Map<string, PendingSessionIdentity>();

export function registerPendingSessionIdentity(
  identity: AcpSessionIdentity
): void {
  const key = formatSessionIdentity(identity);
  pendingIdentities.set(key, {
    sessionKey: identity.sessionKey,
    backend: identity.backend,
    runtimeSessionName: identity.runtimeSessionName,
    registeredAt: Date.now(),
  });
}

export function unregisterPendingSessionIdentity(
  identity: AcpSessionIdentity
): void {
  const key = formatSessionIdentity(identity);
  pendingIdentities.delete(key);
}

export function getPendingSessionIdentities(): PendingSessionIdentity[] {
  return Array.from(pendingIdentities.values());
}

export function clearPendingSessionIdentities(): void {
  pendingIdentities.clear();
}

export async function reconcilePendingSessionIdentities(
  registry?: AcpRuntimeRegistry
): Promise<IdentityReconcileResult> {
  const runtimeRegistry = registry || getAcpRuntimeRegistry();
  const errors: string[] = [];
  const reconciled: string[] = [];

  for (const [key, identity] of pendingIdentities) {
    const runtime = runtimeRegistry.get(identity.backend);
    if (!runtime) {
      errors.push(
        `runtime backend "${identity.backend}" not found for session ${identity.sessionKey}`
      );
      continue;
    }

    try {
      if (runtime.prepareFreshSession) {
        await runtime.prepareFreshSession({ sessionKey: identity.sessionKey });
      }

      pendingIdentities.delete(key);
      reconciled.push(key);
    } catch (error) {
      errors.push(
        `failed to reconcile session ${identity.sessionKey}: ${error instanceof Error ? error.message : String(error)}`
      );
    }
  }

  return {
    reconciled: reconciled.length,
    errors,
    pendingIdentities: getPendingSessionIdentities(),
  };
}

export async function reconcileAllSessions(): Promise<IdentityReconcileResult> {
  return reconcilePendingSessionIdentities();
}

import type {
  AcpRuntime,
  AcpRuntimeHandle,
  AcpRuntimeControl,
} from '../runtime/types.js';
import { AcpRuntimeError } from '../runtime/errors.js';

import { Logger, LogLevel } from '@modules/monitoring';
const logger = new Logger({
  module: 'acp:control-plane:manager.runtime-controls',
  level: LogLevel.INFO,
});

export interface RuntimeControlRequest {
  control: AcpRuntimeControl;
  handle: AcpRuntimeHandle;
  payload?: Record<string, string>;
}

export interface RuntimeControlResult {
  success: boolean;
  error?: string;
}

const SUPPORTED_CONTROLS: AcpRuntimeControl[] = [
  'session/set_mode',
  'session/set_config_option',
  'session/status',
];

export function isSupportedRuntimeControl(
  control: string
): control is AcpRuntimeControl {
  return SUPPORTED_CONTROLS.includes(control as AcpRuntimeControl);
}

export function getSupportedRuntimeControls(): AcpRuntimeControl[] {
  return [...SUPPORTED_CONTROLS];
}

export async function executeRuntimeControl(
  runtime: AcpRuntime,
  request: RuntimeControlRequest
): Promise<RuntimeControlResult> {
  if (!isSupportedRuntimeControl(request.control)) {
    return {
      success: false,
      error: `unsupported runtime control: ${request.control}`,
    };
  }

  try {
    switch (request.control) {
      case 'session/set_mode': {
        if (!runtime.setMode) {
          return { success: false, error: 'runtime does not support setMode' };
        }
        const mode = request.payload?.mode;
        if (!mode) {
          return {
            success: false,
            error: 'mode is required for session/set_mode',
          };
        }
        await runtime.setMode({ handle: request.handle, mode });
        return { success: true };
      }

      case 'session/set_config_option': {
        if (!runtime.setConfigOption) {
          return {
            success: false,
            error: 'runtime does not support setConfigOption',
          };
        }
        const key = request.payload?.key;
        const value = request.payload?.value;
        if (!key || value === undefined) {
          return {
            success: false,
            error: 'key and value are required for session/set_config_option',
          };
        }
        await runtime.setConfigOption({ handle: request.handle, key, value });
        return { success: true };
      }

      case 'session/status': {
        if (!runtime.getStatus) {
          return {
            success: false,
            error: 'runtime does not support getStatus',
          };
        }
        await runtime.getStatus({ handle: request.handle });
        return { success: true };
      }

      default:
        return {
          success: false,
          error: `unhandled control: ${request.control}`,
        };
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return { success: false, error: message };
  }
}

export async function setSessionMode(
  runtime: AcpRuntime,
  handle: AcpRuntimeHandle,
  mode: string
): Promise<void> {
  const result = await executeRuntimeControl(runtime, {
    control: 'session/set_mode',
    handle,
    payload: { mode },
  });

  if (!result.success) {
    throw new AcpRuntimeError(
      'ACP_BACKEND_UNSUPPORTED_CONTROL',
      result.error || 'setMode failed'
    );
  }
}

export async function setSessionConfigOption(
  runtime: AcpRuntime,
  handle: AcpRuntimeHandle,
  key: string,
  value: string
): Promise<void> {
  const result = await executeRuntimeControl(runtime, {
    control: 'session/set_config_option',
    handle,
    payload: { key, value },
  });

  if (!result.success) {
    throw new AcpRuntimeError(
      'ACP_BACKEND_UNSUPPORTED_CONTROL',
      result.error || 'setConfigOption failed'
    );
  }
}

export async function getSessionStatus(
  runtime: AcpRuntime,
  handle: AcpRuntimeHandle
): Promise<RuntimeControlResult> {
  return executeRuntimeControl(runtime, {
    control: 'session/status',
    handle,
  });
}

import { Logger, LogLevel } from '@modules/monitoring';
const logger = new Logger({
  module: 'acp:control-plane:session-actor-queue',
  level: LogLevel.INFO,
});

type Task<T = void> = () => Promise<T>;

interface QueuedTask<T> {
  task: Task<T>;
  resolve: (value: T) => void;
  reject: (reason: unknown) => void;
}

export class SessionActorQueue {
  private queue: QueuedTask<unknown>[] = [];
  private running = false;
  private sessionKey: string;

  constructor(sessionKey: string) {
    this.sessionKey = sessionKey;
  }

  enqueue<T>(task: Task<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.queue.push({
        task: task as Task<unknown>,
        resolve: resolve as (value: unknown) => void,
        reject,
      });
      if (!this.running) {
        this.processNext();
      }
    });
  }

  private async processNext(): Promise<void> {
    if (this.queue.length === 0) {
      this.running = false;
      return;
    }

    this.running = true;
    const item = this.queue.shift()!;

    try {
      const result = await item.task();
      item.resolve(result);
    } catch (error) {
      item.reject(error);
    }

    setImmediate(() => this.processNext());
  }

  get pendingCount(): number {
    return this.queue.length;
  }

  get isRunning(): boolean {
    return this.running;
  }

  clear(): void {
    this.queue = [];
    this.running = false;
  }
}

const actorQueues = new Map<string, SessionActorQueue>();

export function getSessionActorQueue(sessionKey: string): SessionActorQueue {
  let queue = actorQueues.get(sessionKey);
  if (!queue) {
    queue = new SessionActorQueue(sessionKey);
    actorQueues.set(sessionKey, queue);
  }
  return queue;
}

export function clearSessionActorQueue(sessionKey: string): void {
  const queue = actorQueues.get(sessionKey);
  if (queue) {
    queue.clear();
    actorQueues.delete(sessionKey);
  }
}

import type { AcpRuntime } from './types.js';
import type { AcpRuntimeHandle } from './types.js';
import { AcpRuntimeError } from './errors.js';

import { Logger, LogLevel } from '@modules/monitoring';
const logger = new Logger({
  module: 'acp:runtime:availability',
  level: LogLevel.INFO,
});

export interface RuntimeAvailabilityResult {
  available: boolean;
  reason?: string;
  latencyMs?: number;
}

export async function checkRuntimeAvailability(
  runtime: AcpRuntime,
  handle?: AcpRuntimeHandle
): Promise<RuntimeAvailabilityResult> {
  const start = Date.now();

  try {
    if (runtime.doctor) {
      const report = await runtime.doctor();
      const latencyMs = Date.now() - start;
      if (report.healthy) {
        return { available: true, latencyMs };
      }
      const failedChecks = report.checks.filter((c) => !c.passed);
      return {
        available: false,
        reason: failedChecks.map((c) => c.message || c.name).join('; '),
        latencyMs,
      };
    }

    if (runtime.getStatus && handle) {
      const status = await runtime.getStatus({ handle });
      const latencyMs = Date.now() - start;
      if (status.connected) {
        return { available: true, latencyMs };
      }
      return {
        available: false,
        reason: status.error || 'runtime not connected',
        latencyMs,
      };
    }

    return { available: true, latencyMs: Date.now() - start };
  } catch (error) {
    return {
      available: false,
      reason: error instanceof Error ? error.message : String(error),
      latencyMs: Date.now() - start,
    };
  }
}

export async function waitForRuntimeReady(
  runtime: AcpRuntime,
  options?: {
    timeoutMs?: number;
    pollIntervalMs?: number;
    handle?: AcpRuntimeHandle;
  }
): Promise<RuntimeAvailabilityResult> {
  const timeoutMs = options?.timeoutMs ?? 30_000;
  const pollIntervalMs = options?.pollIntervalMs ?? 500;
  const deadline = Date.now() + timeoutMs;

  while (Date.now() < deadline) {
    const result = await checkRuntimeAvailability(runtime, options?.handle);
    if (result.available) {
      return result;
    }
    await new Promise((resolve) => setTimeout(resolve, pollIntervalMs));
  }

  const finalResult = await checkRuntimeAvailability(runtime, options?.handle);
  if (!finalResult.available) {
    return {
      available: false,
      reason: `runtime not ready within ${timeoutMs}ms: ${finalResult.reason || 'timeout'}`,
    };
  }

  return finalResult;
}

export async function assertRuntimeReady(
  runtime: AcpRuntime,
  options?: {
    timeoutMs?: number;
    handle?: AcpRuntimeHandle;
  }
): Promise<void> {
  const result = await waitForRuntimeReady(runtime, options);
  if (!result.available) {
    throw new AcpRuntimeError(
      'ACP_BACKEND_UNAVAILABLE',
      result.reason || 'runtime unavailable'
    );
  }
}

