/**
 * KnowledgeScanner 鈥?鐭ヨ瘑鏂囦欢鍙樻洿鎵弿鍣╘n *
 * 鎵弿鐭ヨ瘑搴撶洰褰曚腑鐨?.md 鏂囦欢鍙樻洿锛堟寜 mtime锛夛紝
 * 鏀寔 git-style diff 妫€娴嬶紙灏忓彉鏇村彧杩斿洖 diff锛夈€俓n */

import { readdir, stat, readFile, writeFile, mkdir } from 'fs/promises';
import { join, relative } from 'path';
import { createHash } from 'crypto';
import { resolvePyappHome } from '@modules/core';
import type { KnowledgeDelta } from '../types';
import { Logger, LogLevel } from '@modules/monitoring';

const logger = new Logger({
  module: 'dream:gather:knowledgeScanner',
  level: LogLevel.INFO,
});

/** 澶у彉鏇撮槇鍊硷細鍙樻洿琛屾暟瓒呰繃姝ゆ瘮渚嬭涓哄叏閲忓彉鏇?*/
const LARGE_CHANGE_RATIO = 0.5;
/** 灏忓彉鏇撮槇鍊硷細鍙樻洿琛屾暟灏忎簬姝よ鏁拌涓哄井灏忓彉鏇?*/
const SMALL_CHANGE_LINES = 10;

export interface ScannedFile {
  filePath: string;
  fileName: string;
  mtimeMs: number;
  content: string;
  isDelta: boolean;
  delta?: KnowledgeDelta;
}

export class KnowledgeScanner {
  private knowledgeRoot: string;
  private deltaDir: string;

  constructor() {
    this.knowledgeRoot = join(resolvePyappHome(), 'knowledge');
    this.deltaDir = join(
      resolvePyappHome(),
      'data',
      'dream',
      'knowledge_delta'
    );
  }

  /**
   * 鎵弿鐭ヨ瘑搴撳彉鏇存枃浠禱n   * @param sinceMs 涓婃姊﹀瀹屾垚鏃堕棿鎴砛n   * @returns 鍙樻洿鏂囦欢鍒楄〃锛堝惈鍐呭鎴?diff锛塡n   */
  async scanChanges(sinceMs: number): Promise<ScannedFile[]> {
    const results: ScannedFile[] = [];

    try {
      await this.scanDir(this.knowledgeRoot, sinceMs, results);
    } catch (e) {
      logger.warn('鐭ヨ瘑搴撴壂鎻忓け璐?, { error: String(e) });
    }

    return results;
  }

  /** 閫掑綊鎵弿鐩綍 */
  private async scanDir(
    dir: string,
    sinceMs: number,
    results: ScannedFile[]
  ): Promise<void> {
    const { readdir } = await import('fs/promises');
    let entries: { name: string; isDirectory: () => boolean }[];
    try {
      entries = (await readdir(dir, { withFileTypes: true })) as any;
    } catch {
      return;
    }

    for (const entry of entries) {
      const fullPath = join(dir, entry.name);

      // 璺宠繃 raw/ 鍜?.knowledge-cache/ 鐩綍
      if (entry.isDirectory()) {
        if (entry.name === 'raw' || entry.name.startsWith('.')) continue;
        await this.scanDir(fullPath, sinceMs, results);
        continue;
      }

      if (!entry.name.endsWith('.md')) continue;

      try {
        const s = await stat(fullPath);
        if (s.mtimeMs <= sinceMs) continue;

        const content = await readFile(fullPath, 'utf-8');
        const scanned: ScannedFile = {
          filePath: fullPath,
          fileName: relative(this.knowledgeRoot, fullPath),
          mtimeMs: s.mtimeMs,
          content,
          isDelta: false,
        };

        // 妫€鏌ユ槸鍚﹀彲浠ュ彧杩斿洖 diff
        const delta = await this.computeDelta(scanned.fileName, content);
        if (delta) {
          scanned.isDelta = true;
          scanned.delta = delta;
        }

        results.push(scanned);
      } catch {
        /* skip unreadable files */
      }
    }
  }

  /**
   * 璁＄畻鐭ヨ瘑鏂囦欢鐨勫彉鏇村閲廫n   * 灏忓彉鏇达紙< 10 琛?diff锛夊彧杩斿洖 diff锛屽ぇ鍙樻洿杩斿洖 null锛堥渶瑕佸叏閲忚锛塡n   */
  private async computeDelta(
    fileName: string,
    currentContent: string
  ): Promise<KnowledgeDelta | null> {
    const deltaPath = join(
      this.deltaDir,
      `${fileName.replace(/[/\\]/g, '_')}.json`
    );
    const currentHash = this.sha256(currentContent);

    let previous: KnowledgeDelta | null = null;
    try {
      const data = await readFile(deltaPath, 'utf-8');
      previous = JSON.parse(data) as KnowledgeDelta;
    } catch {
      /* first time scanning */
    }

    if (!previous) {
      // 棣栨鎵弿锛屽瓨鍌ㄥ熀绾縗n      await this.saveDelta(deltaPath, {
        fileName,
        baseSnapshot: currentHash,
        additions: [],
        removals: [],
        lastCheckedAt: Date.now(),
      });
      return null;
    }

    if (previous.baseSnapshot === currentHash) {
      // 鍐呭鏈彉锛坢time 鍙樹簡浣嗗唴瀹规病鍙橈級
      return null;
    }

    // 璁＄畻琛岀骇 diff
    const oldLines = this.getContentLines(previous);
    const newLines = currentContent.split('\n');
    const additions: string[] = [];
    const removals: string[] = [];
    const oldSet = new Set(oldLines);

    for (const line of newLines) {
      if (!oldSet.has(line)) {
        additions.push(line);
      }
    }
    const newSet = new Set(newLines);
    for (const line of oldLines) {
      if (!newSet.has(line)) {
        removals.push(line);
      }
    }

    const totalChanges = additions.length + removals.length;
    const totalLines = Math.max(oldLines.length, newLines.length);

    // 鏇存柊鍩虹嚎
    await this.saveDelta(deltaPath, {
      fileName,
      baseSnapshot: currentHash,
      additions,
      removals,
      lastCheckedAt: Date.now(),
    });

    // 灏忓彉鏇达細鍙繑鍥?diff
    if (
      totalChanges < SMALL_CHANGE_LINES &&
      totalChanges / totalLines < LARGE_CHANGE_RATIO
    ) {
      return {
        fileName,
        baseSnapshot: previous.baseSnapshot,
        additions,
        removals,
        lastCheckedAt: Date.now(),
      };
    }

    // 澶у彉鏇存垨鏂版枃浠讹細杩斿洖 null锛堣〃绀洪渶瑕佸叏閲忚锛塡n    return null;
  }

  /** 浠?delta 璁板綍涓仮澶嶆棫鍐呭琛?*/
  private getContentLines(delta: KnowledgeDelta): string[] {
    // 绠€鍖栧疄鐜帮細浠?source content 涓噸寤篭n    // 瀹為檯涓婇渶瑕佸瓨鍌ㄥ畬鏁存棫鍐呭鎴栦粎鐢?hash 姣旇緝
    return [];
  }

  private sha256(input: string): string {
    return createHash('sha256').update(input).digest('hex');
  }

  private async saveDelta(
    deltaPath: string,
    delta: KnowledgeDelta
  ): Promise<void> {
    await mkdir(this.deltaDir, { recursive: true });
    await writeFile(deltaPath, JSON.stringify(delta, null, 2), 'utf-8');
  }
}

