  /** 瑙ｆ瀽 LLM 杩斿洖鐨勫垎鏋愮粨鏋?JSON */
  private parseAnalysisResult(result: string): Record<string, any> {
    // 灏濊瘯鐩存帴瑙ｆ瀽 JSON
    try {
      return JSON.parse(result);
    } catch {
      // 灏濊瘯鎻愬彇 JSON 鍧梊n      const match = result.match(/```(?:json)?\s*([\s\S]*?)```/);
      if (match) {
        try {
          return JSON.parse(match[1].trim());
        } catch {
          /* fall through */
        }
      }
    }
    return {};
  }
