 * FlowEngine 娴佺▼寮曟搸
 * P2 鈥?瀵规爣 OpenClaw 鐨勬祦绋嬬郴缁焅n */

/**
 * 娴佺▼姝ラ
 */
import { Logger, LogLevel } from '@modules/monitoring';
const logger = new Logger({ module: 'flows:FlowEngine', level: LogLevel.INFO });

export interface FlowStep {
  id: string;
  name: string;
  type: 'action' | 'condition' | 'parallel' | 'subflow' | 'wait';
  handler: (context: FlowContext) => Promise<FlowStepResult> | FlowStepResult;
  next?: string;
  onFailure?: string;
  timeout?: number;
  retryCount?: number;
}

/**
 * 姝ラ缁撴灉
 */
export interface FlowStepResult {
  success: boolean;
  next?: string;
  data?: unknown;
  error?: string;
}

/**
 * 娴佺▼瀹氫箟
 */
export interface FlowDefinition {
  id: string;
  name: string;
  description: string;
  version: string;
  steps: FlowStep[];
  startStep: string;
  config?: {
    maxRetries?: number;
    timeout?: number;
    enableHistory?: boolean;
  };
}

/**
 * 娴佺▼涓婁笅鏂嘰n */
export interface FlowContext {
  flowId: string;
  executionId: string;
  stepId: string;
  data: Record<string, unknown>;
  history: Array<{ stepId: string; result: FlowStepResult; timestamp: number }>;
  startTime: number;
  metadata?: Record<string, unknown>;
}

/**
 * 娴佺▼缁撴灉
 */
export interface FlowResult {
  success: boolean;
  flowId: string;
  executionId: string;
  duration: number;
  currentStep: string;
  error?: string;
  data: Record<string, unknown>;
  history: Array<{ stepId: string; result: FlowStepResult; timestamp: number }>;
}

/**
 * 娴佺▼閰嶇疆
 */
export interface FlowConfig {
  maxExecutions: number;
  defaultTimeout: number;
  enableHistory: boolean;
}

/**
 * 娴佺▼寮曟搸
 */
export class FlowEngine {
  private flows: Map<string, FlowDefinition> = new Map();
  private executions: Map<string, FlowContext> = new Map();
  private config: FlowConfig;

  constructor(config?: Partial<FlowConfig>) {
    this.config = {
      maxExecutions: config?.maxExecutions || 100,
      defaultTimeout: config?.defaultTimeout || 300000,
      enableHistory: config?.enableHistory !== false,
    };
  }

  /**
   * 娉ㄥ唽娴佺▼
   */
  register(flow: FlowDefinition): void {
    this.flows.set(flow.id, flow);
  }

  /**
   * 鎵ц娴佺▼
   */
  async execute(
    flowId: string,
    initialData?: Record<string, unknown>
  ): Promise<FlowResult> {
    const flow = this.flows.get(flowId);

    if (!flow) {
      return {
        success: false,
        flowId,
        executionId: '',
        duration: 0,
        currentStep: '',
        error: `鏈壘鍒版祦绋? ${flowId}`,
        data: {},
        history: [],
      };
    }

    if (this.executions.size >= this.config.maxExecutions) {
      return {
        success: false,
        flowId,
        executionId: '',
        duration: 0,
        currentStep: '',
        error: '杈惧埌鏈€澶у苟鍙戞墽琛屾暟',
        data: {},
        history: [],
      };
    }

    const executionId = `exec_${flowId}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

    const context: FlowContext = {
      flowId,
      executionId,
      stepId: flow.startStep,
      data: { ...initialData },
      history: [],
      startTime: Date.now(),
    };

    this.executions.set(executionId, context);

    const result = await this.executeStep(flow, flow.startStep, context);

    this.executions.delete(executionId);

    return {
      success: result.success,
      flowId,
      executionId,
      duration: Date.now() - context.startTime,
      currentStep: flow.startStep,
      error: result.error,
      data: context.data,
      history: context.history,
    };
  }

  /**
   * 鎵ц姝ラ
   */
  private async executeStep(
    flow: FlowDefinition,
    stepId: string,
    context: FlowContext
  ): Promise<FlowStepResult> {
    const step = flow.steps.find((s) => s.id === stepId);

    if (!step) {
      return { success: false, error: `鏈壘鍒版楠? ${stepId}` };
    }

    context.stepId = stepId;

    try {
      let result: FlowStepResult;

      if (step.timeout) {
        result = await this.executeWithTimeout(step, context, step.timeout);
      } else if (this.config.defaultTimeout > 0) {
        result = await this.executeWithTimeout(
          step,
          context,
          this.config.defaultTimeout
        );
      } else {
        result = await step.handler(context);
      }

      if (this.config.enableHistory) {
        context.history.push({ stepId, result, timestamp: Date.now() });
      }

      if (!result.success && step.onFailure) {
        return this.executeStep(flow, step.onFailure, context);
      }

      if (result.next || step.next) {
        return this.executeStep(flow, result.next || step.next!, context);
      }

      return result;
    } catch (err) {
      const errorResult: FlowStepResult = {
        success: false,
        error: err instanceof Error ? err.message : String(err),
      };

      if (this.config.enableHistory) {
        context.history.push({
          stepId,
          result: errorResult,
          timestamp: Date.now(),
        });
      }

      if (step.onFailure) {
        return this.executeStep(flow, step.onFailure, context);
      }

      return errorResult;
    }
  }

  /**
   * 甯﹁秴鏃剁殑鎵ц
   */
  private async executeWithTimeout(
    step: FlowStep,
    context: FlowContext,
    timeout: number
  ): Promise<FlowStepResult> {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        resolve({ success: false, error: `姝ラ瓒呮椂: ${step.name}` });
      }, timeout);

      Promise.resolve(step.handler(context))
        .then((result) => {
          clearTimeout(timer);
          resolve(result);
        })
        .catch((err) => {
          clearTimeout(timer);
          reject(err);
        });
    });
  }

  /**
   * 鑾峰彇娴佺▼瀹氫箟
   */
  getFlow(id: string): FlowDefinition | undefined {
    return this.flows.get(id);
  }

  /**
   * 鍒楀嚭鎵€鏈夋祦绋媆n   */
  listFlows(): FlowDefinition[] {
    return Array.from(this.flows.values());
  }

  /**
   * 鍒犻櫎娴佺▼
   */
  deleteFlow(id: string): boolean {
    return this.flows.delete(id);
  }
}

