/**
 * LocalHTTPService 閰嶇疆
 */
export interface LocalHTTPConfig {
  host: string;
  port: number;
}

/**
 * LocalHTTPService 绫籠n * 鎻愪緵鏈湴 HTTP API 鏈嶅姟锛屽鎺?CoreAPI
 */
export class LocalHTTPService {
  private server: http.Server | null = null;
  private config: LocalHTTPConfig;
  private _isRunning = false;
  /** 搴旂敤鏄惁宸插畬鍏ㄥ氨缁紙launch 瀹屾垚鍓嶅墠绔姹傝繑鍥?503锛?*/
  static _appReady = false;
  private readonly apiSecret: string;
  private compileScheduler: any = null;
  /** handler 涓婁笅鏂囷紙鎻愪緵 sendError, readRequestBody, broadcastEvent 绛夛級 */
  private readonly _handlerCtx: HandlerCtx = createHandlerCtx();

  constructor(config: LocalHTTPConfig) {
    this.config = config;
    setAnalyticsDependencies(
      analyticsService,
      costTracker,
      getCostRecordRepository(),
      PerformanceMonitorService
    );
    setupInfrastructureDiagnostics();
    this.apiSecret = configManager.env('LIRI_API_SECRET') || '';
  }

  /**
   * 妫€鏌ユ湇鍔℃槸鍚︽鍦ㄨ繍琛孿n   */
  isStarted(): boolean {
    return this._isRunning;
  }

  /**
   * 鑾峰彇鏈嶅姟绔彛鍙穃n   */
  getPort(): number | undefined {
    const addr = this.server?.address();
    if (addr && typeof addr === 'object') {
      return addr.port;
    }
    return undefined;
  }

  /**
   * 鏍￠獙璇锋眰鏄惁鎼哄甫鏈夋晥鐨勫叡浜瘑閽n   * 濮旀墭缁?LocalHTTPServiceHelpers.verifyRequestAuth
   */
  private verifyRequestAuth(req: http.IncomingMessage): boolean {
    return verifyRequestAuth(req, this.apiSecret);
  }

  /**
   * 绉嶅瓙鐭ヨ瘑搴擄細濮旀墭缁?LocalHTTPServiceHelpers.seedKnowledgeBaseIfEmpty
   */
  private async seedKnowledgeBaseIfEmpty(): Promise<void> {
    return seedKnowledgeBaseIfEmpty();
  }

  /**
   * 鍚姩缂栬瘧璋冨害鍣╘n   * 濮旀墭缁?LocalHTTPServiceHelpers.startCompileScheduler
   */
  private async startCompileScheduler(): Promise<void> {
    this.compileScheduler = await startCompileScheduler();
  }

  /**
   * 鍚姩 HTTP 鏈嶅姟
   */
  async start(): Promise<void> {
    if (this.server) {
      logger.warning('LocalHTTPService 宸茬粡鍚姩锛屾棤闇€閲嶅鍚姩');
      return;
    }

    this.server = http.createServer((req, res) => {
      this.handleRequest(req, res).catch((err) => {
        void handleError(err, {
          module: 'infra:http',
          action: 'handle_request',
        });
        if (!res.headersSent) {
          res.writeHead(500, { 'Content-Type': 'application/json' });
          res.end(
            JSON.stringify({ error: { message: 'Internal server error' } })
          );
        }
      });
    });

    // 閰嶇疆闀胯繛鎺ヨ秴鏃讹紝鏀寔 SSE 娴佸紡璇锋眰
    // server.timeout: 0 琛ㄧず绂佺敤璇锋眰瓒呮椂锛圫SE 娴佸紡璇锋眰鍙兘鎸佺画寰堥暱鏃堕棿锛塡n    // keepAliveTimeout: 鏈嶅姟鍣ㄥ湪鍙戦€佹渶鍚庝竴涓搷搴斿悗绛夊緟鏇村鏁版嵁鐨勬椂闂碶n    // headersTimeout: 鏈嶅姟鍣ㄧ瓑寰呭鎴风鍙戦€佸畬鏁磋姹傚ご鐨勬椂闂碶n    this.server.timeout = 0; // 绂佺敤璇锋眰瓒呮椂锛屾敮鎸侀暱鏃堕棿 SSE 娴乗n    this.server.keepAliveTimeout = 60000 * 5; // 5鍒嗛挓
    this.server.headersTimeout = 60000 * 6; // 6鍒嗛挓锛堝繀椤诲ぇ浜?keepAliveTimeout锛塡n
    return new Promise((resolve, reject) => {
      this.server!.listen(this.config.port, this.config.host, () => {
        this._isRunning = true;
        logger.info(
          `LocalHTTPService 宸插惎鍔? http://${this.config.host}:${this.config.port}`
        );
        // 寮傛鍒濆鍖栫煡璇嗗簱绉嶅瓙锛屼笉闃诲鍚姩
        this.seedKnowledgeBaseIfEmpty().catch((err) =>
          logger.warning('鐭ヨ瘑搴撶瀛愬垵濮嬪寲澶辫触锛堥潪鍏抽敭閿欒锛?, {
            error: String(err),
          })
        );
        this.startCompileScheduler().catch((err) =>
          logger.warning('缂栬瘧璋冨害鍣ㄥ惎鍔ㄥけ璐ワ紙闈炲叧閿敊璇級', {
            error: String(err),
          })
        );
        resolve();
      });

      this.server!.on('error', (err) => {
        logger.error('LocalHTTPService 鍚姩澶辫触', { error: err.message });
        this._isRunning = false;
        reject(err);
      });
    });
  }

  /**
   * 鍋滄 HTTP 鏈嶅姟
   */
  async stop(): Promise<void> {
    if (this.compileScheduler) {
      this.compileScheduler.stop();
      this.compileScheduler = null;
    }
    stopSSE();
    return new Promise((resolve, reject) => {
      if (!this.server) {
        logger.info('LocalHTTPService 鏈惎鍔紝鏃犻渶鍋滄');
        resolve();
        return;
      }

      this.server.close((err) => {
        if (err) {
          logger.error('LocalHTTPService 鍋滄澶辫触', { error: err.message });
          reject(err);
        } else {
          this.server = null;
          this._isRunning = false;
          logger.info('LocalHTTPService 宸插仠姝?);
          resolve();
        }
      });
    });
  }

  /**
   * 澶勭悊 HTTP 璇锋眰
   */
  private async handleRequest(
    req: http.IncomingMessage,
    res: http.ServerResponse
  ): Promise<void> {
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader(
      'Access-Control-Allow-Methods',
      'GET, POST, PUT, PATCH, DELETE, OPTIONS'
    );
    res.setHeader(
      'Access-Control-Allow-Headers',
      'Content-Type, Authorization, x-api-key, traceparent, tracestate'
    );

    if (req.method === 'OPTIONS') {
      res.writeHead(204);
      res.end();
      return;
    }

    // 鍏变韩瀵嗛挜鏍￠獙锛氱‘淇濊姹傛潵鑷鎺堟潈鐨?Tauri 瀹㈡埛绔痋n    if (!this.verifyRequestAuth(req)) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: { message: 'Unauthorized' } }));
      return;
    }

    const url = req.url?.split('?')[0] || '';

    // 搴旂敤灏氭湭瀹屽叏灏辩华鏃讹紝瀵逛笟鍔¤姹傝繑鍥?503
    if (!LocalHTTPService._appReady && url !== '/v1/health/report') {
      res.writeHead(503, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({ error: { message: 'Service starting, please retry' } })
      );
      return;
    }

    logger.debug('鏀跺埌璇锋眰', {
      method: req.method,
      url: req.url,
      parsedUrl: url,
    });

    // ---- 鎵€鏈夎矾鐢遍€昏緫宸叉彁鍙栬嚦 route-table.ts 鐨?dispatchRoute ----
    // ---- 璺敱璋冨害锛堝尮閰?method + URL 鍒板搴?handler锛?---
    const matched = await dispatchRoute(
      req,
      res,
      url,
      this as unknown as Record<string, Function>,
      (event: string, data: any) => this.broadcastEvent(event, data),
      this._handlerCtx
    );
    if (matched) return;

    logger.warning('鏈尮閰嶇殑璺敱', {
      method: req.method,
      url: req.url,
      parsedUrl: url,
    });
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(
      JSON.stringify({
        error: { message: 'Not found', type: 'invalid_request_error' },
      })
    );
  }

  // CPU 浣跨敤鐜囪窡韪姸鎬侊紙宸茬Щ鑷?monitoring-handlers.ts锛塡n
  /**
