  /**
   * 澶勭悊鎵ц鍛戒护璇锋眰 POST /v1/commands/execute
   */
  private async handleExecuteCommand(
    req: http.IncomingMessage,
    res: http.ServerResponse
  ): Promise<void> {
    try {
      const body = await this.readRequestBody(req);
      if (!body) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(
          JSON.stringify({ error: { message: 'request body is required' } })
        );
        return;
      }

      let parsedBody;
      try {
        parsedBody = JSON.parse(body);
      } catch (err) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(
          JSON.stringify({ error: { message: 'invalid JSON in request body' } })
        );
        return;
      }

      const { command } = parsedBody;

      if (!command) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: { message: 'command is required' } }));
        return;
      }

      const { commandExecutor } =
        await import('@modules/commands/executor/CommandExecutor.js');
      const result = await commandExecutor.execute(command);

      const output =
        result.value?.toString() || result.message?.toString() || '';
      const error = result.type === 'error' ? output : '';

      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(
        JSON.stringify({
          success: result.success !== false,
          output,
          error,
        })
      );
    } catch (err) {
      this.sendError(res, err);
    }
  }

  /**
   * 閫掑綊澶嶅埗鐩綍锛堝甫鍥炴粴浠ょ墝锛塡n   * @param src 婧愮洰褰昞n   * @param dest 鐩爣鐩綍
   * @param fs fs 妯″潡
   * @param path path 妯″潡
   * @returns 澶嶅埗缁撴灉缁熻
   */
  private copyDirectory(
    src: string,
    dest: string,
    fs: any,
    path: any
  ): { copied: number; skipped: number; errors: string[] } {
    let copied = 0;
    let skipped = 0;
    const errors: string[] = [];

    if (!fs.existsSync(src)) {
      return { copied, skipped, errors };
    }

    if (!fs.existsSync(dest)) {
      fs.mkdirSync(dest, { recursive: true });
    }

    const entries = fs.readdirSync(src, { withFileTypes: true });

    for (const entry of entries) {
      // 璺宠繃杩佺Щ鏍囪鏂囦欢鏈韩锛岄伩鍏嶈澶嶅埗
      if (
        entry.name === '.migrating' ||
        entry.name === '.migration_committed'
      ) {
        continue;
      }
      const srcPath = path.join(src, entry.name);
      const destPath = path.join(dest, entry.name);

      try {
        if (entry.isDirectory()) {
          const result = this.copyDirectory(srcPath, destPath, fs, path);
          copied += result.copied;
          skipped += result.skipped;
          errors.push(...result.errors);
        } else {
          if (!fs.existsSync(destPath)) {
            fs.copyFileSync(srcPath, destPath);
            copied++;
          } else {
            skipped++;
          }
        }
      } catch (err) {
        errors.push(`澶嶅埗 ${srcPath} 澶辫触: ${(err as Error).message}`);
      }
    }

    return { copied, skipped, errors };
  }

  /**
   * 璁剧疆鐢ㄦ埛鏁版嵁鐩綍 PUT /v1/settings/data-directory
   * 浣跨敤涓ら樁娈佃縼绉伙細鍏ㄩ儴澶嶅埗鎴愬姛鍚庢墠鍒囨崲鐩綍锛屽鍒跺け璐ュ垯鍥炴粴娓呯悊
   * @param req
   * @param res
   * @param options.migrate 鏄惁杩佺Щ鐜版湁鏁版嵁锛堥粯璁?true锛塡n   */
  private async handleSetDataDirectory(
    req: http.IncomingMessage,
    res: http.ServerResponse
  ): Promise<void> {
    try {
      const body = await this.readRequestBody(req);
      const payload = JSON.parse(body);
      const { directory, migrate = true } = payload;

      if (!directory || typeof directory !== 'string') {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(
          JSON.stringify({
            error: {
              message: '鐩綍璺緞涓嶈兘涓虹┖',
              type: 'invalid_request_error',
            },
          })
        );
        return;
      }

      const fs = await import('fs');
      const path = await import('path');
      const resolvedDir = path.resolve(directory);

      // 楠岃瘉鐩綍鍙啓
      try {
        if (!fs.existsSync(resolvedDir)) {
          fs.mkdirSync(resolvedDir, { recursive: true });
        }
        const testFile = path.join(resolvedDir, '.write_test');
        fs.writeFileSync(testFile, '');
        fs.unlinkSync(testFile);
      } catch (err) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(
          JSON.stringify({
            error: {
              message: `鏃犳硶鍒涘缓鎴栧啓鍏ョ洰褰? ${(err as Error).message}`,
              type: 'invalid_request_error',
            },
          })
        );
        return;
      }

      // 鑾峰彇褰撳墠鏁版嵁鐩綍
      const { resolvePyappHome, setUserDataDirOverride } =
        await import('@modules/core/paths');
      const currentDir = resolvePyappHome();

      // 鎵ц鏁版嵁杩佺Щ锛堜袱闃舵锛氬厛澶嶅埗锛屾垚鍔熷悗鍐嶅垏鎹級
      let migrationResult: {
        copied: number;
        skipped: number;
        errors: string[];
      } | null = null;
      if (migrate && currentDir !== resolvedDir && fs.existsSync(currentDir)) {
        // 闃舵涓€锛氬啓杩佺Щ浠ょ墝锛屾爣璁拌縼绉昏繘琛屼腑
        try {
          fs.writeFileSync(
            path.join(resolvedDir, '.migrating'),
            Date.now().toString(),
            'utf-8'
          );
        } catch (err) {
          // 闈炶嚧鍛斤細浠ょ墝鍐欏叆澶辫触涓嶅奖鍝嶈縼绉籠n        }

        migrationResult = this.copyDirectory(currentDir, resolvedDir, fs, path);

        // 妫€鏌ヨ縼绉绘槸鍚﹀嚭閿欙紝鍑洪敊鍒欐墽琛屽洖婊歕n        if (migrationResult.errors.length > 0) {
          this.rollbackMigration(resolvedDir, fs, path, currentDir);

          res.writeHead(500, { 'Content-Type': 'application/json' });
          res.end(
            JSON.stringify({
              success: false,
              message: `鏁版嵁杩佺Щ澶辫触锛屽凡鍥炴粴锛屼繚鐣欎簡 ${migrationResult.copied} 涓凡澶嶅埗鐨勬枃浠朵綔涓哄浠藉弬鑰僠,
              directory: resolvedDir,
              migration: migrationResult,
              rolledBack: true,
              error: {
                message: `杩佺Щ杩囩▼涓嚭鐜?${migrationResult.errors.length} 涓敊璇紝鐩綍宸插洖婊歚,
                type: 'migration_error',
              },
            })
          );
          return;
        }

        // 闃舵浜岋細鍐欒縼绉诲畬鎴愭爣璁癨n        try {
          fs.writeFileSync(
            path.join(resolvedDir, '.migration_committed'),
            Date.now().toString(),
            'utf-8'
          );
        } catch (err) {
          // 闈炶嚧鍛斤細鏍囪鍐欏叆澶辫触涓嶅奖鍝嶇洰褰曞垏鎹n        }
      }

      // 璁剧疆鍏ㄥ眬瑕嗙洊
      setUserDataDirOverride(resolvedDir);

      // 鎸佷箙鍖栧埌鐢ㄦ埛璁剧疆
      const { updateUserSettings } =
        await import('@modules/config/settings/userSettings');
      await updateUserSettings({ dataDirectory: resolvedDir });

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({
          success: true,
          message: migrationResult
            ? `鏁版嵁鐩綍宸叉洿鏂帮紝宸茶縼绉?${migrationResult.copied} 涓枃浠讹紝璺宠繃 ${migrationResult.skipped} 涓枃浠禶
            : '鏁版嵁鐩綍宸叉洿鏂?,
          directory: resolvedDir,
          migration: migrationResult,
        })
      );
    } catch (error) {
      this.sendError(res, error);
    }
  }

  /**
   * 鍥炴粴鏁版嵁杩佺Щ锛氬垹闄ょ洰鏍囩洰褰曚腑鐨勫凡澶嶅埗鍐呭
   * @param destDir 鐩爣鐩綍锛堝皢琚竻鐞嗭級
   * @param fs fs 妯″潡
   * @param path path 妯″潡
   * @param oldDir 鍘熸暟鎹洰褰曪紙淇濈暀涓嶅姩锛塡n   */
  private rollbackMigration(
    destDir: string,
    fs: any,
    path: any,
    _oldDir: string
  ): void {
    try {
      // 娓呯悊鐩爣鐩綍涓櫎 .migrating 浠ょ墝澶栫殑鎵€鏈夋枃浠跺拰瀛愮洰褰昞n      if (fs.existsSync(destDir)) {
        const entries = fs.readdirSync(destDir, { withFileTypes: true });
        for (const entry of entries) {
          if (entry.name === '.migrating') continue;
          const entryPath = path.join(destDir, entry.name);
          try {
            if (entry.isDirectory()) {
              fs.rmSync(entryPath, { recursive: true, force: true });
            } else {
              fs.unlinkSync(entryPath);
            }
          } catch (err) {
            // 闈欓粯蹇界暐娓呯悊涓殑涓埆閿欒
          }
        }
      }
    } catch (err) {
      // 鍥炴粴娓呯悊澶辫触涓嶅奖鍝嶄富娴佺▼锛屾暟鎹繚鐣欏湪鍘熺洰褰昞n    }
  }

