              const name = entry.name;
              const description = parsed.frontmatter?.description || '';
              const fm = parsed.frontmatter as Record<string, any>;
              const version = fm?.version || '1.0.0';
              const author = fm?.author || '';
              const category = fm?.category || 'general';

              if (seen.has(name)) continue;
              seen.add(name);

              let createdAt = 0;
              let updatedAt = 0;
              try {
                const st = await stat(skillMdPath);
                createdAt = st.birthtimeMs;
                updatedAt = st.mtimeMs;
              } catch (err) {
                /* use defaults */
              }

              skills.push({
                id: name,
                name,
                description,
                status: 'enabled',
                category,
                parameters: [],
                createdAt,
                updatedAt,
                usageCount: 0,
                lastUsedAt: null,
                source,
                version,
                filePath: skillMdPath,
                frontmatter: { author, version, category },
              });
            } catch (err) {
              // 娌℃湁 SKILL.md 鐨勫瓙鐩綍璺宠繃
              continue;
            }
            continue;
          }

          // 鏍圭洰褰曚笅鐨?.md 鏂囦欢锛堝吋瀹规棫缁撴瀯锛塡n          if (!entry.isFile() || !entry.name.endsWith('.md')) continue;
          const filePath = join(dir, entry.name);
          try {
            const content = await readFile(filePath, 'utf-8');
            const parsed = parseSkillFrontmatter(content);
            const name = entry.name.replace(/\.md$/, '');
            const description = parsed.frontmatter?.description || '';
            const fm = parsed.frontmatter as Record<string, any>;
            const version = fm?.version || '1.0.0';
            const author = fm?.author || '';
            const category = fm?.category || 'general';

            if (seen.has(name)) continue;
            seen.add(name);

            let createdAt = 0;
            let updatedAt = 0;
            try {
              const st = await stat(filePath);
              createdAt = st.birthtimeMs;
              updatedAt = st.mtimeMs;
            } catch (err) {
              /* use defaults */
            }

            skills.push({
              id: name,
              name,
              description,
              status: 'enabled',
              category,
              parameters: [],
              createdAt,
              updatedAt,
              usageCount: 0,
              lastUsedAt: null,
              source,
              version,
              filePath,
              frontmatter: { author, version, category },
            });
          } catch (err) {
            /* skip malformed files */
          }
        }
      };

      // 鎵弿鍐呯疆鎶€鑳絓n      const projectRoot = resolveProjectRoot();
      const builtinDir = join(projectRoot, 'app', 'src', 'builtin', 'skills');
      await scanDir(builtinDir, 'builtin');

      // 鎵弿鐢ㄦ埛鎶€鑳絓n      const userSkillsDir = join(resolvePyappHome(), 'skills');
      await scanDir(userSkillsDir, 'user');

      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(JSON.stringify({ skills, total: skills.length }));
    } catch (err) {
      this.sendError(res, err);
    }
  }

  /**
   * 澶勭悊鑾峰彇绯荤粺鎶€鑳藉唴瀹?GET /v1/skills/system/:id/content
   * 璇诲彇 SKILL.md 鏂囦欢杩斿洖鍘熷鍐呭鍙?frontmatter
   */
  private async handleSystemSkillContent(
    _req: http.IncomingMessage,
    res: http.ServerResponse,
    skillId: string
  ): Promise<void> {
    try {
      const { readFile } = await import('fs/promises');
      const { existsSync } = await import('fs');
      const { resolveProjectRoot, resolvePyappHome } =
        await import('@modules/core/paths');
      const pathMod = await import('path');

      const candidateDirs = [
        pathMod.join(
          resolveProjectRoot(),
          'app',
          'src',
          'builtin',
          'skills',
          decodeURIComponent(skillId)
        ),
        pathMod.join(resolvePyappHome(), 'skills', decodeURIComponent(skillId)),
      ];

      let skillFile = '';
      for (const dir of candidateDirs) {
        const candidate = pathMod.join(dir, 'SKILL.md');
        if (existsSync(candidate)) {
          skillFile = candidate;
          break;
        }
      }

      if (!skillFile) {
        res.writeHead(404, {
          'Content-Type': 'application/json; charset=utf-8',
        });
        res.end(JSON.stringify({ error: { message: '鎶€鑳芥湭鎵惧埌' } }));
        return;
      }

      const rawContent = await readFile(skillFile, 'utf-8');
      let content = rawContent;
      const frontmatter: Record<string, unknown> = {};
      const linkedFiles: string[] = [];

      const fmMatch = rawContent.match(/^---\n([\s\S]*?)\n---\n/);
      if (fmMatch) {
        content = rawContent.slice(fmMatch[0].length);
        const lines = fmMatch[1].split('\n');
        for (const line of lines) {
          const m = line.match(/^(\w[\w-]*):\s*(.+)$/);
          if (m) frontmatter[m[1]] = m[2].trim();
        }
      }

      // 鏀堕泦鍏宠仈鏂囦欢
      const skillDir = pathMod.dirname(skillFile);
      try {
        const entries = await (
          await import('fs/promises')
        ).readdir(skillDir, { withFileTypes: true });
        for (const entry of entries) {
          if (entry.isFile() && entry.name !== 'SKILL.md') {
            linkedFiles.push(entry.name);
          }
        }
      } catch (err) {
        /* ignore */
      }

      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(
        JSON.stringify({
          content,
          rawContent,
          frontmatter,
          linkedFiles,
        })
      );
    } catch (err) {
      this.sendError(res, err);
    }
  }

