  /**
   * 澶勭悊 MCP 甯傚満鎼滅储璇锋眰 GET /v1/mcp/marketplace/search?query=xx&category=xx
   */
  private async handleMCPMarketplaceSearch(
    req: http.IncomingMessage,
    res: http.ServerResponse
  ): Promise<void> {
    try {
      const parsedUrl = new URL(
        req.url!,
        `http://${req.headers.host || 'localhost'}`
      );
      const query = parsedUrl.searchParams.get('query') || '';
      const category = parsedUrl.searchParams.get('category') || undefined;
      const registry = parsedUrl.searchParams.get('registry') as
        | RegistryType
        | undefined;
      const sourceRegistry = parsedUrl.searchParams.get('sourceRegistry') as
        | ThirdPartyRegistry
        | undefined;

      const { mcpSystem } = await import('@modules/services/mcp');

      if (!mcpSystem || !mcpSystem.marketplace) {
        res.writeHead(503, {
          'Content-Type': 'application/json; charset=utf-8',
        });
        res.end(JSON.stringify({ error: { message: 'MCP 甯傚満鏈嶅姟鏈垵濮嬪寲' } }));
        return;
      }

      const results = await mcpSystem.marketplace.search({
        query,
        category,
        registry,
        sourceRegistry,
      });

      if (!results || !Array.isArray(results)) {
        res.writeHead(200, {
          'Content-Type': 'application/json; charset=utf-8',
        });
        res.end(JSON.stringify([]));
        return;
      }

      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(JSON.stringify(results));
    } catch (err) {
      await handleError(err, {
        module: 'infra:http',
        action: 'mcp_marketplace_search',
      });
      res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(
        JSON.stringify({
          error: {
            message: '鎼滅储澶辫触',
            detail: err instanceof Error ? err.message : String(err),
          },
        })
      );
    }
  }

