  /**
   * 澶勭悊楠岃瘉 MCP 鏈嶅姟鍣ㄨ繛鎺?POST /v1/mcp/servers/:serverId/verify
   */
  private async handleMCPVerifyServer(
    req: http.IncomingMessage,
    res: http.ServerResponse,
    serverId: string
  ): Promise<void> {
    try {
      const { getMCPServerManager } =
        await import('@modules/services/mcp/MCPServerManager');
      const { mcpSystem } = await import('@modules/services/mcp');

      const manager = getMCPServerManager();
      const detail = mcpSystem.marketplace.getInstalledServerDetail(serverId);

      if (!detail.metadata) {
        res.writeHead(404, { 'Content-Type': 'application/json' });
        res.end(
          JSON.stringify({
            success: false,
            error: `鏈嶅姟鍣?"${serverId}" 鏈畨瑁卄,
          })
        );
        return;
      }

      const server = manager.getServer(serverId);
      if (!server) {
        res.writeHead(200, {
          'Content-Type': 'application/json; charset=utf-8',
        });
        res.end(
          JSON.stringify({
            success: false,
            connected: false,
            status: 'not_found',
          })
        );
        return;
      }

      // 灏濊瘯杩炴帴
      const wasConnected = detail.connected;
      const success = await server.connect();

      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(
        JSON.stringify({
          success,
          connected: success,
          status: success ? 'connected' : 'failed',
          wasConnected,
        })
      );
    } catch (err) {
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(
        JSON.stringify({
          success: false,
          connected: false,
          status: 'error',
          error: err instanceof Error ? err.message : String(err),
        })
      );
    }
  }

  /**
   * 澶勭悊鍒楀嚭鎵€鏈?MCP 宸ュ叿 GET /v1/mcp/tools
   */
  private async handleMCPListTools(
    req: http.IncomingMessage,
    res: http.ServerResponse
  ): Promise<void> {
    try {
      const { getMCPServerManager } =
        await import('@modules/services/mcp/MCPServerManager');
      const { mcpSystem } = await import('@modules/services/mcp');
      const manager = getMCPServerManager();
      const serverInfos = manager.getServerInfos();

      const tools: Array<{
        name: string;
        description: string;
        server: string;
        inputSchema: Record<string, unknown>;
        enabled: boolean;
      }> = [];

      for (const info of serverInfos) {
        for (const tool of info.tools || []) {
          const enabled = !mcpSystem.marketplace.isToolDisabled(
            info.name,
            tool.name
          );
          tools.push({
            name: tool.name,
            description: tool.description || '',
            server: info.name,
            inputSchema: (tool.inputSchema as Record<string, unknown>) || {},
            enabled,
          });
        }
      }

      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(JSON.stringify({ tools, total: tools.length }));
    } catch (err) {
      this.sendError(res, err);
    }
  }

