export async function startCompileScheduler(): Promise<{
  stop: () => void;
} | null> {
  try {
    const { aiService } = await import('@modules/ai/services/aiService');
    const defaultModel = aiService.getDefaultModel();
    if (!defaultModel) {
      logger.warning(
        '鐭ヨ瘑搴撶紪璇戣皟搴﹀櫒璺宠繃棣栨缂栬瘧锛氭湭閰嶇疆榛樿妯″瀷锛岃皟搴﹀櫒浠嶆寜鍛ㄦ湡杩愯'
      );
    }

    const { runKnowledgeCompile } =
      await import('@modules/knowledge/KnowledgeCompiler');
    const { KnowledgeCompileScheduler } =
      await import('@modules/knowledge/KnowledgeCompileScheduler');
    const scheduler = new KnowledgeCompileScheduler(
      (force?: boolean) =>
        runKnowledgeCompile(aiService, {
          force,
          model: defaultModel || undefined,
        }),
      { runOnStart: !!defaultModel }
    );
    scheduler.start();
    return scheduler;
  } catch (err) {
    logger.warning('鐭ヨ瘑搴撶紪璇戣皟搴﹀櫒鍒濆鍖栧け璐ワ紙闈炲叧閿敊璇級', {
      error: String(err),
    });
    return null;
  }
}

/**
 * 灏濊瘯鍔ㄦ€佹敞鍐屾湭娉ㄥ唽鐨勯€氶亾锛堝墠绔彁渚涘嚟鎹椂鑷姩娉ㄥ唽锛塡n * 瑕嗙洊鍏ㄩ儴 26 涓€氶亾锛岄€氳繃 CHANNEL_TABLE 琛ㄩ┍鍔╘n */
export async function tryDynamicRegister(
  channelType: string,
  config?: Record<string, unknown>
): Promise<boolean> {
  const entry = getChannelEntry(channelType);
  if (!entry) return false;

  try {
    // 鍔ㄦ€佸鍏ユ彃浠舵ā鍧梊n    const mod = await import(entry.importPath);
    const plugin = (mod as Record<string, unknown>)[entry.exportKey] as
      | IChannelPlugin
      | undefined;
    if (!plugin) {
      logger.warning(
        `tryDynamicRegister: 鏈壘鍒版彃浠跺鍑?鈥?${channelType}/${entry.exportKey}`
      );
      return false;
    }

    // 1. 娉ㄥ唽鍒?ChannelRegistry
    const { channelRegistry } =
      await import('@modules/channels/registry/ChannelRegistry');
    const { adaptPluginToInterface } =
      await import('@modules/channels/registry/ChannelRegistry');
    channelRegistry.register(adaptPluginToInterface(plugin));

    // 2. 娉ㄥ唽鍒?ChannelBootstrapper
    const { channelBootstrapper } =
      await import('../../channels/bootstrap/ChannelBootstrapper');
    channelBootstrapper.registerPluginChannel(channelType, () => plugin);

    // 3. 鍐欏叆閰嶇疆锛堝悎骞跺墠绔紶鍏ョ殑鍑嵁锛塡n    channelRegistry.updateConfig(channelType, {
      name: entry.name,
      enabled: false,
      options: {
        ...(channelRegistry.getConfig(channelType)?.options || {}),
        ...(config || {}),
      },
    });

    // 4. 缁戝畾鍏ョ珯娑堟伅澶勭悊鍣╘n    bindInboundMessageHandler(channelType, plugin);

    return true;
  } catch (err) {
    logger.error(`tryDynamicRegister(${channelType}) 澶辫触`, {
      error: String(err),
    });
    return false;
  }
}

/** 缁戝畾鍏ョ珯娑堟伅 鈫?AI 鈫?鍑虹珯 鍥炶矾 */
function bindInboundMessageHandler(
  channelType: string,
  plugin: IChannelPlugin
): void {
  if (!plugin.inbound) return;

  const _processingMessages = new Set<string>();

  plugin.inbound.setMessageHandler(
    async (message: import('@modules/channels/types').MessageContext) => {
      if (_processingMessages.has(message.messageId)) return;
      _processingMessages.add(message.messageId);

      try {
        const sender = message.senderName || message.senderId || 'unknown';
        const label = channelType.toUpperCase();
        console.log(`\n鈹€鈹€ [${label}] ${sender} 鈹€鈹€`);
        console.log(message.content);

        const coreAPI = getCoreAPI();
        const response = await coreAPI.chat({
          content: message.content,
          sessionId: message.conversationId ?? message.senderId,
          metadata: {
            channel: message.channelId,
            sender: message.senderId,
            messageType: message.messageType,
            isDirectMessage: message.isDirectMessage,
            rawPayload: message.rawPayload,
          },
        });

        if (response.content && plugin.outbound) {
          console.log(`\n鈹€鈹€ [${label}] Liri 鈹€鈹€`);
          console.log(response.content);
          console.log('');

          await plugin.outbound.sendText(
            message.conversationId ?? message.senderId,
            response.content
          );
        }
      } catch (error) {
        await handleError(error, {
          module: 'infra:http',
          action: 'channel_inbound_message',
          context: { channelType, messageId: message.messageId },
        });
      } finally {
        setTimeout(() => {
          _processingMessages.delete(message.messageId);
        }, 3000);
      }
    }
  );
  logger.info(`[${channelType}] 鍏ョ珯娑堟伅澶勭悊鍣ㄥ凡缁戝畾`);
}

/**
 * 閫掑綊澶嶅埗鐩綍
 * 璺宠繃杩佺Щ鏍囪鏂囦欢锛?migrating, .migration_committed锛塡n */
export function copyDirectory(
  src: string,
  dest: string,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  fs: any,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  path: any
): { copied: number; skipped: number; errors: string[] } {
  let copied = 0;
  let skipped = 0;
  const errors: string[] = [];

  if (!fs.existsSync(src)) {
    return { copied, skipped, errors };
  }

  if (!fs.existsSync(dest)) {
    fs.mkdirSync(dest, { recursive: true });
  }

  const entries = fs.readdirSync(src, { withFileTypes: true });

  for (const entry of entries) {
    if (entry.name === '.migrating' || entry.name === '.migration_committed') {
      continue;
    }
    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);

    try {
      if (entry.isDirectory()) {
        const result = copyDirectory(srcPath, destPath, fs, path);
        copied += result.copied;
        skipped += result.skipped;
        errors.push(...result.errors);
      } else {
        if (!fs.existsSync(destPath)) {
          fs.copyFileSync(srcPath, destPath);
          copied++;
        } else {
          skipped++;
        }
      }
    } catch (err) {
      errors.push(`澶嶅埗 ${srcPath} 澶辫触: ${(err as Error).message}`);
    }
  }

  return { copied, skipped, errors };
}

/**
 * 缂栨帓鍘嗗彶閫傞厤鍣╘n *
 * 璁㈤槄 globalEventBus 涓婄殑缂栨帓浜嬩欢锛屼互 append-only JSONL 鏍煎紡
 * 鎸佷箙鍖栧埌 .liri/workitems/<itemId>_orchestration_history.jsonl銆俓n * 渚涘墠绔巻鍙插洖鏀句娇鐢ㄣ€俓n *
 * 姣忎釜浜嬩欢璁板綍鏍煎紡锛歕n * { "eventId": "uuid", "eventType": "orch:*", "payload": {}, "timestamp": 1234567890 }
 */

import { existsSync, mkdirSync, appendFileSync, readFileSync } from 'fs';
import { join } from 'path';
import { randomUUID } from 'crypto';
import { globalEventBus } from '../../../core/events/EventBus.js';
import { OrchestrationEventType } from '../../../agent/events/OrchestrationEvents.js';
import { AgentEventType } from '../../../agent/events/types.js';
import { Logger, LogLevel } from '@modules/monitoring';

const logger = new Logger({ module: 'http:orchHistory', level: LogLevel.INFO });

/** 缂栨帓鍘嗗彶浜嬩欢璁板綍 */
export interface OrchestrationHistoryRecord {
  /** 鍏ㄥ眬鍞竴浜嬩欢 ID */
  eventId: string;
  /** 浜嬩欢绫诲瀷 */
  eventType: string;
  /** 浜嬩欢杞借嵎 */
  payload: unknown;
  /** 浜嬩欢鏃堕棿鎴筹紙姣锛?*/
  timestamp: number;
}

/** 鍘嗗彶鏌ヨ缁撴灉 */
export interface OrchestrationHistoryQueryResult {
  /** 浜嬩欢鍒楄〃 */
  events: OrchestrationHistoryRecord[];
  /** 鏄惁杩樻湁鏇村 */
  hasMore: boolean;
  /** 鏈€鏂颁簨浠舵椂闂存埑 */
  latestTimestamp: number;
}

/** 闇€瑕佽褰曠殑缂栨帓浜嬩欢绫诲瀷鍒楄〃 */
const RECORDED_EVENT_TYPES: ReadonlySet<string> = new Set([
  OrchestrationEventType.COUNCIL_START,
  OrchestrationEventType.COUNCIL_ROUND_START,
  OrchestrationEventType.COUNCIL_AGENT_SPEAKING,
  OrchestrationEventType.COUNCIL_AGENT_DELTA,
  OrchestrationEventType.COUNCIL_ROUND,
  OrchestrationEventType.COUNCIL_END,
  OrchestrationEventType.COUNCIL_DETAIL,

  OrchestrationEventType.ORCH_START,
  OrchestrationEventType.ORCH_TASK_START,
  OrchestrationEventType.ORCH_TASK_PROGRESS,
  OrchestrationEventType.ORCH_TASK_END,
  OrchestrationEventType.ORCH_STEP_START,
  OrchestrationEventType.ORCH_STEP_DELTA,
  OrchestrationEventType.ORCH_STEP_COMPLETED,
  OrchestrationEventType.ORCH_END,

  OrchestrationEventType.PLAN_START,
  OrchestrationEventType.PLAN_STEP_START,
  OrchestrationEventType.PLAN_STEP_COMPLETED,
  OrchestrationEventType.PLAN_PROGRESS,
  OrchestrationEventType.PLAN_COMPLETED,

  OrchestrationEventType.CHAIN_START,
  OrchestrationEventType.CHAIN_STEP,
  OrchestrationEventType.CHAIN_END,

  OrchestrationEventType.SWARM_DISPATCH,
  OrchestrationEventType.SWARM_AGENT_STATUS,
  OrchestrationEventType.SWARM_COMPLETE,

  AgentEventType.THINKING_START,
  AgentEventType.THINKING_DELTA,
  AgentEventType.THINKING_END,
  AgentEventType.TOOL_CALL_START,
  AgentEventType.TOOL_CALL_DELTA,
  AgentEventType.TOOL_CALL_END,
]);

/** JSONL 鏂囦欢鍚嶅悗缂€ */
const HISTORY_FILE_SUFFIX = '_orchestration_history.jsonl';

/**
 * 缂栨帓鍘嗗彶閫傞厤鍣╘n *
 * 璁㈤槄 globalEventBus 骞舵寔涔呭寲缂栨帓浜嬩欢鍒?JSONL 鏂囦欢锛孿n * 鍚屾椂鎻愪緵鍘嗗彶鏌ヨ鑳藉姏銆俓n */
export class OrchestrationHistoryAdapter {
  /** 姣忎釜 item 瀵瑰簲鐨勬枃浠惰矾寰?*/
  private filePaths = new Map<string, string>();

  /** 璁㈤槄鍒楄〃 */
  private subscriptions: Array<{ unsubscribe: () => void }> = [];

  /** 鏄惁宸插惎鍔?*/
  private started = false;

  /**
   * 鍚姩鍘嗗彶璁板綍
   *
   * 璁㈤槄鎵€鏈夌紪鎺掍簨浠剁被鍨嬶紝鍐欏叆鍘嗗彶鏂囦欢銆俓n   */
  start(liriDir: string): void {
    if (this.started) return;
    this.started = true;

    const itemDir = join(liriDir, 'workitems');
    if (!existsSync(itemDir)) {
      mkdirSync(itemDir, { recursive: true });
    }

    // 璁㈤槄鎵€鏈夐渶瑕佽褰曠殑浜嬩欢绫诲瀷
    for (const eventType of RECORDED_EVENT_TYPES) {
      const sub = globalEventBus.subscribe(eventType, (payload: unknown) => {
        // 浠?payload 涓彁鍙?itemId锛堝悇浜嬩欢鍙兘鍦ㄤ笉鍚屽瓧娈碉級
        const itemId = this.extractItemId(payload, eventType);
        if (!itemId) return; // 鏃犳硶纭畾 itemId 鐨勪簨浠惰烦杩嘰n
        this.appendRecord(itemDir, itemId, {
          eventId: randomUUID(),
          eventType,
          payload,
          timestamp: Date.now(),
        });
      });
      this.subscriptions.push(sub);
    }

    logger.info('缂栨帓鍘嗗彶閫傞厤鍣ㄥ凡鍚姩');
  }

  /**
   * 鍋滄鍘嗗彶璁板綍锛屾竻鐞嗘墍鏈夎闃匼n   */
  stop(): void {
    for (const sub of this.subscriptions) {
      sub.unsubscribe();
    }
    this.subscriptions = [];
    this.started = false;
    this.filePaths.clear();
    logger.info('缂栨帓鍘嗗彶閫傞厤鍣ㄥ凡鍋滄');
  }

  /**
   * 鏌ヨ缂栨帓鍘嗗彶
   *
   * @param itemDir 宸ヤ綔椤瑰瓨鍌ㄧ洰褰昞n   * @param itemId 宸ヤ綔椤?ID
   * @param since 鍙€夛紝鍙繑鍥炶鏃堕棿鎴充箣鍚庣殑浜嬩欢
   * @param limit 鍙€夛紝鏈€澶ц繑鍥炴潯鏁帮紙榛樿 100锛塡n   */
  query(
    itemDir: string,
    itemId: string,
    since?: number,
    limit: number = 100
  ): OrchestrationHistoryQueryResult {
    const filePath = join(itemDir, `${itemId}${HISTORY_FILE_SUFFIX}`);

    if (!existsSync(filePath)) {
      return { events: [], hasMore: false, latestTimestamp: 0 };
    }

    try {
      const content = readFileSync(filePath, 'utf-8');
      const lines = content.trim().split('\n');

      // 浠庡悗寰€鍓嶈В鏋愶紝鍙栨渶鏂扮殑 limit 鏉n      const records: OrchestrationHistoryRecord[] = [];

      for (let i = lines.length - 1; i >= 0; i--) {
        const line = lines[i].trim();
        if (!line) continue;

        try {
          const record = JSON.parse(line) as OrchestrationHistoryRecord;
          if (since !== undefined && record.timestamp <= since) continue;
          records.unshift(record);
          if (records.length >= limit) break;
        } catch (err) {
          // 璺宠繃鎹熷潖鐨勮
        }
      }

      const latestTimestamp =
        records.length > 0 ? records[records.length - 1].timestamp : 0;

      return {
        events: records,
        hasMore: records.length >= limit,
        latestTimestamp,
      };
    } catch (err) {
      return { events: [], hasMore: false, latestTimestamp: 0 };
    }
  }

  /**
   * 鑾峰彇鍘嗗彶鏂囦欢璺緞
   */
  getHistoryFilePath(itemDir: string, itemId: string): string {
    return join(itemDir, `${itemId}${HISTORY_FILE_SUFFIX}`);
  }

  // ========== 绉佹湁鏂规硶 ==========

  /**
   * 杩藉姞涓€鏉¤褰曞埌鍘嗗彶鏂囦欢
   */
  private appendRecord(
    itemDir: string,
    itemId: string,
    record: OrchestrationHistoryRecord
  ): void {
    const filePath = this.getHistoryFilePath(itemDir, itemId);

    try {
      appendFileSync(filePath, JSON.stringify(record) + '\n', 'utf-8');
    } catch (err) {
      logger.warn('鍐欏叆缂栨帓鍘嗗彶澶辫触', {
        itemId,
        eventType: record.eventType,
        error: String(err),
      });
    }
  }

  /**
   * 浠庝簨浠?payload 涓彁鍙?itemId
   *
   * 涓嶅悓浜嬩欢绫诲瀷鐨?payload 涓?itemId/workspaceItemId 瀛楁鍚嶄笉鍚岋紝
   * 缁熶竴灏濊瘯澶氫釜鍙兘鐨勫瓧娈靛悕銆俓n   */
  private extractItemId(payload: unknown, _eventType: string): string | null {
    if (!payload || typeof payload !== 'object') return null;

    const obj = payload as Record<string, unknown>;

    // 灏濊瘯甯歌瀛楁鍚峔n    const possibleKeys = [
      'workItemId',
      'itemId',
      'workspaceItemId',
      'sessionId',
    ];

    for (const key of possibleKeys) {
      const val = obj[key];
      if (typeof val === 'string' && val.length > 0) {
        return val;
      }
    }

    return null;
  }
}

