 */
export async function handleListAgentRoles(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const store = getAgentRoleStore();
    const roles = await store.listAll();
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(roles));
  } catch (err) {
    ctx.sendError(res, err);
  }
}

/**
 * GET /v1/agent-roles/:agentId
 * 鏌ヨ鍗曚釜 Agent 瑙掕壊
 */
export async function handleGetAgentRole(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  agentId: string
): Promise<void> {
  try {
    const store = getAgentRoleStore();
    const role = await store.getByAgentId(agentId);
    if (!role) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Agent 瑙掕壊涓嶅瓨鍦? }));
      return;
    }
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(role));
  } catch (err) {
    ctx.sendError(res, err);
  }
}

/**
 * POST /v1/agent-roles
 * 鍒涘缓 Agent 瑙掕壊
 */
export async function handleCreateAgentRole(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const body = await ctx.readRequestBody(req);
    const data = JSON.parse(body);

    if (!data.agentId || !data.name) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: '缂哄皯蹇呰鍙傛暟锛歛gentId, name' }));
      return;
    }

    const store = getAgentRoleStore();
    const id = await store.insert({
      agentId: data.agentId,
      name: data.name,
      expertise: data.expertise || [],
      weight: data.weight ?? 1.0,
      systemPrompt: data.systemPrompt || '',
      icon: data.icon || '馃',
      sortOrder: data.sortOrder ?? 0,
      enabled: data.enabled !== false,
    });

    res.writeHead(201, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ id, message: 'Agent 瑙掕壊鍒涘缓鎴愬姛' }));
  } catch (err) {
    ctx.sendError(res, err);
  }
}

/**
 * PUT /v1/agent-roles/:agentId
 * 鏇存柊 Agent 瑙掕壊
 */
export async function handleUpdateAgentRole(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  agentId: string
): Promise<void> {
  try {
    const body = await ctx.readRequestBody(req);
    const data = JSON.parse(body);

    const store = getAgentRoleStore();
    const existing = await store.getByAgentId(agentId);
    if (!existing) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Agent 瑙掕壊涓嶅瓨鍦? }));
      return;
    }

    await store.update(existing.id!, {
      name: data.name,
      expertise: data.expertise,
      weight: data.weight,
      systemPrompt: data.systemPrompt,
      icon: data.icon,
      sortOrder: data.sortOrder,
      enabled: data.enabled,
    });

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ message: 'Agent 瑙掕壊鏇存柊鎴愬姛' }));
  } catch (err) {
    ctx.sendError(res, err);
  }
}

/**
 * DELETE /v1/agent-roles/:agentId
 * 鍒犻櫎 Agent 瑙掕壊
 */
export async function handleDeleteAgentRole(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  agentId: string
): Promise<void> {
  try {
    const store = getAgentRoleStore();
    const existing = await store.getByAgentId(agentId);
    if (!existing) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Agent 瑙掕壊涓嶅瓨鍦? }));
      return;
    }

    await store.delete(existing.id!);

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ message: 'Agent 瑙掕壊鍒犻櫎鎴愬姛' }));
  } catch (err) {
    ctx.sendError(res, err);
  }
}

