import type http from 'http';
import { sendError, readRequestBody } from './handler-utils';

import { Logger, LogLevel } from '@modules/monitoring';
const logger = new Logger({
  module: 'infrastructure:http:handlers:auth-handlers',
  level: LogLevel.INFO,
});

const users = new Map<string, { username: string; password: string }>();
const tokens = new Map<string, { username: string; permissions: string[] }>();

// ========== Auth Handlers ==========

/**
 * 鐢ㄦ埛鐧诲綍 POST /v1/auth/login
 */
export async function handleAuthLogin(
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const body = await readRequestBody(req);
    const { username, password } = JSON.parse(body);

    if (!username || !password) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({
          error: { message: 'username and password are required' },
        })
      );
      return;
    }

    const user = users.get(username);
    if (!user || user.password !== password) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({
          error: { message: 'Invalid username or password' },
        })
      );
      return;
    }

    const token = `token_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    tokens.set(token, {
      username,
      permissions: ['read', 'write'],
    });

    const now = Date.now();
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(
      JSON.stringify({
        token,
        user: {
          id: `user_${now}`,
          username,
          email: '',
          role: 'user',
          trustLevel: 2,
          created_at: now,
        },
        expires_at: now + 86400000,
      })
    );
  } catch (err) {
    sendError(res, err);
  }
}

/**
 * 鐢ㄦ埛娉ㄥ唽 POST /v1/auth/register
 */
export async function handleAuthRegister(
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const body = await readRequestBody(req);
    const { username, password } = JSON.parse(body);

    if (!username || !password) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({
          error: { message: 'username and password are required' },
        })
      );
      return;
    }

    if (users.has(username)) {
      res.writeHead(409, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({
          error: { message: 'Username already exists' },
        })
      );
      return;
    }

    users.set(username, { username, password });
    const token = `token_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    tokens.set(token, {
      username,
      permissions: ['read', 'write'],
    });

    const now = Date.now();
    res.writeHead(201, { 'Content-Type': 'application/json' });
    res.end(
      JSON.stringify({
        token,
        user: {
          id: `user_${now}`,
          username,
          email: '',
          role: 'user',
          trustLevel: 2,
          created_at: now,
        },
        expires_at: now + 86400000,
      })
    );
  } catch (err) {
    sendError(res, err);
  }
}

/**
 * 鐢ㄦ埛鐧诲嚭 POST /v1/auth/logout
 */
export async function handleAuthLogout(
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const authHeader = req.headers['authorization'] || '';
    const token = authHeader.replace('Bearer ', '');

    if (token) {
      tokens.delete(token);
    }

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({}));
  } catch (err) {
    sendError(res, err);
  }
}

/**
 * 鑾峰彇褰撳墠鐢ㄦ埛淇℃伅 GET /v1/auth/me
 */
export async function handleAuthMe(
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const authHeader = req.headers['authorization'] || '';
    const token = authHeader.replace('Bearer ', '');

    const session = tokens.get(token);
    if (!session) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: { message: 'Not authenticated' } }));
      return;
    }

    const now = Date.now();
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(
      JSON.stringify({
        id: `user_${now}`,
        username: session.username,
        email: '',
        role: 'user',
        trustLevel: 2,
        created_at: now,
        permissions: session.permissions,
      })
    );
  } catch (err) {
    sendError(res, err);
  }
}

/**
 * 鑾峰彇褰撳墠鐢ㄦ埛鏉冮檺鍒楄〃 GET /v1/auth/permissions
 */
export async function handleAuthPermissions(
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const authHeader = req.headers['authorization'] || '';
    const token = authHeader.replace('Bearer ', '');

    const session = tokens.get(token);
    if (!session) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: { message: 'Not authenticated' } }));
      return;
    }

    const permissionList = session.permissions.map((p: string) => ({
      scope: p === 'read' ? 'read' : p === 'write' ? 'write' : 'admin',
      description:
        p === 'read' ? '璇诲彇鏉冮檺' : p === 'write' ? '鍐欏叆鏉冮檺' : '绠＄悊鏉冮檺',
      level: p as 'none' | 'read' | 'write' | 'admin',
    }));

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(permissionList));
  } catch (err) {
    sendError(res, err);
  }
}

