/**
 * 鑾峰彇鎴愭湰鎶ュ憡
 * GET /v1/workspaces/:id/cost/report
 *
 * 鏁村悎鐜版湁 costTracker 鍜?costBudgetManager 鏁版嵁
 */
export async function handleWorkspaceCostReport(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  workspaceId: string
): Promise<void> {
  try {
    const wsPath = await resolveWorkspacePath(workspaceId);
    if (!wsPath) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: { message: 'Workspace not found' } }));
      return;
    }

    // 浠庣幇鏈?costTracker 鑾峰彇鎴愭湰鏁版嵁
    let totalCostUSD = 0;
    let totalInputTokens = 0;
    let totalOutputTokens = 0;
    const modelBreakdown: Record<
      string,
      { model: string; costUSD: number; tokens: number; requestCount: number }
    > = {};

    try {
      const { costTracker } = await import('@modules/cost/CostTracker');
      totalCostUSD = costTracker.getTotalCostUSD();
      totalInputTokens = costTracker.getTotalInputTokens();
      totalOutputTokens = costTracker.getTotalOutputTokens();

      const modelUsage = costTracker.getModelUsage();
      // modelUsage is Record<string, ModelUsage>, iterate with Object.entries
      for (const [model, usage] of Object.entries(modelUsage)) {
        modelBreakdown[model] = {
          model,
          costUSD: usage.costUSD,
          tokens: (usage.inputTokens || 0) + (usage.outputTokens || 0),
          requestCount: 0,
        };
      }
    } catch (err) {
      logger.warn('costTracker 涓嶅彲鐢紝杩斿洖绌烘姤鍛?);
    }

    // 浠?costBudgetManager 鑾峰彇棰勭畻鐘舵€乗n    let budgetStatus: 'ok' | 'warning' | 'exceeded' = 'ok';
    let budgetUtilization = 0;

    try {
      const { costBudgetManager } =
        await import('@modules/cost/CostBudgetManager');
      const statuses = costBudgetManager.getAllBudgetStatuses();
      if (statuses.length > 0) {
        // 浣跨敤绗竴涓惎鐢ㄧ殑棰勭畻鐘舵€乗n        const monthlyStatus = statuses.find(
          (s: { budgetId: string }) => s.budgetId === 'monthly-budget'
        );
        const primary = monthlyStatus || statuses[0];
        if (primary.status === 'exceeded') {
          budgetStatus = 'exceeded';
        } else if (primary.status === 'warning') {
          budgetStatus = 'warning';
        }
        budgetUtilization = primary.percentageUsed / 100;
      }
    } catch (err) {
      // budgetManager 鍙兘鏈厤缃甛n    }

    const report: CostReport = {
      id: `cost_${Date.now()}`,
      workspaceId,
      totalCostUSD,
      totalTokens: totalInputTokens + totalOutputTokens,
      inputTokens: totalInputTokens,
      outputTokens: totalOutputTokens,
      modelBreakdown,
      budgetStatus,
      budgetUtilization,
      generatedAt: new Date().toISOString(),
      period: 'total',
    };

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(report));
  } catch (err) {
    await handleError(err, { module: 'infra:http', action: 'cost_report' });
    if (!res.headersSent) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({ error: { message: 'Failed to get cost report' } })
      );
    }
  }
}

/**
 * 鑾峰彇棰勭畻鐘舵€乗n * GET /v1/workspaces/:id/cost/budget
 */
export async function handleWorkspaceBudgetStatus(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  workspaceId: string
): Promise<void> {
  try {
    const wsPath = await resolveWorkspacePath(workspaceId);
    if (!wsPath) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: { message: 'Workspace not found' } }));
      return;
    }

    let budgetInfo: {
      status: 'ok' | 'warning' | 'exceeded';
      currentCost: number;
      limit: number;
      remaining: number;
      percentageUsed: number;
    } = {
      status: 'ok',
      currentCost: 0,
      limit: 0,
      remaining: 0,
      percentageUsed: 0,
    };

    try {
      const { costBudgetManager } =
        await import('@modules/cost/CostBudgetManager');
      const statuses = costBudgetManager.getAllBudgetStatuses();
      if (statuses.length > 0) {
        const monthlyStatus = statuses.find(
          (s: { budgetId: string }) => s.budgetId === 'monthly-budget'
        );
        const primary = monthlyStatus || statuses[0];
        budgetInfo = {
          status:
            primary.status === 'exceeded'
              ? 'exceeded'
              : primary.status === 'warning'
                ? 'warning'
                : 'ok',
          currentCost: primary.currentCost,
          limit: primary.limit,
          remaining: primary.remaining,
          percentageUsed: primary.percentageUsed,
        };
      }
    } catch (err) {
      logger.warn('costBudgetManager 涓嶅彲鐢?);
    }

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(budgetInfo));
  } catch (err) {
    await handleError(err, { module: 'infra:http', action: 'budget_status' });
    if (!res.headersSent) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({ error: { message: 'Failed to get budget status' } })
      );
    }
  }
}

/**
 * Council HTTP 澶勭悊鍣╘n *
 * 鎻愪緵 Agent Council 鐨?REST API 鍜?SSE 娴佸紡鎺ㄩ€佺鐐癸細
 * - POST /v1/workspace/:id/council  鍒涘缓 Council 浼氳瘽骞跺紑濮嬭京璁篭n * - GET  /v1/workspace/:id/council/:sessionId  鑾峰彇浼氳瘽鐘舵€乗n * - GET  /v1/workspace/:id/council/:sessionId/stream  SSE 娴佸紡璁㈤槄杈╄杩囩▼
 * - GET  /v1/workspace/:id/council 鍒楀嚭鎵€鏈夋椿璺冧細璇漒n * - POST /v1/workspace/:id/council/:sessionId/statement  鎻愪氦 AI 鍙戣█
 */

import type http from 'http';
import { randomUUID } from 'crypto';
import { Logger, LogLevel } from '@modules/monitoring';
import type { HandlerCtx } from './handler-utils';
import {
  getCouncilEngine,
  setCouncilEmitter,
} from '@modules/workspace/CouncilEngine';
import type { CouncilStreamEvent } from '@modules/workspace/CouncilTypes';
import { CouncilOrchestrator } from '@modules/workspace/CouncilOrchestrator';

const logger = new Logger({ module: 'CouncilHandlers', level: LogLevel.INFO });

/** SSE 瀹㈡埛绔繛鎺ユ睜 */
const sseClients = new Map<string, Set<http.ServerResponse>>();

// 鍒濆鍖栵細缁戝畾 emit 鍥炶皟鍒?SSE 杩炴帴姹燶nsetCouncilEmitter((event: CouncilStreamEvent) => {
  const clients = sseClients.get(event.sessionId);
  if (clients) {
    const data = `data: ${JSON.stringify(event)}\n\n`;
    for (const res of clients) {
      res.write(data);
    }
  }
});

/** 娉ㄥ唽 SSE 瀹㈡埛绔?*/
function registerSSEClient(sessionId: string, res: http.ServerResponse): void {
  if (!sseClients.has(sessionId)) {
    sseClients.set(sessionId, new Set());
  }
  sseClients.get(sessionId)!.add(res);
}

/** 娉ㄩ攢 SSE 瀹㈡埛绔?*/
function unregisterSSEClient(
  sessionId: string,
  res: http.ServerResponse
): void {
  const clients = sseClients.get(sessionId);
  if (clients) {
    clients.delete(res);
    if (clients.size === 0) {
      sseClients.delete(sessionId);
    }
  }
}

/**
 * POST /v1/workspace/:id/council
 * 鍒涘缓 Council 浼氳瘽
 */
export async function handleCreateCouncil(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  workspaceId: string
): Promise<void> {
  try {
    const body = await ctx.readRequestBody(req);
    const data = JSON.parse(body);
    const { topic, context, agents, maxRounds } = data;

    if (
      !topic ||
      !context ||
      !agents ||
      !Array.isArray(agents) ||
      agents.length < 2
    ) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({
          error: '缂哄皯蹇呰鍙傛暟锛歵opic, context, agents锛堣嚦灏?2 涓?Agent锛?,
        })
      );
      return;
    }

    const engine = getCouncilEngine();

    const session = engine.createSession(workspaceId, topic, context, agents, {
      maxRounds: maxRounds ?? 3,
    });

    // 绗?1 姝ワ細绔嬪嵆杩斿洖 sessionId锛堜笉绛夊緟杈╄瀹屾垚锛塡n    res.writeHead(201, { 'Content-Type': 'application/json' });
    res.end(
      JSON.stringify({
        sessionId: session.sessionId,
        status: 'debating',
      })
    );

    // 绗?2 姝ワ細寮傛鎵ц杈╄锛堜笉闃诲 HTTP 鍝嶅簲锛塡n    const orchestrator = new CouncilOrchestrator(engine);
    orchestrator.runDebate(session.sessionId).catch((err) => {
      logger.error('Council 杈╄鎵ц澶辫触', { error: String(err) });
    });
  } catch (err) {
    logger.error('鍒涘缓 Council 浼氳瘽澶辫触', { error: String(err) });
    if (!res.headersSent) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: '鍒涘缓 Council 浼氳瘽澶辫触' }));
    }
  }
}

