/**
 * GET /v1/workspace/:id/council/:sessionId/stream
 * SSE 娴佸紡璁㈤槄杈╄杩囩▼
 */
export function handleCouncilStream(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  sessionId: string
): void {
  const engine = getCouncilEngine();
  const session = engine.getSession(sessionId);

  if (!session) {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Council 浼氳瘽涓嶅瓨鍦? }));
    return;
  }

  // 璁剧疆 SSE 澶碶n  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    Connection: 'keep-alive',
    'X-Accel-Buffering': 'no',
  });

  // 鍙戦€佸垵濮嬭繛鎺ョ‘璁n  res.write(`data: ${JSON.stringify({ type: 'connected', sessionId })}\n\n`);

  registerSSEClient(sessionId, res);

  // 濡傛灉浼氳瘽宸叉湁鍘嗗彶鍙戣█锛屽洖鏀剧粰瀹㈡埛绔痋n  for (const statement of session.statements) {
    res.write(
      `data: ${JSON.stringify({
        type: 'statement',
        sessionId,
        phase: session.phase,
        round: statement.round,
        statement,
        timestamp: statement.timestamp,
      })}\n\n`
    );
  }

  // 濡傛灉浼氳瘽宸插畬鎴愶紝鍙戦€佸畬鎴愪簨浠禱n  if (session.phase === 'completed') {
    res.write(
      `data: ${JSON.stringify({
        type: 'council_completed',
        sessionId,
        phase: 'completed',
        finalProposal: session.finalProposal,
        timestamp: Date.now(),
      })}\n\n`
    );
    res.end();
    unregisterSSEClient(sessionId, res);
    return;
  }

  // 瀹㈡埛绔柇寮€鏃舵竻鐞哱n  req.on('close', () => {
    unregisterSSEClient(sessionId, res);
  });
}

