/**
 * POST /v1/workspace/:id/council/:sessionId/statement
 * 鎻愪氦 AI 鍙戣█鍒?Council 杈╄
 */
export async function handleSubmitStatement(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  sessionId: string
): Promise<void> {
  try {
    const body = await ctx.readRequestBody(req);
    const data = JSON.parse(body);
    const { agentId, agentName, round, type, content, keyPoints } = data;

    if (!agentId || !agentName || !round || !type || !content) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: '缂哄皯蹇呰鍙傛暟' }));
      return;
    }

    const engine = getCouncilEngine();
    const session = engine.getSession(sessionId);

    if (!session) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Council 浼氳瘽涓嶅瓨鍦? }));
      return;
    }

    const statement = {
      id: randomUUID(),
      agentId,
      agentName,
      round,
      type,
      content,
      keyPoints: keyPoints || [],
      timestamp: Date.now(),
    };

    session.statements.push(statement);

    // 鍙戝皠 SSE 浜嬩欢锛岀‘淇濆墠绔?SSE 瀹㈡埛绔兘鏀跺埌鎵嬪姩娉ㄥ叆鐨勫彂瑷€
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const emit = (getCouncilEngine() as any).emit;
    if (typeof emit === 'function') {
      try {
        emit({
          type: 'statement',
          sessionId,
          phase: session.phase,
          round,
          statement,
          timestamp: Date.now(),
        });
      } catch (err) {
        // emit 澶辫触涓嶉樆濉炶姹俓n      }
    }

    res.writeHead(201, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(statement));
  } catch (err) {
    logger.error('鎻愪氦 Council 鍙戣█澶辫触', { error: String(err) });
    if (!res.headersSent) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: '鎻愪氦 Council 鍙戣█澶辫触' }));
    }
  }
}

/**
 * 鍓嶇閿欒涓婃姤澶勭悊鍣╘n *
 * 鎺ユ敹鍓嶇 handleClientError 涓婃姤鐨勯敊璇壒娆★紝
 * 鍐欏叆 Logger 骞惰褰曞埌 OTEL銆俓n *
 * GET /v1/monitoring/errors 鈥?杩斿洖鍚庣閿欒缁熻锛圥3-2.11锛塡n */

import type http from 'http';
import { Logger, LogLevel } from '../../../monitoring/logs/Logger';
import { handleError } from '../../../error/handleError';
import { getErrorStats } from '../../../error/handleError';

const logger = new Logger({
  module: 'http:error-report',
  level: LogLevel.INFO,
});

interface ErrorBatchItem {
  message: string;
  category: string;
  severity: string;
  code?: string;
  module: string;
  action?: string;
  timestamp: number;
  stack?: string;
}

async function parseBody(req: http.IncomingMessage): Promise<unknown> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (chunk: Buffer) => chunks.push(chunk));
    req.on('end', () => {
      try {
        resolve(JSON.parse(Buffer.concat(chunks).toString()));
      } catch {
        resolve(null);
      }
    });
    req.on('error', reject);
  });
}

export async function handleClientErrorReport(
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const body = (await parseBody(req)) as { errors: ErrorBatchItem[] } | null;
    if (!body?.errors || !Array.isArray(body.errors)) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'missing errors array' }));
      return;
    }

    const count = body.errors.length;
    const severities = new Set(body.errors.map((e) => e.severity));
    const criticalCount = body.errors.filter(
      (e) => e.severity === 'critical' || e.severity === 'high'
    ).length;

    logger.info(`鏀跺埌鍓嶇閿欒涓婃姤: ${count} 鏉, {
      count,
      severities: [...severities],
      criticalCount,
      clientModules: [...new Set(body.errors.map((e) => e.module))],
    });

    // 璁板綍姣忔潯鍒伴敊璇拷韪猏n    for (const entry of body.errors) {
      logger.warn(`[鍓嶇閿欒] [${entry.module}] ${entry.message}`, {
        category: entry.category,
        severity: entry.severity,
        code: entry.code,
        action: entry.action,
      });
    }

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ ok: true, received: count }));
  } catch (err) {
    await handleError(err, {
      module: 'http:error-report',
      action: 'handleClientErrorReport',
    });
    res.writeHead(500, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'internal error' }));
  }
}

