import type http from 'http';
import { sendError, readRequestBody } from './handler-utils';
import { LogLevel } from '@modules/monitoring';
import { OTelAwareLogger } from '@modules/monitoring/logs/OTelAwareLogger';

const logger = new OTelAwareLogger({
  module: 'knowledge:faq:handler',
  level: LogLevel.INFO,
});

/** 浠?URL 璺緞涓彁鍙栫煡璇嗗簱鍚嶇О */
function extractBaseName(url: string): string | null {
  const match = url.match(/\/v1\/knowledge\/([^/]+)\/faq/);
  return match ? decodeURIComponent(match[1]!) : null;
}

/** 浠?URL 璺緞涓彁鍙?FAQ ID */
function extractFaqId(url: string): string | null {
  const match = url.match(/\/v1\/knowledge\/[^/]+\/faq\/([^/?]+)/);
  return match ? decodeURIComponent(match[1]!) : null;
}

/** 鍙戦€?JSON 鍝嶅簲 */
function sendJson(
  res: http.ServerResponse,
  status: number,
  data: unknown
): void {
  const body = JSON.stringify(data);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
  });
  res.end(body);
}

