/**
 * 澶勭悊鏂囦欢涓婁紶璇锋眰
 * 閬靛惊銆岀敤鎴蜂笂浼犳枃浠朵粎淇濆瓨鍒扮敤鎴风洰褰曘€嶈鍒欙紝浣跨敤 AttachmentManager 淇濆瓨鍒?~/.pyapp/attachments/
 */
export async function handleFileUpload(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const body = await ctx.readRequestBody(req);
    const { filename, data } = JSON.parse(body);
    if (!filename || !data) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({
          error: { message: 'filename and data are required' },
        })
      );
      return;
    }
    const buffer = Buffer.from(data, 'base64');
    const safeName = path.basename(filename);
    // 浣跨敤 AttachmentManager 淇濆瓨鍒扮敤鎴烽檮浠剁洰褰曪紙绗笁灞傦細~/.pyapp/attachments/锛塡n    const attachment = attachmentManager.saveAttachment(
      safeName,
      buffer,
      'file',
      'application/octet-stream',
      AttachmentSource.SESSION
    );
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ path: attachment.path, size: buffer.length }));
    ctx.broadcastEvent('file:uploaded', {
      path: attachment.path,
      size: buffer.length,
      filename: safeName,
      attachmentId: attachment.id,
    });
  } catch (err) {
    ctx.sendError(res, err);
  }
}

