    // 瑙ｆ瀽 URL 鏌ヨ鍙傛暟锛坆ase, domain, tags 绛夛級
    const url = new URL(req.url!, `http://${req.headers.host ?? 'localhost'}`);
    const base = url.searchParams.get('base') ?? undefined;
    const domain = url.searchParams.get('domain') ?? undefined;
    const urlTags = url.searchParams
      .get('tags')
      ?.split(',')
      .map((t) => t.trim())
      .filter(Boolean);
    const filterTags = tags ?? urlTags;

    const { KnowledgeRouter } =
      await import('@modules/knowledge/KnowledgeRouter');
    const { knowledgeDocsProvider } =
      await import('@modules/docs/FileDocsProvider');
    const router = new KnowledgeRouter(knowledgeDocsProvider);
    const routes = await router.search(query, {
      maxResults: 20,
      ...(domain ? ({ domain } as any) : {}),
    });
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let result = routes.map((route: any) => ({
      id: `knowledge-${route.docPath}`,
      title: route.title,
      content: route.snippet || '',
      category: route.category || '鏍圭洰褰?,
      score: route.score,
      matchType: route.matchType,
      docPath: route.docPath,
      tags: route.tags ?? [],
    }));

    // 鎸夋爣绛捐繃婊わ紙SearchTarget锛塡n    if (filterTags && filterTags.length > 0) {
      result = result.filter((r: any) =>
        filterTags.some((t: string) => r.tags?.includes(t))
      );
    }

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(result));
  } catch (err) {
    sendError(res, err);
  }
}

/**
 * 澶勭悊鍒涘缓鐭ヨ瘑鏉＄洰璇锋眰
 * 灏嗘柊鐭ヨ瘑鍐欏叆鐢ㄦ埛鐭ヨ瘑搴撶洰褰曪紙~/.pyapp/knowledge/锛塡n */
export async function handleCreateKnowledge(
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const body = await readRequestBody(req);
    const { title, content, category } = JSON.parse(body);
    if (!title) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: { message: 'title is required' } }));
      return;
    }
    const { resolvePyappHome } = await import('@modules/core/paths');
    const { writeFile, mkdir } = await import('fs/promises');
    const { join } = await import('path');
    const userKnowledgeDir = join(resolvePyappHome(), 'knowledge');
    const targetDir = category
      ? join(userKnowledgeDir, category)
      : userKnowledgeDir;
    await mkdir(targetDir, { recursive: true });
    const fileName = `${title.replace(/[\\/:*?"<>|]/g, '_')}.md`;
    const filePath = join(targetDir, fileName);
    const fileContent = content
      ? `# ${title}\n\n${content}\n`
      : `# ${title}\n\n`;
    await writeFile(filePath, fileContent, 'utf-8');
    const newId = `knowledge-${Date.now()}`;
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(
      JSON.stringify({
        id: newId,
        title,
        content: content || '',
        category: category || '鏍圭洰褰?,
        docPath: filePath,
        created_at: Date.now(),
        updated_at: Date.now(),
      })
    );
    broadcastEvent('knowledge:created', { id: newId, title });
  } catch (err) {
    sendError(res, err);
  }
}

