/**
 * MCP OAuth 鍥炶皟澶勭悊鍣╘n *
 * 鎺ユ敹娴忚鍣?OAuth 鎺堟潈鍚庣殑 redirect callback锛岃В鏋?code/state 鍙傛暟锛孿n * 閫氳繃 OAuth Discovery 鑾峰彇鏈嶅姟鍣ㄥ厓鏁版嵁鍚庯紝濮旀墭 MCPAuthManager.handleCallback()
 * 瀹屾垚 token 浜ゆ崲鍜屾寔涔呭寲銆俓n *
 * 瀵规爣 hermes: mcp_oauth_manager.py 鐨?OAuth 鍥炶皟澶勭悊
 */
import type http from 'http';
import { mcpAuthManager } from '@modules/services/mcp/auth/MCPAuth';
import type { MCPOAuthConfig } from '@modules/services/mcp/auth/types';
import type { McpOAuthConfig } from '@modules/services/mcp/types';
import { readMcpConfig } from '@modules/mcp';
import { configManager } from '@modules/config';

import { Logger, LogLevel } from '@modules/monitoring';
const logger = new Logger({
  module: 'infrastructure:http:handlers:mcp-oauth-handler',
  level: LogLevel.INFO,
});

/**
 * 閫氳繃 OAuth Discovery 灏?McpOAuthConfig 瑙ｆ瀽涓?MCPOAuthConfig
 */
async function resolveOAuthConfig(
  oauth: McpOAuthConfig,
  callbackBase: string
): Promise<MCPOAuthConfig> {
  const { OAuthDiscovery } = await import('@modules/oauth');

  // 閫氳繃 authServerMetadataUrl 鑷姩鍙戠幇 OAuth 绔偣
  const discovery = new OAuthDiscovery();
  const metadata = oauth.authServerMetadataUrl
    ? await discovery.discoverMetadata(oauth.authServerMetadataUrl)
    : null;

  return {
    clientId: oauth.clientId || '',
    authUrl:
      metadata?.authorizationEndpoint || oauth.authServerMetadataUrl || '',
    tokenUrl:
      metadata?.tokenEndpoint ||
      oauth.authServerMetadataUrl?.replace(
        /\/\.well-known\/oauth-authorization-server$/,
        '/token'
      ) ||
      '',
    redirectUri: `${callbackBase}/v1/mcp/oauth/callback`,
  };
}

/**
 * 澶勭悊 MCP OAuth 鍥炶皟璇锋眰
 * GET /v1/mcp/oauth/callback?server=<name>&code=<auth_code>&state=<state>
 */
export async function handleMCPOAuthCallback(
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  const sendJson = (status: number, body: Record<string, unknown>) => {
    res.writeHead(status, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(body));
  };

  try {
    const parsedUrl = new URL(
      req.url!,
      `http://${req.headers.host || 'localhost'}`
    );

    const serverKey = parsedUrl.searchParams.get('server');
    const code = parsedUrl.searchParams.get('code');
    const state = parsedUrl.searchParams.get('state');

    if (!serverKey) {
      sendJson(400, { error: { message: 'Missing "server" query parameter' } });
      return;
    }

    if (!code) {
      sendJson(400, { error: { message: 'Missing "code" query parameter' } });
      return;
    }

    // 浠?MCP 閰嶇疆涓鍙栬鏈嶅姟鍣ㄧ殑 OAuth 閰嶇疆
    const configPath =
      configManager.env('MCP_CONFIG_PATH') || './mcp.config.json';
    const servers = readMcpConfig(configPath);
    const mcpConfig = servers[serverKey];
    if (!mcpConfig || !mcpConfig.oauth) {
      sendJson(404, {
        error: {
          message: `MCP server '${serverKey}' not found or has no OAuth config`,
        },
      });
      return;
    }

    // 閫氳繃 Discovery 瑙ｆ瀽 OAuth 绔偣
    const callbackBase = `http://127.0.0.1:${parsedUrl.port || '7890'}`;
    const oauthConfig = await resolveOAuthConfig(mcpConfig.oauth, callbackBase);

    const token = await mcpAuthManager.handleCallback(
      serverKey,
      code,
      state || '',
      oauthConfig
    );

    sendJson(200, {
      success: true,
      server: serverKey,
      expiresAt: token.expiresAt,
      scopes: token.scopes,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    sendJson(500, { error: { message } });
  }
}

/**
 * 濯掍綋鏂囦欢澶勭悊 handler
 *
 * 鎻愪緵濯掍綋鏂囦欢瀵煎叆 鈫?闊抽鎻愬彇 鈫?STT 杞綍 鈫?瀛楀箷瀵煎嚭鐨勫畬鏁寸绾裤€俓n *
 * 绔偣锛歕n *   POST /v1/media/subtitle 鈥?涓婁紶濯掍綋鏂囦欢骞剁敓鎴愬瓧骞昞n *   GET  /v1/media/subtitle/:id/download 鈥?涓嬭浇瀛楀箷鏂囦欢锛圫RT/TXT锛塡n */

import type http from 'http';
import { randomUUID } from 'crypto';
import { join, extname } from 'path';
import {
  existsSync,
  readFileSync,
  writeFileSync,
  unlinkSync,
  mkdirSync,
} from 'fs';
import { Logger } from '@modules/monitoring';
import { handleError } from '@modules/error';
import { resolveTempDir } from '@modules/core/paths';
import { videoProcessor } from '../../../media/video/VideoProcessor';

const logger = new Logger({ module: 'http:media' });

/** 鏀寔鐨勫獟浣撴枃浠舵墿灞曞悕 */
const SUPPORTED_AUDIO_EXTS = new Set([
  '.mp3',
  '.wav',
  '.flac',
  '.ogg',
  '.m4a',
  '.aac',
  '.wma',
  '.opus',
  '.webm',
]);
const SUPPORTED_VIDEO_EXTS = new Set([
  '.mp4',
  '.mkv',
  '.avi',
  '.mov',
  '.wmv',
  '.flv',
  '.webm',
]);

/** 瀛楀箷鐢熸垚缁撴灉缂撳瓨锛堝唴瀛樹腑锛屽簲鐢ㄩ噸鍚嵆涓㈠け锛?*/
const subtitleCache = new Map<string, SubtitleResult>();

/** 瀛楀箷鏉＄洰 */
interface SubtitleEntry {
  index: number;
  start: number;
  end: number;
  text: string;
}

/** 瀛楀箷鐢熸垚缁撴灉 */
interface SubtitleResult {
  id: string;
  fileName: string;
  text: string;
  language: string;
  duration: number;
  segments: SubtitleEntry[];
  createdAt: number;
}

/**
 * 璇诲彇璇锋眰浣擄紙multipart 瑙ｆ瀽绠€鍖栫増锛塡n */
async function readMultipartBody(
  req: http.IncomingMessage
): Promise<{ fileName: string; data: Buffer } | null> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = [];

    req.on('data', (chunk: Buffer) => chunks.push(chunk));
    req.on('end', () => {
      const raw = Buffer.concat(chunks);

      // 瑙ｆ瀽 multipart/form-data boundary
      const contentType = req.headers['content-type'] || '';
      const boundaryMatch = contentType.match(/boundary=(.+)$/);
      if (!boundaryMatch) {
        resolve(null);
        return;
      }

      const boundary = boundaryMatch[1].trim();
      const boundaryBuffer = Buffer.from(`--${boundary}`);

      // 鏌ユ壘鏂囦欢閮ㄥ垎
      let startIdx = raw.indexOf(boundaryBuffer);
      while (startIdx !== -1) {
        const headerEnd = raw.indexOf('\r\n\r\n', startIdx);
        if (headerEnd === -1) break;

        const headerSection = raw.slice(startIdx, headerEnd).toString();
        const nextBoundary = raw.indexOf(boundaryBuffer, headerEnd + 4);
        const bodyEnd = nextBoundary !== -1 ? nextBoundary - 2 : raw.length - 2;

        if (headerSection.includes('filename=')) {
          // 鎻愬彇鏂囦欢鍚峔n          const filenameMatch = headerSection.match(/filename="([^"]+)"/);
          const fileName = filenameMatch ? filenameMatch[1] : 'unknown';

          const fileData = raw.slice(headerEnd + 4, bodyEnd);
          resolve({ fileName, data: fileData });
          return;
        }

        startIdx = raw.indexOf(boundaryBuffer, bodyEnd);
      }

      resolve(null);
    });

    req.on('error', () => resolve(null));
  });
}

/**
 * 灏嗙鏁版牸寮忓寲涓?SRT 鏃堕棿鎴虫牸寮?(HH:MM:SS,mmm)
 */
function formatSrtTimestamp(seconds: number): string {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.floor(seconds % 60);
  const ms = Math.floor((seconds % 1) * 1000);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')},${String(ms).padStart(3, '0')}`;
}

/**
 * 鐢熸垚 SRT 鏍煎紡瀛楀箷鏂囨湰
 */
function generateSRT(segments: SubtitleEntry[]): string {
  return segments
    .map((seg) => {
      return `${seg.index}\n${formatSrtTimestamp(seg.start)} --> ${formatSrtTimestamp(seg.end)}\n${seg.text}\n`;
    })
    .join('\n');
}

/**
 * 鐢熸垚绾枃鏈牸寮忓瓧骞昞n */
function generateTXT(segments: SubtitleEntry[]): string {
  return segments.map((seg) => seg.text).join('\n');
}

/**
 * 鏍规嵁杞綍闊抽鏃堕暱灏嗘枃鏈垏鍒嗕负鍥哄畾闂撮殧鐨勫瓧骞曟钀絓n * STT 杩斿洖 segments 鏃剁洿鎺ヤ娇鐢紱鏃?segments 鏃舵寜 2 绉掗棿闅斿垏鍒哱n */
function buildSegments(
  text: string,
  duration: number,
  rawSegments?: Array<{ text: string; start: number; end: number }>
): SubtitleEntry[] {
  if (rawSegments && rawSegments.length > 0) {
    return rawSegments.map((seg, i) => ({
      index: i + 1,
      start: seg.start,
      end: seg.end,
      text: seg.text,
    }));
  }

  // 鏃?segments 鏃舵寜鍙ュ瓙鍒囧垎锛屽潎鍖€鍒嗛厤鏃堕棿
  const sentences = text.split(/(?<=[銆傦紒锛?!?\n])/).filter((s) => s.trim());
  if (sentences.length === 0) return [];

  const totalDuration = Math.max(duration, sentences.length * 2);
  const perSegment = totalDuration / sentences.length;

  return sentences.map((sentence, i) => ({
    index: i + 1,
    start: i * perSegment,
    end: Math.min((i + 1) * perSegment, totalDuration),
    text: sentence.trim(),
  }));
}

/**
 * 鍒ゆ柇鏂囦欢鏄惁涓洪煶棰戞枃浠禱n */
function isAudioFile(fileName: string): boolean {
  return SUPPORTED_AUDIO_EXTS.has(extname(fileName).toLowerCase());
}

/**
 * 鍒ゆ柇鏂囦欢鏄惁涓鸿棰戞枃浠禱n */
function isVideoFile(fileName: string): boolean {
  return SUPPORTED_VIDEO_EXTS.has(extname(fileName).toLowerCase());
}

/**
 * 澶勭悊濯掍綋鏂囦欢瀛楀箷鐢熸垚 POST /v1/media/subtitle
 *
 * 鎺ュ彈 multipart/form-data 涓婁紶鐨勫獟浣撴枃浠讹紙闊抽鎴栬棰戯級锛孿n * 瑙嗛鍒欏厛鎻愬彇闊抽锛屽啀閫氳繃 STT 杞綍锛岃繑鍥炲瓧骞曠粨鏋溿€俓n */
export async function handleMediaSubtitleGenerate(
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const parsed = await readMultipartBody(req);
    if (!parsed) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: '鏃犳硶瑙ｆ瀽涓婁紶鏂囦欢' }));
      return;
    }

    const { fileName, data } = parsed;
    const ext = extname(fileName).toLowerCase();

    if (!isAudioFile(fileName) && !isVideoFile(fileName)) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({
          error: `涓嶆敮鎸佺殑鏂囦欢鏍煎紡 "${ext}"锛屾敮鎸佺殑鏍煎紡: ${[...SUPPORTED_AUDIO_EXTS, ...SUPPORTED_VIDEO_EXTS].join(', ')}`,
        })
      );
      return;
    }

    // 纭繚涓存椂鐩綍瀛樺湪
    const tempDir = resolveTempDir();
    if (!existsSync(tempDir)) {
      mkdirSync(tempDir, { recursive: true });
    }

    const taskId = randomUUID();
    const inputPath = join(tempDir, `media_${taskId}${ext}`);

    try {
      // 鍐欏叆涓婁紶鏂囦欢鍒颁复鏃剁洰褰昞n      writeFileSync(inputPath, data);

      let audioPath: string;

      // 瑙嗛鏂囦欢 鈫?鍏堟彁鍙栭煶棰慭n      if (isVideoFile(fileName)) {
        audioPath = join(tempDir, `audio_${taskId}.wav`);
        const success = await videoProcessor.extractAudio(inputPath, audioPath);
        if (!success || !existsSync(audioPath)) {
          res.writeHead(500, { 'Content-Type': 'application/json' });
          res.end(
            JSON.stringify({ error: '瑙嗛闊抽鎻愬彇澶辫触锛岃纭 ffmpeg 宸插畨瑁? })
          );
          return;
        }
        // 娓呯悊瑙嗛涓存椂鏂囦欢
        try {
          unlinkSync(inputPath);
        } catch (err) {
          /* 娓呯悊澶辫触涓嶅奖鍝嶄富娴佺▼ */
        }
      } else {
        audioPath = inputPath;
      }

      // 璇诲彇闊抽鏁版嵁骞惰浆褰昞n      const audioData = readFileSync(audioPath);

      const { STTRegistry } =
        await import('../../../services/voice/services/sttRegistry');

      // 纭繚榛樿鎻愪緵鑰呭凡娉ㄥ唽
      if (STTRegistry.getAllProviders().length === 0) {
        const { LocalSTTProvider } =
          await import('../../../services/voice/services/localSTTProvider');
        STTRegistry.register(new LocalSTTProvider());
      }

      const sttResult = await STTRegistry.transcribe(audioData, {
        language: 'zh',
      });

      // 鏋勫缓瀛楀箷鏉＄洰
      const segments = buildSegments(
        sttResult.text,
        sttResult.duration || 0,
        sttResult.segments
      );

      // 淇濆瓨缁撴灉鍒扮紦瀛榎n      const result: SubtitleResult = {
        id: taskId,
        fileName,
        text: sttResult.text,
        language: sttResult.language || 'zh',
        duration: sttResult.duration || 0,
        segments,
        createdAt: Date.now(),
      };
      subtitleCache.set(taskId, result);

      // 娓呯悊闊抽涓存椂鏂囦欢
      try {
        unlinkSync(audioPath);
      } catch (err) {
        /* 娓呯悊澶辫触涓嶅奖鍝嶄富娴佺▼ */
      }

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({
          id: taskId,
          fileName,
          text: sttResult.text,
          language: result.language,
          duration: result.duration,
          segments,
          downloadSrt: `/v1/media/subtitle/${taskId}/download?format=srt`,
          downloadTxt: `/v1/media/subtitle/${taskId}/download?format=txt`,
        })
      );
    } catch (err) {
      // 娓呯悊涓存椂鏂囦欢
      try {
        unlinkSync(inputPath);
      } catch (err) {
        /* ignore */
      }
      throw err;
    }
  } catch (err) {
    logger.error('濯掍綋瀛楀箷鐢熸垚澶辫触', { error: String(err) });
    void handleError(err, {
      module: 'http:media',
      action: 'subtitle_generate',
    });
    res.writeHead(500, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: '瀛楀箷鐢熸垚澶辫触' }));
  }
}

/**
 * 涓嬭浇瀛楀箷鏂囦欢 GET /v1/media/subtitle/:id/download?format=srt|txt
 */
export async function handleMediaSubtitleDownload(
  req: http.IncomingMessage,
  res: http.ServerResponse,
  id: string
): Promise<void> {
  try {
    const result = subtitleCache.get(id);
    if (!result) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: '瀛楀箷缁撴灉涓嶅瓨鍦ㄦ垨宸茶繃鏈? }));
      return;
    }

    // 瑙ｆ瀽 format 鏌ヨ鍙傛暟
    const urlObj = new URL(
      req.url || '/',
      `http://${req.headers.host || 'localhost'}`
    );
    const format = urlObj.searchParams.get('format') || 'srt';

    let content: string;
    let contentType: string;
    let fileExt: string;

    if (format === 'srt') {
      content = generateSRT(result.segments);
      contentType = 'text/plain; charset=utf-8';
      fileExt = '.srt';
    } else if (format === 'txt') {
      content = generateTXT(result.segments);
      contentType = 'text/plain; charset=utf-8';
      fileExt = '.txt';
    } else {
      res.writeHead(400, { 'Content-Type': 'application/json' });
