  getSystemCpuPercentAsync,
  getDiskInfoAsync,
} from '@modules/monitoring';

const logger = new Logger({
  module: 'infrastructure:http:handlers:monitoring-handlers',
  level: LogLevel.INFO,
});

// 鈹€鈹€ 鎸囨爣鏁版嵁鐜舰缂撳啿鍖?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

interface MetricPoint {
  timestamp: number;
  value: number;
}

const MAX_BUFFER_POINTS = 360;
// 绯荤粺绾ф寚鏍嘰nlet cpuHistory: MetricPoint[] = [];
let memoryHistory: MetricPoint[] = [];
// 搴旂敤绾ф寚鏍囷紙褰撳墠杩涚▼锛塡nlet appCpuHistory: MetricPoint[] = [];
let appMemoryHistory: MetricPoint[] = [];

// 杩涚▼ CPU 閲囨牱杈呭姪锛堢敤浜庤绠?CPU 浣跨敤鐜囧閲忥級
let prevCpuUsage: { user: number; system: number } | null = null;
let prevCpuSampleTime: number = 0;

/**
 * 璁＄畻褰撳墠杩涚▼鐨?CPU 浣跨敤鐜囷紙%锛塡n * 鍩轰簬 process.cpuUsage() 鐨勫閲忛櫎浠ユ椂闂撮棿闅擻n */
function sampleProcessCpuPercent(): number {
  const now = Date.now();
  const currentUsage = process.cpuUsage();
  if (!prevCpuUsage) {
    // 棣栨閲囨牱锛屽彧璁板綍鍩哄噯鍊糪n    prevCpuUsage = currentUsage;
    prevCpuSampleTime = now;
    return 0;
  }
  const deltaUser = currentUsage.user - prevCpuUsage.user;
  const deltaSystem = currentUsage.system - prevCpuUsage.system;
  const deltaTotalUs = deltaUser + deltaSystem; // 寰
  const elapsedMs = now - prevCpuSampleTime;
  prevCpuUsage = currentUsage;
  prevCpuSampleTime = now;
  if (elapsedMs <= 0) return 0;
  // CPU% = (鎬籆PU寰 / (姣 * 1000)) * 100 = 寰 / (姣 * 10)
  const percent = deltaTotalUs / (elapsedMs * 10);
  return Math.min(Math.round(percent * 10) / 10, 100);
}

/**
 * 閲囨牱褰撳墠杩涚▼鐨勫唴瀛樹娇鐢ㄩ噺锛圡B锛塡n */
function sampleProcessMemoryMB(): number {
  return Math.round((process.memoryUsage().rss / 1024 / 1024) * 100) / 100;
}

/**
 * 鍚戠幆褰㈢紦鍐插尯娣诲姞涓€涓暟鎹偣
 */
function pushMetric(buffer: MetricPoint[], point: MetricPoint): void {
  buffer.push(point);
  if (buffer.length > MAX_BUFFER_POINTS) {
    buffer.shift();
  }
}

/**
 * 浠庣紦鍐插尯涓瓫閫夋寚瀹氭椂闂磋寖鍥村唴鐨勬暟鎹偣
 */
function filterMetric(buffer: MetricPoint[], range: number): MetricPoint[] {
  const cutoff = Date.now() - range;
  return buffer.filter((p) => p.timestamp >= cutoff);
}

// 鈹€鈹€ 澶勭悊鍣?鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

/**
 * GET /v1/monitor/summary 鈥?鐩戞帶鎽樿
 */
export async function handleMonitorSummary(
  _ctx: HandlerCtx,
  _req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const service = getMonitoringService();
    const status = service.getSystemStatus();

    const cpuPercent = await getSystemCpuPercentAsync();
    const freeMemMB = Math.round(os.freemem() / 1024 / 1024);
    const totalMemMB = Math.round(os.totalmem() / 1024 / 1024);
    const usedMemMB = totalMemMB - freeMemMB;
    const memoryPercent =
      totalMemMB > 0 ? Math.round((usedMemMB / totalMemMB) * 100) : 0;
    const disk = await getDiskInfoAsync();
    const loadAverage =
      status.loadAverage.length > 0
        ? status.loadAverage.map((l) => Math.round(l * 100) / 100)
        : [];

    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
    res.end(
      JSON.stringify({
        uptime: Math.floor(status.uptime),
        cpuPercent,
        memoryPercent,
        memoryUsedMB: usedMemMB,
        memoryTotalMB: totalMemMB,
        diskTotalGB: disk.totalGB,
        diskUsedGB: disk.usedGB,
        diskFreeGB: disk.freeGB,
        diskUsagePercent: disk.percent,
        loadAverage,
        requestCount: 0,
        errorCount: 0,
        avgResponseTime: 0,
      })
    );
  } catch (err) {
    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
    res.end(
      JSON.stringify({
        uptime: 0,
        cpuPercent: 0,
        memoryPercent: 0,
        memoryUsedMB: 0,
        memoryTotalMB: 0,
        diskTotalGB: 0,
        diskUsedGB: 0,
        diskFreeGB: 0,
        diskUsagePercent: 0,
        loadAverage: [],
        requestCount: 0,
        errorCount: 0,
        avgResponseTime: 0,
      })
    );
  }
}

/**
 * GET /v1/monitor/metrics 鈥?鐩戞帶鎸囨爣
 * 杩斿洖绯荤粺绾т笌搴旂敤绾э紙褰撳墠杩涚▼锛塁PU/鍐呭瓨鍙岀嚎鏁版嵁
 */
export async function handleMonitorMetrics(
  _ctx: HandlerCtx,
  _req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const now = Date.now();

    // 绯荤粺绾ч噰鏍穃n    const sysCpu = await getSystemCpuPercentAsync();
    const sysMem =
      Math.round(((os.totalmem() - os.freemem()) / 1024 / 1024) * 100) / 100;

    // 搴旂敤绾э紙杩涚▼绾э級閲囨牱
    const appCpu = sampleProcessCpuPercent();
    const appMem = sampleProcessMemoryMB();

    // 杩藉姞鍒板悇鑷殑鐜舰缂撳啿鍖篭n    pushMetric(cpuHistory, { timestamp: now, value: sysCpu });
    pushMetric(memoryHistory, { timestamp: now, value: sysMem });
    pushMetric(appCpuHistory, { timestamp: now, value: appCpu });
    pushMetric(appMemoryHistory, { timestamp: now, value: appMem });

    const range = 3600000; // 榛樿杩斿洖鏈€杩?1 灏忔椂鏁版嵁
    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
    res.end(
      JSON.stringify({
        requests: [],
        responseTime: [],
        errorRate: [],
        cpu: filterMetric(cpuHistory, range), // 绯荤粺 CPU
        memory: filterMetric(memoryHistory, range), // 绯荤粺鍐呭瓨
        appCpu: filterMetric(appCpuHistory, range), // 搴旂敤 CPU
        appMemory: filterMetric(appMemoryHistory, range), // 搴旂敤鍐呭瓨
      })
    );
  } catch (err) {
    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
    res.end(
      JSON.stringify({
        requests: [],
        responseTime: [],
        errorRate: [],
        cpu: [],
        memory: [],
        appCpu: [],
        appMemory: [],
      })
    );
  }
}

