          e.message && e.message.toLowerCase().includes(lowerSearch);
        const inData = e.data
          ? JSON.stringify(e.data).toLowerCase().includes(lowerSearch)
          : false;
        const inModule =
          e.module && e.module.toLowerCase().includes(lowerSearch);
        return inMessage || inData || inModule;
