/**
 * Video Handlers
 * 瑙嗛闈欐€佹枃浠舵湇鍔?+ 瑙嗛鍒楄〃 API + 瑙嗛鍒犻櫎 API
 *
 * 绔偣锛歕n *   GET    /v1/videos/static/*  鈥?鎻愪緵瑙嗛鏂囦欢锛堟敮鎸?Range 璇锋眰鐢ㄤ簬 seek锛塡n *   GET    /v1/videos/list       鈥?鍒楀嚭鎵€鏈夊凡鐢熸垚鐨勮棰慭n *   DELETE /v1/videos/delete     鈥?鍒犻櫎瑙嗛锛堟寜璺緞锛塡n *
 * 瑙嗛瀛樺偍鐩綍锛殈/.pyapp/media/video/
 */

import type http from 'http';
import fs from 'fs';
import path from 'path';
import type { HandlerCtx } from './handler-utils';
import { handleError } from '@modules/error';
import { resolveMediaDir } from '@modules/core/paths';

import { Logger, LogLevel } from '@modules/monitoring';
const logger = new Logger({
  module: 'infrastructure:http:handlers:video-handlers',
  level: LogLevel.INFO,
});

/** 瑙嗛鏍圭洰褰曪紙AI 鐢熸垚鎸佷箙鍖栵級 */
const VIDEOS_ROOT = path.join(resolveMediaDir(), 'video');

/** MIME 绫诲瀷鏄犲皠 */
const VIDEO_MIME_MAP: Record<string, string> = {
  '.mp4': 'video/mp4',
  '.webm': 'video/webm',
  '.mov': 'video/quicktime',
  '.avi': 'video/x-msvideo',
  '.mkv': 'video/x-matroska',
  '.ogv': 'video/ogg',
};

/** 鏀寔鐨勮棰戞墿灞曞悕 */
const _VIDEO_EXTENSIONS = Object.keys(VIDEO_MIME_MAP);

/**
 * 鑾峰彇瑙嗛鏂囦欢鐨?MIME 绫诲瀷
 */
function getVideoMimeType(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  return VIDEO_MIME_MAP[ext] || 'application/octet-stream';
}

/**
 * 瀹夊叏妫€鏌?鈥?纭繚瑙ｆ瀽鍚庣殑缁濆璺緞鍦ㄥ畨鍏ㄦ牴鐩綍鍐匼n */
function isVideoRootSafe(requestedPath: string): boolean {
  if (path.isAbsolute(requestedPath)) {
    const resolved = path.resolve(requestedPath);
    return resolved.startsWith(VIDEOS_ROOT);
  }

  const resolved = path.resolve(VIDEOS_ROOT, requestedPath);
  return resolved.startsWith(VIDEOS_ROOT);
}

/**
 * 瑙ｆ瀽璇锋眰璺緞鍒板畬鏁存枃浠惰矾寰刓n */
function resolveVideoPath(requestedPath: string): string | null {
  if (path.isAbsolute(requestedPath)) {
    const resolved = path.resolve(requestedPath);
    if (resolved.startsWith(VIDEOS_ROOT)) return resolved;
    return null;
  }

  const resolved = path.resolve(VIDEOS_ROOT, requestedPath);
  if (!resolved.startsWith(VIDEOS_ROOT)) return null;
  return resolved;
}

/**
 * 閫掑綊閬嶅巻鐩綍鏀堕泦瑙嗛鏂囦欢
 */
function collectVideoFiles(
  dir: string,
  basePath: string,
  files: string[]
): void {
  try {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        collectVideoFiles(fullPath, basePath, files);
      } else if (entry.isFile()) {
        const ext = path.extname(entry.name).toLowerCase();
        if (VIDEO_MIME_MAP[ext]) {
          const relativePath = path.relative(basePath, fullPath);
          files.push(relativePath);
        }
      }
    }
  } catch (err) {
    // 鐩綍涓嶅瓨鍦ㄦ垨涓嶅彲璇伙紝蹇界暐

    logger.debug('Operation skipped', {
      context: '鐩綍涓嶅瓨鍦ㄦ垨涓嶅彲璇伙紝蹇界暐',
      error: err instanceof Error ? err.message : String(err),
    });
  }
}

/**
 * 浠?DB file_files 琛ㄨ鍙栧凡娉ㄥ唽鐨勮棰戞枃浠讹紝鍚堝苟鏂囦欢绯荤粺鎵弿缁撴灉
 */
function collectRegisteredVideos(): Array<{
  relativePath: string;
  absolutePath: string;
}> {
  const result: Array<{ relativePath: string; absolutePath: string }> = [];

  // 浠?DB 璇诲彇宸叉敞鍐岀殑瑙嗛鏂囦欢锛坒ile_files 琛?store_zone = 'media', media_type = 'video'锛塡n  try {
    const { Database } = require('bun:sqlite');
    const { resolveDbPath } = require('@modules/core/paths');
    const db = new Database(resolveDbPath(), { readonly: true });

    const rows = db
      .query(
        `SELECT saved_name, saved_path, original_name 
         FROM file_files 
         WHERE store_zone = 'media' AND media_type = 'video' 
         ORDER BY created_at DESC`
      )
      .all() as Array<{
      saved_name: string;
      saved_path: string;
      original_name: string;
    }>;

    for (const row of rows) {
      const absPath = path.resolve(VIDEOS_ROOT, row.saved_name);
      if (fs.existsSync(absPath)) {
        result.push({
          relativePath: row.saved_name,
          absolutePath: absPath,
        });
      }
    }

    db.close();
  } catch (err) {
    // DB 涓嶅彲鐢紝鍥為€€鍒版枃浠剁郴缁熸壂鎻廫n
    logger.debug('Operation skipped', {
      context: 'DB 涓嶅彲鐢紝鍥為€€鍒版枃浠剁郴缁熸壂鎻?,
      error: err instanceof Error ? err.message : String(err),
    });
  }

  return result;
}

/**
 * GET /v1/videos/static/*
 * 鎻愪緵瑙嗛闈欐€佹枃浠舵湇鍔★紙鏀寔 HTTP Range 璇锋眰鐢ㄤ簬瑙嗛 seek锛塡n */
export async function handleVideoStatic(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  filePath: string
): Promise<void> {
  try {
    // 瀹夊叏妫€鏌n    if (!isVideoRootSafe(filePath)) {
      res.writeHead(403, {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': '*',
      });
      res.end(JSON.stringify({ error: 'Access denied' }));
      return;
    }

    const fullPath = resolveVideoPath(filePath);
    if (!fullPath) {
      res.writeHead(404, {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': '*',
      });
      res.end(JSON.stringify({ error: 'Video not found' }));
      return;
    }

    // 鏂囦欢瀛樺湪鎬ф鏌n    if (!fs.existsSync(fullPath) || !fs.statSync(fullPath).isFile()) {
      res.writeHead(404, {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': '*',
      });
      res.end(JSON.stringify({ error: 'Video not found' }));
      return;
    }

    const stat = fs.statSync(fullPath);
    const fileSize = stat.size;
    const mimeType = getVideoMimeType(fullPath);

    // 澶勭悊 Range 璇锋眰锛堣棰?seek 闇€瑕侊級
    const rangeHeader = req.headers['range'];
    if (rangeHeader) {
      const parts = rangeHeader.replace(/bytes=/, '').split('-');
      const start = parseInt(parts[0], 10);
      const end = parts[1] ? parseInt(parts[1], 10) : fileSize - 1;

      if (start >= fileSize) {
        res.writeHead(416, { 'Content-Range': `bytes */${fileSize}` });
        res.end();
        return;
      }

      const chunkSize = end - start + 1;
      const buffer = Buffer.alloc(chunkSize);
      const fd = fs.openSync(fullPath, 'r');
      fs.readSync(fd, buffer, 0, chunkSize, start);
      fs.closeSync(fd);

      res.writeHead(206, {
        'Content-Type': mimeType,
        'Content-Length': chunkSize,
        'Content-Range': `bytes ${start}-${end}/${fileSize}`,
        'Accept-Ranges': 'bytes',
        'Cache-Control': 'public, max-age=3600',
        'Access-Control-Allow-Origin': '*',
      });
      res.end(buffer);
      return;
    }

    // 瀹屾暣鏂囦欢鍝嶅簲
    const buffer = fs.readFileSync(fullPath);

    res.writeHead(200, {
      'Content-Type': mimeType,
      'Content-Length': fileSize,
      'Accept-Ranges': 'bytes',
      'Cache-Control': 'public, max-age=3600',
      'Access-Control-Allow-Origin': '*',
    });
    res.end(buffer);
  } catch (err) {
    await handleError(err, { module: 'infra:http', action: 'video_static' });
    if (!res.headersSent) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Internal server error' }));
    }
  }
}

/**
 * GET /v1/videos/metadata?path=xxx
 * 杩斿洖瑙嗛鏂囦欢鐨勫厓鏁版嵁锛圥hase 3.4: 淇℃伅闈㈡澘锛塡n * 浠?DB video_tasks 琛ㄤ氦鍙夊紩鐢?prompt銆乵odel銆乻ource_image_url
 */
export async function handleVideoMetadata(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const rawUrl = req.url || '/';
    const urlObj = new URL(rawUrl, `http://${req.headers.host || 'localhost'}`);
    const filePath = urlObj.searchParams.get('path');

    if (!filePath) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Missing path parameter' }));
      return;
    }

    const fullPath = resolveVideoPath(filePath);
    if (!fullPath || !fs.existsSync(fullPath)) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Video not found' }));
      return;
    }

    const stat = fs.statSync(fullPath);
    const ext = path.extname(fullPath).toLowerCase().replace('.', '');
    const fileName = path.basename(fullPath);

    // 浠?DB 鏌ヨ瑙嗛浠诲姟鐨勫厓鏁版嵁锛坧rompt銆乵odel銆乻ource_image_url锛塡n    let prompt: string | null = null;
    let model: string | null = null;
    let sourceImageUrl: string | null = null;
    let sourceImagePath: string | null = null;
    let mode: string | null = null;

    try {
      const { Database } = require('bun:sqlite');
      const { resolveDbPath } = require('@modules/core/paths');
      const db = new Database(resolveDbPath(), { readonly: true });

      // 浠?video_tasks 琛ㄦ煡璇紙鎸?result_video_url LIKE 鍖归厤锛塡n      const likePattern = `%${fileName}%`;
      const row = db
        .query(
          `SELECT prompt, model, source_image_url, source_image_path, mode
           FROM video_tasks
           WHERE result_video_url LIKE ?
           ORDER BY created_at DESC LIMIT 1`
        )
        .get(likePattern) as any;

      if (row) {
        prompt = row.prompt || null;
        model = row.model || null;
        sourceImageUrl = row.source_image_url || null;
        sourceImagePath = row.source_image_path || null;
        mode = row.mode || null;
      }
      db.close();
    } catch (err) {
      // DB 涓嶅彲鐢紝蹇界暐

      logger.debug('Operation skipped', {
        context: 'DB 涓嶅彲鐢紝蹇界暐',
        error: err instanceof Error ? err.message : String(err),
      });
    }

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(
      JSON.stringify({
        path: fullPath,
        size: stat.size,
        format: ext,
        duration: null, // TODO: 闇€瑕?ffprobe 鑾峰彇瑙嗛鏃堕暱
        createdAt: stat.birthtimeMs,
        modifiedAt: stat.mtimeMs,
        prompt,
        model,
        mode,
        sourceImageUrl,
        sourceImagePath,
      })
    );
  } catch (err) {
    await handleError(err, { module: 'infra:http', action: 'video_metadata' });
    if (!res.headersSent) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Internal server error' }));
    }
  }
}

/**
 * GET /v1/videos/by-source-image?path=xxx
 * 鏌ヨ鐢辨寚瀹氬浘鐗囩敓鎴愮殑瑙嗛鍒楄〃锛圥hase 6.1: 鍥剧敓瑙嗛婧簮锛塡n */
export async function handleVideoBySourceImage(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const rawUrl = req.url || '/';
    const urlObj = new URL(rawUrl, `http://${req.headers.host || 'localhost'}`);
    const imagePath = urlObj.searchParams.get('path');

    if (!imagePath) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Missing path parameter' }));
      return;
    }

    // 浣跨敤 VideoTaskPersistence 鏌ヨ
    const { getVideoTaskPersistence } =
      await import('@modules/tools/VideoGenerateTool/VideoTaskPersistence');
    const persistence = getVideoTaskPersistence();

    const tasks = persistence.listBySourceImagePath(imagePath);

    const videos = tasks
      .filter((t) => t.resultVideoUrl)
      .map((t) => ({
        taskId: t.id,
        status: t.status,
        mode: t.mode,
        prompt: t.prompt,
        model: t.model || null,
        sourceImageUrl: t.sourceImageUrl || null,
        sourceImagePath: t.sourceImagePath || null,
        resultVideoUrl: t.resultVideoUrl || null,
        progress: t.progress,
        createdAt: t.createdAt,
        completedAt: t.completedAt || null,
      }));

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ videos, count: videos.length }));
  } catch (err) {
    await handleError(err, {
      module: 'infra:http',
      action: 'video_by_source_image',
    });
    if (!res.headersSent) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Internal server error' }));
    }
  }
}

/**
 * GET /v1/videos/list?page=1&pageSize=50
 * 鍒楀嚭宸茬敓鎴愮殑瑙嗛鏂囦欢锛堟敮鎸佸垎椤碉級
 * 浠?DB file_files 琛ㄨ鍙栵紙宸叉敞鍐岀殑瑙嗛锛夛紝鍥為€€鍒版枃浠剁郴缁熸壂鎻廫n */
export async function handleVideoList(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const rawUrl = req.url || '/';
    const urlObj = new URL(rawUrl, `http://${req.headers.host || 'localhost'}`);
    const page = Math.max(
      1,
      parseInt(urlObj.searchParams.get('page') || '1', 10)
    );
    const pageSize = Math.min(
      200,
      Math.max(1, parseInt(urlObj.searchParams.get('pageSize') || '50', 10))
    );

    // 鍏堜粠 DB 璇诲彇宸叉敞鍐岀殑瑙嗛
    let dbVideos = collectRegisteredVideos();

    // 鍚屾椂鎵弿鏂囦欢绯荤粺涓?DB 鍙兘鏈敞鍐岀殑鏂囦欢
    const fsFiles: string[] = [];
    if (fs.existsSync(VIDEOS_ROOT)) {
      collectVideoFiles(VIDEOS_ROOT, VIDEOS_ROOT, fsFiles);
    }

    // 鍚堝苟鍘婚噸锛堟寜鏂囦欢鍚嶏級
    const seenNames = new Set(
      dbVideos.map((v) => path.basename(v.absolutePath))
    );
    for (const f of fsFiles) {
      const absPath = path.join(VIDEOS_ROOT, f);
      if (!seenNames.has(path.basename(absPath))) {
        dbVideos.push({ relativePath: f, absolutePath: absPath });
        seenNames.add(path.basename(absPath));
      }
    }

    // 鎸夋枃浠朵慨鏀规椂闂村€掑簭锛堟柊鐨勫湪鍓嶏級
    dbVideos.sort((a, b) => {
      try {
        const statA = fs.statSync(a.absolutePath);
        const statB = fs.statSync(b.absolutePath);
        return statB.mtimeMs - statA.mtimeMs;
      } catch {
        return 0;
      }
    });

    const total = dbVideos.length;
    const startIdx = (page - 1) * pageSize;
    const paged = dbVideos.slice(startIdx, startIdx + pageSize);

    const videos = paged.map((f) => ({
      path: f.absolutePath,
      url: `/v1/videos/static/${f.relativePath.replace(/\\/g, '/')}`,
    }));

    res.writeHead(200, {
      'Content-Type': 'application/json',
      'Access-Control-Allow-Origin': '*',
    });
    res.end(
      JSON.stringify({
        videos,
        total,
        page,
        pageSize,
        hasMore: startIdx + pageSize < total,
      })
    );
  } catch (err) {
    await handleError(err, { module: 'infra:http', action: 'video_list' });
    if (!res.headersSent) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Internal server error' }));
    }
  }
}

/**
 * DELETE /v1/videos/delete?path=fileName.mp4
 * 鍒犻櫎鎸囧畾璺緞鐨勮棰戞枃浠禱n */
export async function handleVideoDelete(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  try {
    const rawUrl = req.url || '/';
    const urlObj = new URL(rawUrl, `http://${req.headers.host || 'localhost'}`);
    const filePath = urlObj.searchParams.get('path');

    if (!filePath) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Missing path parameter' }));
      return;
    }

    // 瀹夊叏妫€鏌n    if (!isVideoRootSafe(filePath)) {
      res.writeHead(403, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Access denied' }));
      return;
    }

    const fullPath = resolveVideoPath(filePath);
    if (!fullPath || !fs.existsSync(fullPath)) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Video not found' }));
      return;
    }

    const stat = fs.statSync(fullPath);
    if (!stat.isFile()) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Cannot delete directory' }));
      return;
    }

    // 鍒犻櫎鐗╃悊鏂囦欢
    fs.unlinkSync(fullPath);

    // 灏濊瘯浠?DB 涓Щ闄よ褰昞n    try {
      const { Database } = require('bun:sqlite');
      const { resolveDbPath } = require('@modules/core/paths');
      const db = new Database(resolveDbPath());
      const fileName = path.basename(fullPath);
      db.prepare(`DELETE FROM file_files WHERE saved_name = ?`).run(fileName);
      db.close();
    } catch (err) {
      // DB 涓嶅彲鐢紝蹇界暐

      logger.debug('Operation skipped', {
        context: 'DB 涓嶅彲鐢紝蹇界暐',
        error: err instanceof Error ? err.message : String(err),
      });
    }

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ success: true, path: filePath }));
  } catch (err) {
    await handleError(err, { module: 'infra:http', action: 'video_delete' });
    if (!res.headersSent) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Internal server error' }));
    }
  }
}

/**
 * VideoTaskAPI
 * 瑙嗛寮傛浠诲姟 HTTP API
 *
 * Phase 1 鈥?鍥惧儚涓庤棰戣仈鍔╘n *
 * 绔偣锛歕n *   POST /v1/video/tasks       鈥?鍒涘缓寮傛瑙嗛鐢熸垚浠诲姟
 *   GET  /v1/video/tasks/:id    鈥?鏌ヨ鍗曚釜浠诲姟鐘舵€乗n *   GET  /v1/video/tasks        鈥?鏌ヨ浠诲姟鍒楄〃锛堟敮鎸??status=active 杩囨护锛塡n */

import type http from 'http';
import type { HandlerCtx } from './handler-utils';
import { handleError } from '@modules/error';
import { getVideoTaskPersistence } from '@modules/tools/VideoGenerateTool/VideoTaskPersistence';
import type { ToolUseContext } from '@modules/tools/types/Tool';

import { Logger, LogLevel } from '@modules/monitoring';
