/**
 * 澶勭悊缁撴潫璇煶浼氳瘽璇锋眰 POST /v1/voice/session/:id/end
 */
export async function handleEndVoiceSession(
  req: http.IncomingMessage,
  res: http.ServerResponse,
  sessionId: string
): Promise<void> {
  try {
    const session = voiceSessions.get(sessionId);
    if (!session) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({ error: { message: `浼氳瘽 ${sessionId} 涓嶅瓨鍦╜ } })
      );
      return;
    }

    session.endedAt = Date.now();
    session.duration = session.endedAt - session.startedAt;
    session.status = 'completed';
    voiceSessions.set(sessionId, session);

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(session));
  } catch (err) {
    logger.error('缁撴潫璇煶浼氳瘽澶辫触', { error: String(err), sessionId });
    void handleError(err, {
      module: 'http:voice',
      action: 'end_session',
      context: { sessionId },
    });
    sendError(res, err);
  }
}

