/**
 * 澶勭悊娴嬭瘯鍞ら啋璇嶈姹?POST /v1/voice/wakeword/:id/test
 *
 * 浣跨敤璇锋眰浣撲腑鐨勯煶棰戞暟鎹紝閫氳繃 STT + detectWakeWord 妫€娴嬫寚瀹氬敜閱掕瘝
 */
export async function handleTestWakeWord(
  req: http.IncomingMessage,
  res: http.ServerResponse,
  wakeWordId: string
): Promise<void> {
  try {
    const audioBuffer = await readRawBody(req);

    if (!audioBuffer || audioBuffer.length < 100) {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ detected: false, reason: '闊抽鏁版嵁涓嶈冻' }));
      return;
    }

    const { STTRegistry } =
      await import('../../../services/voice/services/sttRegistry');
    const { detectWakeWord } = await import('../../../voice/VoiceWakeManager');

    // 浣跨敤璇ュ敜閱掕瘝浣滀负 keyterms 杩涜 STT 杞啓
    const result = await STTRegistry.transcribe(audioBuffer, {
      keyterms: [wakeWordId],
    });

    // 鏂囨湰绾у敜閱掕瘝妫€娴媆n    const detection = await detectWakeWord(result.text ?? '', [wakeWordId]);

    logger.info('鍞ら啋璇嶆祴璇曞畬鎴?, {
      wakeWordId,
      transcript: result.text?.slice(0, 80),
      detected: detection.detected,
    });

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(
      JSON.stringify({
        detected: detection.detected,
        matchedTrigger: detection.matchedTrigger,
        transcript: result.text?.slice(0, 200),
        confidence: result.confidence,
      })
    );
  } catch (err) {
    logger.error('娴嬭瘯鍞ら啋璇嶅け璐?, { error: String(err) });
    void handleError(err, { module: 'http:voice', action: 'test_wakeword' });
    sendError(res, err);
  }
}

