/**
 * 澶勭悊淇濆瓨 TTS 鎻愪緵鑰呴厤缃?POST /v1/tts/providers/:name/config
 */
export async function handleSaveProviderConfig(
  req: http.IncomingMessage,
  res: http.ServerResponse,
  providerName: string
): Promise<void> {
  try {
    const body = await readRequestBody(req);
    const config = JSON.parse(body);

    const { TTSRegistry } =
      await import('../../../services/voice/services/ttsProvider');

    const provider = TTSRegistry.getProvider(providerName);
    if (!provider) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({
          error: { message: `Provider "${providerName}" 鏈敞鍐宍 },
        })
      );
      return;
    }

    // 濡傛灉 provider 鏈?updateConfig 鏂规硶锛岃皟鐢ㄤ箣
    if (
      typeof (provider as unknown as Record<string, unknown>).updateConfig ===
      'function'
    ) {
      (
        provider as unknown as Record<
          string,
          (config: Record<string, unknown>) => void
        >
      ).updateConfig(config);
    }

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ success: true }));
  } catch (err) {
    logger.error('淇濆瓨 TTS 鎻愪緵鑰呴厤缃け璐?, {
      error: String(err),
      providerName,
    });
    void handleError(err, {
      module: 'http:voice',
      action: 'save_provider_config',
    });
    sendError(res, err);
  }
}

