/**
 * 宸ヤ綔椤规悳绱?API Handler锛堝璇濆紡鍥為【锛塡n *
 * 鏀寔鑷劧璇█鎻忚堪鎼滅储鍘嗗彶宸ヤ綔椤癸細
 * - POST /v1/workspaces/:id/items/search  鈥?鎼滅储宸ヤ綔椤筡n * - GET  /v1/workspaces/:id/items/review  鈥?宸ヤ綔椤瑰洖椤炬憳瑕乗n */

import type http from 'http';
import type { HandlerCtx } from './handler-utils';
import { handleError } from '@modules/error';
import { createWorkItemStore } from '@modules/workspace/WorkItemStore';
import { createLiriConfigManager } from '@modules/workspace/LiriConfigManager';
import { resolveWorkspacePath } from './workspaces-handlers';
import type {
  WorkItemSearchQuery,
  WorkItemSearchResult,
} from '@modules/workspace/types';

import { Logger, LogLevel } from '@modules/monitoring';
const logger = new Logger({
  module: 'infrastructure:http:handlers:workitem-search-handlers',
  level: LogLevel.INFO,
});

/**
 * 鎼滅储宸ヤ綔椤筡n * POST /v1/workspaces/:id/items/search
 *
 * 鏀寔鍏抽敭璇嶃€佹棩鏈熻寖鍥淬€佺姸鎬併€佺被鍨嬨€佹爣绛剧瓑澶氱淮搴﹁繃婊n */
export async function handleSearchWorkItems(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  workspaceId: string
): Promise<void> {
  try {
    const body = await ctx.readRequestBody(req);
    const query: WorkItemSearchQuery = body ? JSON.parse(body) : {};

    const wsPath = await resolveWorkspacePath(workspaceId);
    if (!wsPath) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: { message: 'Workspace not found' } }));
      return;
    }

    const manager = createLiriConfigManager(wsPath);
    const store = createWorkItemStore(manager.dir, manager);
    let items = store.list(workspaceId);

    // 鍏抽敭璇嶈繃婊わ紙鏍囬 + 鎻忚堪锛塡n    if (query.keywords) {
      const kw = query.keywords.toLowerCase();
      items = items.filter(
        (item) =>
          item.title.toLowerCase().includes(kw) ||
          (item.description && item.description.toLowerCase().includes(kw))
      );
    }

    // 鏃ユ湡鑼冨洿杩囨护
    if (query.dateRange) {
      const { start, end } = query.dateRange;
      items = items.filter((item) => {
        if (start && item.createdAt < start) return false;
        if (end && item.createdAt > end) return false;
        return true;
      });
    }

    // 鐘舵€佽繃婊n    if (query.status && query.status.length > 0) {
      items = items.filter((item) => query.status!.includes(item.status));
    }

    // 绫诲瀷杩囨护
    if (query.type && query.type.length > 0) {
      items = items.filter((item) => query.type!.includes(item.type));
    }

    // 鏍囩杩囨护
    if (query.tags && query.tags.length > 0) {
      items = items.filter(
        (item) =>
          item.tags && item.tags.some((tag) => query.tags!.includes(tag))
      );
    }

    // 鍒嗛厤鑰呰繃婊n    if (query.assigneeId) {
      items = items.filter(
        (item) =>
          item.assignment && item.assignment.assignee.id === query.assigneeId
      );
    }

    // 鎺掑簭
    const sortBy = query.sortBy || 'updatedAt';
    const sortOrder = query.sortOrder || 'desc';
    items.sort((a, b) => {
      const aVal = a[sortBy] || '';
      const bVal = b[sortBy] || '';
      if (sortOrder === 'asc') return aVal > bVal ? 1 : -1;
      return aVal < bVal ? 1 : -1;
    });

    const total = items.length;

    // 鍒嗛〉
    const offset = query.offset || 0;
    const limit = query.limit || 50;
    items = items.slice(offset, offset + limit);

    const result: WorkItemSearchResult = {
      items,
      total,
      query,
      searchedAt: new Date().toISOString(),
    };

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(result));
  } catch (err) {
    await handleError(err, {
      module: 'infra:http',
      action: 'search_workitems',
    });
    if (!res.headersSent) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({ error: { message: 'Failed to search work items' } })
      );
    }
  }
}

/**
 * 宸ヤ綔椤瑰洖椤炬憳瑕乗n * GET /v1/workspaces/:id/items/review
 *
 * 杩斿洖宸ヤ綔椤圭殑缁熻鎽樿锛岀敤浜?AI 瀵硅瘽寮忓洖椤綷n */
export async function handleWorkItemReview(
  ctx: HandlerCtx,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  workspaceId: string
): Promise<void> {
  try {
    const wsPath = await resolveWorkspacePath(workspaceId);
    if (!wsPath) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: { message: 'Workspace not found' } }));
      return;
    }

    const manager = createLiriConfigManager(wsPath);
    const store = createWorkItemStore(manager.dir, manager);
    const items = store.list(workspaceId);

    // 鎸夌姸鎬佺粺璁n    const statusCounts: Record<string, number> = {};
    const typeCounts: Record<string, number> = {};
    let totalTokens = 0;
    let totalCost = 0;

    for (const item of items) {
      statusCounts[item.status] = (statusCounts[item.status] || 0) + 1;
      typeCounts[item.type] = (typeCounts[item.type] || 0) + 1;
    }

    // 鏈€杩戝畬鎴愮殑宸ヤ綔椤筡n    const recentlyCompleted = items
      .filter((item) => item.status === 'done')
      .sort((a, b) => (b.completedAt || '').localeCompare(a.completedAt || ''))
      .slice(0, 10);

    // 褰撳墠杩涜涓殑宸ヤ綔椤筡n    const inProgress = items.filter(
      (item) => item.status === 'running' || item.status === 'review'
    );

    const review = {
      workspaceId,
      totalItems: items.length,
      statusCounts,
      typeCounts,
      inProgress,
      recentlyCompleted,
      totalTokens,
      totalCostUSD: totalCost,
      generatedAt: new Date().toISOString(),
    };

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(review));
  } catch (err) {
    await handleError(err, { module: 'infra:http', action: 'workitem_review' });
    if (!res.headersSent) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({ error: { message: 'Failed to get work item review' } })
      );
    }
  }
}

