export async function resolveWorkspacePath(
  workspaceId: string
): Promise<string | null> {
  try {
    const { buildEntries } =
      await import('@modules/workspaces/WorkspaceStorage');
    const entries = await buildEntries();
    const entry = entries.find((e) => e.meta.id === workspaceId);
    return entry ? entry.path : null;
  } catch (err) {
    return null;
  }
}

