 */
export class AutoRagService {
  private knowledgeRoot: string;
  private embeddingManager: EmbeddingManager;
  private indexManager: IndexManager;
  private domainName?: string;

  /**
   * @param knowledgeRoot 鐭ヨ瘑搴撴牴鐩綍
   * @param embeddingManager 鍙€夛紝鎻愪緵 L3 璇箟鎼滅储鑳藉姏
   * @param domainName 鍩熷悕绉帮紙鍙€夛級銆傛寚瀹氬悗妫€绱㈤檺缂╁埌鍩熺洰褰昞n   */
  constructor(
    knowledgeRoot?: string,
    embeddingManager?: EmbeddingManager,
    domainName?: string
  ) {
    this.domainName = domainName;

    if (knowledgeRoot) {
      this.knowledgeRoot = knowledgeRoot;
    } else if (domainName) {
      this.knowledgeRoot = resolveDomainDir(domainName);
    } else {
      this.knowledgeRoot = resolveKnowledgeDir();
    }

    this.embeddingManager = embeddingManager || globalEmbeddingManager;

    this.indexManager = new IndexManager(this.knowledgeRoot, domainName);
  }

  /**
   * 鑾峰彇鍩熷悕绉帮紙鍙兘涓虹┖锛塡n   */
  getDomainName(): string | undefined {
    return this.domainName;
  }

  // -----------------------------------------------------------------------
  // L0: 鑾峰彇 index.md 鍏ㄦ枃锛堜緵娉ㄥ叆 system prompt锛塡n  // -----------------------------------------------------------------------

  /**
   * 鑾峰彇 index.md 鍏ㄦ枃锛屼緵娉ㄥ叆绯荤粺娑堟伅
   * L0 绾т笂涓嬫枃 鈥?绾?1-3K tokens
   *
   * @returns index.md 鍏ㄦ枃锛屼笉瀛樺湪鏃惰繑鍥炵┖瀛楃涓瞈n   */
  async getIndexContext(maxEntries: number = 50): Promise<string> {
    return this.indexManager.getIndexContext(maxEntries);
  }

  // -----------------------------------------------------------------------
  // L2: 鍏抽敭璇嶆绱?wiki 椤甸潰
  // -----------------------------------------------------------------------

  /**
   * 鏍规嵁鍏抽敭璇嶆悳绱?wiki 椤甸潰鍏ㄦ枃
   * L2 绾ф绱?鈥?鍏抽敭璇嶅尮閰嶆爣棰樺拰鍐呭
   *
   * @param keywords 鎼滅储鍏抽敭璇峔n   * @param maxPages 鏈€澶ц繑鍥為〉鏁帮紝榛樿 3
   * @returns 鍖归厤鐨勯〉闈㈠叏鏂囧垪琛╘n   */
  async searchPages(
    keywords: string[],
    maxPages: number = 3
  ): Promise<RagResult[]> {
    const results: RagResult[] = [];
    const pages = await this.listMdPages();

    for (const filename of pages) {
      if (results.length >= maxPages) break;

      const filePath = join(this.knowledgeRoot, filename);
      let content: string;

      try {
        content = await readFile(filePath, 'utf-8');
      } catch {
        continue;
      }

      // 瀵规瘡涓叧閿瘝鍋氬ぇ灏忓啓涓嶆晱鎰熷尮閰峔n      const lowerContent = content.toLowerCase();
      const matched = keywords.some((kw) =>
        lowerContent.includes(kw.toLowerCase())
      );

      if (!matched) continue;

      const { title, kind } = this.parseFrontmatter(content);

      results.push({
        filename,
        title: title || filename.replace(/\.md$/, ''),
        kind,
        content,
        source: 'L2-keyword',
      });
    }

    return results;
  }

  // -----------------------------------------------------------------------
  // L3: 璇箟鎼滅储锛堝厹搴曪級
  // -----------------------------------------------------------------------

  /**
   * 璇箟鎼滅储 wiki 椤甸潰
   * L3 绾ф绱?鈥?褰?L2 鏃犵粨鏋滄椂浣跨敤
   *
   * 鍐呴儴瀹炵幇锛氶亶鍘嗙煡璇嗗簱鎵€鏈?.md 椤甸潰锛屽祵鍏ユ煡璇㈠悗閫愰〉璁＄畻浣欏鸡鐩镐技搴︺€俓n   *
   * @param query 鑷劧璇█鏌ヨ
   * @param topK 杩斿洖鏉℃暟锛岄粯璁?3
   * @returns 鎸夌浉浼煎害闄嶅簭鎺掑垪鐨勭粨鏋淺n   */
  async semanticSearch(query: string, topK: number = 3): Promise<RagResult[]> {
    const pages = await this.listMdPages();
    if (pages.length === 0) return [];

    // 纭繚 EmbeddingManager 宸插垵濮嬪寲锛堝箓绛夛級
    this.embeddingManager.initialize();

    const queryVec = await this.embeddingManager.embedOne(query);
    if (!queryVec || queryVec.length === 0) return [];

    const scored: Array<{
      filename: string;
      title: string;
      kind: string;
      snippet: string;
      score: number;
    }> = [];

    for (const filename of pages) {
      const filePath = join(this.knowledgeRoot, filename);
      let content: string;

      try {
        content = await readFile(filePath, 'utf-8');
      } catch {
        continue;
      }

      // 鍘绘帀 frontmatter锛岃幏鍙栫函姝ｆ枃
      const body = content.replace(/^---[\s\S]*?---\n*/, '').trim() || content;
      if (!body) continue;

      const pageVec = await this.embeddingManager.embedOne(body);
      if (!pageVec || pageVec.length === 0) continue;

      const score = cosineSimilarity(
        new Float32Array(queryVec),
        new Float32Array(pageVec)
      );
      if (score <= 0.3) continue;

      const { title, kind } = this.parseFrontmatter(content);
      scored.push({
        filename,
        title: title || filename.replace(/\.md$/, '').replace(/[-_]/g, ' '),
        kind,
        snippet: body.slice(0, 200),
        score,
      });
    }

    scored.sort((a, b) => b.score - a.score);
    const top = scored.slice(0, topK);

    return top.map((hit) => ({
      filename: hit.filename,
      title: hit.title,
      kind: hit.kind,
      content: hit.snippet,
      source: 'L3-semantic' as const,
      score: hit.score,
    }));
  }

  // -----------------------------------------------------------------------
  // 鍒嗙骇妫€绱㈠叆鍙n  // -----------------------------------------------------------------------

  /**
   * 缁熶竴妫€绱㈠叆鍙ｏ細L2 鈫?L3 閫愮骇闄嶇骇
   *
   * @param query 鐢ㄦ埛鏌ヨ
   * @param options 妫€绱㈤€夐」
   * @returns 妫€绱㈢粨鏋滃垪琛╘n   */
  async retrieve(
    query: string,
    options?: {
      /** L2 鍏抽敭璇嶅垪琛紝榛樿浠?query 涓彁鍙?*/
      keywords?: string[];
      /** 鏈€澶ц繑鍥為〉鏁帮紝榛樿 3 */
      maxPages?: number;
      /** 鏄惁鍏佽 L3 璇箟鍥炶惤锛岄粯璁?true */
      allowSemanticFallback?: boolean;
    }
  ): Promise<RagResult[]> {
    const maxPages = options?.maxPages ?? 3;
    const allowFallback = options?.allowSemanticFallback ?? true;

    // 浼樺厛 L2锛氬叧閿瘝妫€绱n    const keywords = options?.keywords ?? this.extractKeywords(query);
    const l2Results = await this.searchPages(keywords, maxPages);

    if (l2Results.length > 0) {
      logger.debug('RAG L2 鍛戒腑', { keywords, count: l2Results.length });
      return l2Results;
    }

    // L2 鏃犵粨鏋滄椂 L3 璇箟妫€绱n    if (!allowFallback) return [];

    logger.debug('RAG L2 鏈懡涓紝闄嶇骇鍒?L3 璇箟鎼滅储', { query });
    return await this.semanticSearch(query, maxPages);
  }

  // -----------------------------------------------------------------------
  // 宸ュ叿鏂规硶
  // -----------------------------------------------------------------------

  /**
   * 鍒楀嚭鐭ヨ瘑搴撲腑鎵€鏈?.md 椤甸潰锛堜笉鍚?index.md / log.md锛塡n   */
  private async listMdPages(): Promise<string[]> {
    try {
      const entries = await readdir(this.knowledgeRoot);
      return entries
        .filter(
          (e) =>
            e.endsWith('.md') &&
            e !== 'index.md' &&
            e !== 'log.md' &&
            !e.includes('DIARY')
        )
        .sort();
    } catch {
      return [];
    }
  }

  /**
   * 浠?frontmatter 涓彁鍙?title 鍜?kind
   */
  private parseFrontmatter(content: string): {
    title: string;
    kind: string;
  } {
    const titleMatch = content.match(/^title:\s*(.+)$/m);
    const kindMatch = content.match(/^kind:\s*(.+)$/m);

    return {
      title: titleMatch ? titleMatch[1].trim().replace(/["'"]/g, '') : '',
      kind: kindMatch ? kindMatch[1].trim().replace(/["'"]/g, '') : '鍏朵粬',
    };
  }

  /**
   * 浠庢煡璇㈡枃鏈腑鎻愬彇鍏抽敭璇峔n   */
  private extractKeywords(query: string): string[] {
    return query
      .split(/[\s,锛屻€傦紱;锛?銆侊紵锛??()锛堬級"'"銆屻€嶃€愩€慮/)
      .filter((w) => w.length >= 2 && !COMMON_STOP_WORDS.has(w.toLowerCase()))
      .slice(0, 5);
  }
}

