/**
 * 杞婚噺绱㈠紩绠＄悊鍣?鈥?IndexManager
 *
 * 绠＄悊鐭ヨ瘑搴撶殑 index.md锛堥〉闈㈢储寮曪級鍜?log.md锛堟椿鍔ㄦ棩蹇楋級銆俓n * 瀵规爣 Karpathy LLM Wiki 绾枃鏈储寮曟柟妗堚€斺€斾腑绛夎妯＄煡璇嗗簱
 * 鏃犻渶鍚戦噺鏁版嵁搴擄紝绾?Markdown 鍗冲彲婊¤冻妫€绱㈤渶姹傘€俓n *
 * 鏂囦欢浣嶇疆锛歕n *   ~/.pyapp/knowledge/index.md  鈥?鎸?kind 鍒嗙粍鐨勯〉闈㈢储寮昞n *   ~/.pyapp/knowledge/log.md    鈥?缂栬瘧/鏇存柊娲诲姩鏃ュ織
 */

import { readdir, readFile, writeFile, mkdir } from 'fs/promises';
import { join, dirname, relative } from 'path';
import { existsSync } from 'fs';
import { Logger, LogLevel } from '@modules/monitoring';
import { resolveKnowledgeDir, resolveDomainDir } from '@modules/core';
import type { EventBus } from '@modules/core';

const logger = new Logger({
  module: 'knowledge:indexManager',
  level: LogLevel.INFO,
});

/** 鍗曟娲诲姩璁板綍 */
export interface LogEntry {
  /** 鏃堕棿鎴?*/
  timestamp: number;
  /** 鎿嶄綔绫诲瀷 */
  action: 'compile' | 'update' | 'delete' | 'lint';
  /** 婧愭枃浠舵垨瑙﹀彂鑰?*/
  source: string;
  /** 娑夊強鐨勯〉闈㈠垪琛?*/
  pages: string[];
  /** 璇︽儏 */
  detail?: string;
}

/**
 * 绱㈠紩绠＄悊鍣╘n * 璐熻矗 index.md 鍜?log.md 鐨勭敓鎴愬拰缁存姢
 *
 * Domain-First 妯″紡涓嬶紝閫氳繃 domainName 鎸囧畾鍩燂細
 *   璇诲啓 ~/.pyapp/knowledge/domains/{domain}/ 涓嬬殑 index.md 鍜?log.md
 */
export class IndexManager {
  private knowledgeRoot: string;
  private domainName?: string;
  private eventBus?: EventBus;

  /**
   * @param knowledgeRoot 鐭ヨ瘑搴撴牴鐩綍锛岄粯璁?~/.pyapp/knowledge/
   * @param domainName 鍩熷悕绉帮紙鍙€夛級銆傛寚瀹氬悗榛樿璺緞涓哄煙鐩綍
   * @param eventBus 浜嬩欢鎬荤嚎锛堝彲閫夛級銆備紶鍏ュ悗鐩戝惉鐭ヨ瘑鍙樻洿浜嬩欢锛岃嚜鍔ㄥ埛鏂版枃鏈储寮昞n   */
  constructor(
    knowledgeRoot?: string,
    domainName?: string,
    eventBus?: EventBus
  ) {
    this.domainName = domainName;
    this.eventBus = eventBus;
    if (knowledgeRoot) {
      this.knowledgeRoot = knowledgeRoot;
    } else if (domainName) {
      this.knowledgeRoot = resolveDomainDir(domainName);
    } else {
      this.knowledgeRoot = resolveKnowledgeDir();
    }

    // 鐩戝惉鐭ヨ瘑鍙樻洿浜嬩欢锛岃嚜鍔ㄥ埛鏂版枃鏈储寮昞n    this.eventBus?.subscribe('knowledge:changed', () => {
      this.updateIndexMd().catch((err) => {
        logger.error('鐭ヨ瘑鍙樻洿鍚?index.md 鍒锋柊澶辫触', { error: String(err) });
      });
    });
  }

  /**
   * 鑾峰彇鍩熷悕绉帮紙鍙兘涓虹┖锛塡n   */
  getDomainName(): string | undefined {
    return this.domainName;
  }

  // -----------------------------------------------------------------------
  // index.md
  // -----------------------------------------------------------------------

  /**
   * 鐢熸垚/鏇存柊 index.md
   * 鎵弿鎵€鏈?wiki 椤甸潰锛屾寜 kind 鍒嗙粍鐢熸垚绱㈠紩锛屾瘡椤甸檮甯︽憳瑕乗n   */
  async updateIndexMd(): Promise<void> {
    const pages = await this.listPages();

    if (pages.length === 0) {
      await this.writeIndex(
        `---\nid: index\ntitle: 鐭ヨ瘑搴撶储寮昞
kind: index\n---\n\n# 鐭ヨ瘑搴撶储寮昞
\n鐭ヨ瘑搴撳綋鍓嶄负绌恒€俓
`
      );
      return;
    }

    // 鎸?kind 鍒嗙粍锛屽悓鏃舵彁鍙栨憳瑕乗n    const byKind = new Map<
      string,
      Array<{ id: string; title: string; summary: string }>
    >();

    for (const page of pages) {
      const filePath = join(this.knowledgeRoot, page);
      let kind = '鍏朵粬';
      let title = page.replace(/\.md$/, '');
      let id = title;
      let summary = '';

      try {
        const content = await readFile(filePath, 'utf-8');
        const kindMatch = content.match(/^kind:\s*(.+)$/m);
        if (kindMatch) {
          kind = kindMatch[1].trim().replace(/["'"]/g, '');
        }
        const titleMatch = content.match(/^title:\s*(.+)$/m);
        if (titleMatch) {
          title = titleMatch[1].trim().replace(/["'"]/g, '');
        }
        const idMatch = content.match(/^id:\s*(.+)$/m);
        if (idMatch) {
          id = idMatch[1].trim().replace(/["'"]/g, '');
        }
        const summaryMatch = content.match(/^summary:\s*(.+)$/m);
        if (summaryMatch) {
          summary = summaryMatch[1].trim().replace(/["'"]/g, '');
        }
      } catch (err) {
        // 鏃犳硶璇诲彇鏃朵娇鐢ㄩ粯璁ゅ€糪n      }

      const list = byKind.get(kind) || [];
      list.push({ id, title, summary });
      byKind.set(kind, list);
    }

    const lines: string[] = [];
    lines.push('---');
    lines.push('id: index');
    lines.push('title: 鐭ヨ瘑搴撶储寮?);
    lines.push('kind: index');
    lines.push('---');
    lines.push('');
    lines.push('# 鐭ヨ瘑搴撶储寮?);
    lines.push('');
    lines.push(
      '> 鑷姩鐢熸垚 鈥?鏈€鍚庢洿鏂? ' + new Date().toISOString().slice(0, 10)
    );
    lines.push('');
    lines.push(`鍏?${pages.length} 涓〉闈);
    lines.push('');

    for (const [kind, pageList] of byKind) {
      lines.push(`## ${kind}锛?{pageList.length}锛塦);
      lines.push('');
      for (const item of pageList) {
        const display =
          item.title !== item.id ? `${item.title} 鈥?\`${item.id}\`` : item.id;
        const summaryLine = item.summary
          ? `  鈥?${item.summary.slice(0, 60)}`
          : '';
        lines.push(`- [[${item.id}|${display}]]${summaryLine}`);
      }
      lines.push('');
    }

    await this.writeIndex(lines.join('\n'));
    logger.info(
      `index.md 宸叉洿鏂? ${pages.length} 涓〉闈? ${byKind.size} 涓垎绫籤
    );
  }

  /**
   * 鑾峰彇 index.md 鍐呭锛岀敤浜?L0 娉ㄥ叆锛堟敞鍏?system prompt 鏃朵娇鐢級
   * 浠呰繑鍥為〉闈㈡憳瑕佸垪琛紙绮剧畝鐗堬級锛岄€傚悎 token 鍙楅檺鐨勫満鏅痋n   *
   * @param maxEntries 鏈€澶ф潯鐩暟锛岄粯璁?50
   * @returns 绮剧畝绱㈠紩鏂囨湰
   */
  async getIndexContext(maxEntries: number = 50): Promise<string> {
    const pages = await this.listPages();
    if (pages.length === 0) return '';

    const entries: string[] = [];
    entries.push(`# 鐭ヨ瘑搴撶储寮曪紙${this.domainName || 'default'}锛塦);
    entries.push(`椤甸潰鏁? ${pages.length}`);
    entries.push('');

    let count = 0;
    for (const page of pages) {
      if (count >= maxEntries) break;
      const filePath = join(this.knowledgeRoot, page);
      let title = page.replace(/\.md$/, '');
      let summary = '';
      let kind = '';

      try {
        const content = await readFile(filePath, 'utf-8');
        const titleMatch = content.match(/^title:\s*(.+)$/m);
        if (titleMatch) title = titleMatch[1].trim().replace(/["'"]/g, '');
        const summaryMatch = content.match(/^summary:\s*(.+)$/m);
        if (summaryMatch)
          summary = summaryMatch[1].trim().replace(/["'"]/g, '');
        const kindMatch = content.match(/^kind:\s*(.+)$/m);
        if (kindMatch) kind = kindMatch[1].trim().replace(/["'"]/g, '');
      } catch (err) {
        /* 蹇界暐 */
      }

      const kindTag = kind ? `[${kind}] ` : '';
      const summarySuffix = summary ? ` 鈥?${summary.slice(0, 80)}` : '';
      entries.push(`- ${kindTag}${title}${summarySuffix}`);
      count++;
    }

    return entries.join('\n');
  }

  /**
   * 鍐欏叆 index.md
   */
  private async writeIndex(content: string): Promise<void> {
    const filePath = join(this.knowledgeRoot, 'index.md');

    if (!existsSync(dirname(filePath))) {
      await mkdir(dirname(filePath), { recursive: true });
    }

    await writeFile(filePath, content, 'utf-8');
  }

  // -----------------------------------------------------------------------
  // log.md
  // -----------------------------------------------------------------------

  /**
   * 杩藉姞涓€鏉℃椿鍔ㄦ棩蹇楀埌 log.md
   * @param entry 娲诲姩璁板綍
   */
  async appendLog(entry: LogEntry): Promise<void> {
    const logFile = join(this.knowledgeRoot, 'log.md');
    let existingLog = '';

    if (existsSync(logFile)) {
      try {
        existingLog = await readFile(logFile, 'utf-8');
      } catch (err) {
        existingLog = '';
      }
    }

    const dateStr = new Date(entry.timestamp).toISOString();
    const pageList = entry.pages.join(', ');

    const actionLabel: Record<string, string> = {
      compile: '缂栬瘧',
      update: '鏇存柊',
      delete: '鍒犻櫎',
      lint: '妫€鏌?,
    };

    const logLine = [
      `- **${dateStr}** 鈥?${actionLabel[entry.action] || entry.action}`,
      `  - 鏉ユ簮: ${entry.source}`,
      `  - 椤甸潰: ${pageList}`,
      entry.detail ? `  - 璇︽儏: ${entry.detail}` : '',
    ]
      .filter(Boolean)
      .join('\n');

    // 妫€鏌?frontmatter
    let newLog: string;
    if (existingLog.trim().startsWith('---')) {
      // 宸叉湁 frontmatter锛岀洿鎺ヨ拷鍔燶n      newLog = existingLog.trimEnd() + '\n' + logLine;
    } else {
      // 棣栨鍒涘缓锛屽姞 frontmatter
      newLog = [
        '---',
        'id: log',
        'title: 鐭ヨ瘑搴撴椿鍔ㄦ棩蹇?,
        'kind: log',
        '---',
        '',
        '# 鐭ヨ瘑搴撴椿鍔ㄦ棩蹇?,
        '',
        logLine,
      ].join('\n');
    }

    await writeFile(logFile, newLog, 'utf-8');
  }

  /**
   * 璇诲彇 log.md 鏈€杩?N 鏉¤褰昞n   * @param count 杩斿洖鏉℃暟锛岄粯璁?20
   */
  async getRecentLogs(count: number = 20): Promise<string[]> {
    const logFile = join(this.knowledgeRoot, 'log.md');

    if (!existsSync(logFile)) return [];

    try {
      const content = await readFile(logFile, 'utf-8');
      const lines = content.split('\n').filter((l) => l.startsWith('- **'));

      return lines.slice(-count);
    } catch (err) {
      return [];
    }
  }

  // -----------------------------------------------------------------------
  // 鍐呴儴宸ュ叿
  // -----------------------------------------------------------------------

  /**
   * 鍒楀嚭宸叉湁 wiki 椤甸潰锛堜笉鍚?index.md 鍜?log.md锛塡n   * 閫掑綊鎵弿瀛愮洰褰曪紝鏀寔 KnowledgeCompiler 鐢熸垚鐨?kind 鍒嗙被鐩綍锛坰ummary/entity/concept/锛塡n   */
  async listPages(): Promise<string[]> {
    const files: string[] = [];
    await this.walkDir(this.knowledgeRoot, files);
    return files
      .map((f) => relative(this.knowledgeRoot, f).replace(/\\/g, '/'))
      .filter(
        (f) =>
          f.endsWith('.md') &&
          !f.endsWith('index.md') &&
          !f.endsWith('log.md') &&
          !f.includes('DIARY')
      )
      .sort();
  }

  /**
   * 閫掑綊閬嶅巻鐩綍锛屾敹闆嗘墍鏈?.md 鏂囦欢
   */
  private async walkDir(dir: string, files: string[]): Promise<void> {
    let entries;
    try {
      entries = await readdir(dir, { withFileTypes: true });
    } catch (err) {
      return;
    }
    for (const entry of entries) {
      if (entry.name.startsWith('.')) continue;
      const full = join(dir, entry.name);
      if (entry.isDirectory()) {
        await this.walkDir(full, files);
      } else if (entry.isFile()) {
        files.push(full);
      }
    }
  }
}

