/**
 * 鐭ヨ瘑搴撳啓鍏ュ櫒
 *
 * 杩佺Щ鑷?memory/services/KnowledgeBaseWriter.ts銆俓n * 鍐欏叆鐭ヨ瘑鏂囦欢鍚庡箍鎾?knowledge:changed 浜嬩欢锛岃Е鍙戠储寮曡仈鍔ㄣ€俓n */

import { join } from 'path';
import { writeFile, mkdir, readFile } from 'fs/promises';
import { existsSync } from 'fs';

import { Logger, LogLevel } from '@modules/monitoring';
import { handleError } from '@modules/error';
import { resolvePyappHome } from '@modules/core';
import type { EventBus } from '@modules/core';
import { KnowledgeDedupStrategy } from '@modules/knowledge/KnowledgeDedupStrategy';

export interface KnowledgeBaseEntry {
  title: string;
  content: string;
  category: string;
  tags: string[];
  source: string;
}

export interface WriteResult {
  success: boolean;
  filePath: string;
  action: 'created' | 'updated' | 'skipped';
  error?: string;
}

export class KnowledgeBaseWriter {
  private baseDir: string;
  private logger: Logger;
  private eventBus?: EventBus;
  private dedup?: KnowledgeDedupStrategy;
  /** 姣忎釜鏂囨。淇濈暀鐨勬渶澶у揩鐓ф暟 */
  private maxSnapshots: number;

  constructor(
    baseDir?: string,
    eventBus?: EventBus,
    maxSnapshots: number = 10
  ) {
    this.baseDir = baseDir || join(resolvePyappHome(), 'knowledge');
    this.logger = new Logger({ level: LogLevel.INFO });
    this.eventBus = eventBus;
    this.maxSnapshots = maxSnapshots;
  }

  /** 璁剧疆鍘婚噸绛栫暐锛堝彲閫夛級 */
  setDedup(dedup: KnowledgeDedupStrategy): void {
    this.dedup = dedup;
  }

  async writeEntry(entry: KnowledgeBaseEntry): Promise<WriteResult> {
    const fileName = this.sanitizeFileName(entry.title) + '.md';
    const filePath = join(this.baseDir, fileName);

    try {
      await this.ensureDir();

      const frontmatter = this.buildFrontmatter({
        title: entry.title,
        tags: entry.tags,
        category: entry.category,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        source: entry.source,
      });

      const fullContent = `${frontmatter}\n\n${entry.content}\n`;

      const exists = existsSync(filePath);
      let action: WriteResult['action'] = 'skipped';

      // 鍘婚噸妫€鏌ワ細鍐欏叆鏂版枃浠舵椂妫€娴嬫槸鍚︿笌宸叉湁鏂囨。閲嶅
      if (!exists && this.dedup) {
        const dedupResult = await this.dedup.check(entry.title, entry.content);
        if (dedupResult.isDuplicate) {
          return {
            success: false,
            filePath,
            action: 'skipped',
            error: `鍐呭涓庡凡鏈夋枃妗?"${dedupResult.existingTitle}" 閲嶅 (鐩镐技搴? ${(dedupResult.similarity * 100).toFixed(0)}%)`,
          };
        }
      }

      if (exists) {
        const existing = await readFile(filePath, 'utf-8');
        const existingContent = this.stripFrontmatter(existing);

        if (existingContent.trim() === entry.content.trim()) {
          return { success: true, filePath, action: 'skipped' };
        }

        // 鏇存柊鍓嶅垱寤哄揩鐓n        await this.createSnapshot(fileName, existing);

        await writeFile(filePath, fullContent, 'utf-8');
        action = 'updated';
      } else {
        await writeFile(filePath, fullContent, 'utf-8');
        action = 'created';
      }

      // 骞挎挱鐭ヨ瘑鍙樻洿浜嬩欢锛岃Е鍙戠储寮曡仈鍔╘n      this.eventBus?.publish('knowledge:changed', {
        action,
        filePath,
      });

      return { success: true, filePath, action };
    } catch (error) {
      const errMsg = error instanceof Error ? error.message : String(error);
      await handleError(error, {
        module: 'knowledge:writer',
        action: 'write_entry',
        context: { filePath },
      });
      return {
        success: false,
        filePath,
        action: 'skipped',
        error: errMsg,
      };
    }
  }

  /**
   * 鑾峰彇鏂囨。鐨勫揩鐓х洰褰曡矾寰刓n   */
  getSnapshotDir(title: string): string {
    const fileName = this.sanitizeFileName(title);
    return join(this.baseDir, '.knowledge-snapshots', fileName);
  }

  /**
   * 鍒楀嚭鏂囨。鐨勬墍鏈夊揩鐓ф枃浠禱n   */
  async listSnapshots(title: string): Promise<string[]> {
    const snapDir = this.getSnapshotDir(title);
    if (!existsSync(snapDir)) return [];
    try {
      const { readdir } = await import('fs/promises');
      const entries = await readdir(snapDir);
      return entries
        .filter((e) => e.startsWith('snapshot_') && e.endsWith('.md'))
        .sort()
        .reverse(); // 鏈€鏂板湪鍓峔n    } catch (err) {
      return [];
    }
  }

  /**
   * 浠庡揩鐓ф仮澶嶆枃妗n   */
  async restoreSnapshot(
    title: string,
    snapshotFileName: string
  ): Promise<boolean> {
    const snapDir = this.getSnapshotDir(title);
    const snapPath = join(snapDir, snapshotFileName);
    if (!existsSync(snapPath)) return false;

    try {
      const content = await readFile(snapPath, 'utf-8');
      const fileName = this.sanitizeFileName(title) + '.md';
      const filePath = join(this.baseDir, fileName);

      // 鎭㈠鍓嶄篃鍒涘缓褰撳墠鐗堟湰鐨勫揩鐓n      if (existsSync(filePath)) {
        const current = await readFile(filePath, 'utf-8');
        await this.createSnapshot(fileName, current);
      }

      await writeFile(filePath, content, 'utf-8');

      this.eventBus?.publish('knowledge:changed', {
        action: 'created',
        filePath,
      });

      return true;
    } catch (err) {
      return false;
    }
  }

  /**
   * 鍒涘缓鏂囨。蹇収
   */
  private async createSnapshot(
    fileName: string,
    content: string
  ): Promise<void> {
    const docName = fileName.replace(/\.md$/i, '');
    const snapDir = join(this.baseDir, '.knowledge-snapshots', docName);

    if (!existsSync(snapDir)) {
      await mkdir(snapDir, { recursive: true });
    }

    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const snapFile = join(snapDir, `snapshot_${timestamp}.md`);
    await writeFile(snapFile, content, 'utf-8');

    // 娓呯悊瓒呭嚭涓婇檺鐨勬棫蹇収
    try {
      const { readdir, unlink } = await import('fs/promises');
      const entries = (await readdir(snapDir))
        .filter((e) => e.startsWith('snapshot_') && e.endsWith('.md'))
        .sort(); // 鏈€鏃х殑鍦ㄥ墠
      while (entries.length > this.maxSnapshots) {
        const oldest = entries.shift();
        if (oldest) {
          await unlink(join(snapDir, oldest));
        }
      }
    } catch (err) {
      // 娓呯悊澶辫触涓嶅奖鍝嶄富娴佺▼
    }
  }

  private async ensureDir(): Promise<void> {
    if (!existsSync(this.baseDir)) {
      await mkdir(this.baseDir, { recursive: true });
    }
  }

  private sanitizeFileName(name: string): string {
    return name
      .replace(/[<>:"/\\|?*]/g, '_')
      .replace(/\s+/g, '_')
      .slice(0, 100);
  }

  private buildFrontmatter(metadata: Record<string, unknown>): string {
    const lines = ['---'];
    for (const [key, value] of Object.entries(metadata)) {
      if (value === undefined || value === null) continue;
      if (Array.isArray(value)) {
        lines.push(
          `${key}: [${value.map((v) => JSON.stringify(v)).join(', ')}]`
        );
      } else if (typeof value === 'string') {
        lines.push(`${key}: "${value}"`);
      } else {
        lines.push(`${key}: ${value}`);
      }
    }
    lines.push('---');
    return lines.join('\n');
  }

  private stripFrontmatter(content: string): string {
    const match = content.match(/^---\n[\s\S]*?\n---\n/);
    if (match) {
      return content.slice(match[0].length).trim();
    }
    return content.trim();
  }
}

export function createKnowledgeBaseWriter(
  baseDir?: string,
  eventBus?: EventBus
): KnowledgeBaseWriter {
  return new KnowledgeBaseWriter(baseDir, eventBus);
}

/**
 * LLM 鐭ヨ瘑缂栬瘧绠￠亾 (KnowledgeCompiler)
 * Many-to-many 缂栬瘧鑼冨瀷 鈥?瀵规爣 Karpathy LLM Wiki 鏂规硶璁篭n *
 * 涓€鏉?raw 婧愭枃浠惰Е鍙戝椤甸潰鏇存柊锛歕n *   1. 鍒涘缓/鏇存柊涓绘憳瑕侀〉
 *   2. 鎻愬彇瀹炰綋/姒傚康鐢熸垚鐙珛椤甸潰
 *   3. 鏇存柊鐜版湁鐩稿叧椤甸潰锛堜氦鍙夊紩鐢ㄣ€佺煕鐩炬爣娉級
 *
 * 鑱岃矗锛歕n *   1. 璇诲彇 raw/ 鐩綍鐨勫師濮嬫暟鎹枃浠禱n *   2. 閫氳繃 LLM 缂栬瘧涓哄涓粨鏋勫寲 Markdown wiki 椤甸潰
 *   3. 鍐欏叆鐭ヨ瘑搴撶洰褰曞苟鏇存柊绱㈠紩锛坕ndex.md / log.md锛塡n *   4. 杩借釜鍘熷鏂囦欢鏉ユ簮锛堥€氳繃 companion .meta.json锛塡n */
import { readdir, readFile, writeFile, mkdir, stat } from 'fs/promises';
import { join, dirname } from 'path';
import { existsSync } from 'fs';
import { LogLevel } from '@modules/monitoring';
import { OTelAwareLogger } from '@modules/monitoring/logs/OTelAwareLogger';
import { getOTelTracing } from '@modules/monitoring/otel/OTelTracing';
import { LLMPerformanceMonitor } from '@modules/ai/utils/LLMPerformanceMonitor';
