}

/** 鍙紪璇戠殑鏂囦欢鎵╁睍鍚嶏紙涓嶅惈 .meta.json 浼翠荆鏂囦欢锛?*/
const COMPILABLE_EXTENSIONS = new Set([
  '.txt',
