]);

/** LLM 杈撳嚭涓?page-break 鍒嗛殧绗?*/
const PAGE_BREAK = '---page-break---';

export interface CompileOptions {
  /** 鏄惁寮哄埗閲嶇紪璇戞墍鏈夋枃浠讹紝榛樿 false锛堜粎缂栬瘧鏇存柊鐨勬枃浠讹級 */
  force?: boolean;
  /** 鏈€澶у苟鍙戠紪璇戞暟锛岄粯璁?3 */
  concurrency?: number;
