  totalFound: number;
  /** many-to-many: 瀹為檯鐢熸垚鐨?wiki 椤甸潰鎬绘暟锛堜竴鏉℃簮鏂囦欢鍙敓鎴愬椤碉級 */
  pagesCreated: number;
  /** 缂栬瘧浜у嚭鐨勬枃浠惰矾寰勫垪琛紙鐢ㄤ簬鍚庣画鍥捐氨鎻愬彇锛?*/
  compiledFiles: string[];
  /** 缂栬瘧璐ㄩ噺淇℃伅锛坴1.5 鏂板锛?*/
  quality?: {
