    hasWarnings: boolean;
    /** 缂栬瘧澶辫触娆℃暟锛堢敤浜庡洖婊氶槇鍊煎垽鏂級 */
    consecutiveFails: number;
  };
}

/**
 * LLM 鐭ヨ瘑缂栬瘧鍣╘n * Many-to-many 缂栬瘧鑼冨瀷锛歕n *   涓€鏉?raw 婧愭枃浠?鈫?LLM 浜у嚭澶氫釜 wiki 椤甸潰锛堟憳瑕侀〉 + 瀹炰綋/姒傚康椤碉級
 *   鑷姩缁存姢 index.md / log.md锛岀‘淇濈煡璇哱

鑰岄潪鏇挎崲銆俓n */
export class KnowledgeCompiler {
  private knowledgeRoot: string;
  private rawDir: string;
  private aiService: AIService;
  private indexManager: IndexManager;
  private graphExtractor?: GraphExtractor;

  constructor(aiService: AIService, graphExtractor?: GraphExtractor) {
    this.knowledgeRoot = join(resolvePyappHome(), 'knowledge');
    this.rawDir = join(this.knowledgeRoot, 'raw');
    this.aiService = aiService;
    this.graphExtractor = graphExtractor;
    this.indexManager = new IndexManager(this.knowledgeRoot);
  }

  /**
   * 鎵ц缂栬瘧锛坢any-to-many锛塡n   * 姣忔潯 raw 婧愭枃浠惰Е鍙戝椤甸潰鐢熸垚锛屽畬鎴愬悗鏇存柊绱㈠紩
   */
  async compile(options: CompileOptions = {}): Promise<CompileResult> {
    const { force = false, model } = options;

    const result: CompileResult = {
      compiled: 0,
      skipped: 0,
      errors: [],
      totalFound: 0,
      pagesCreated: 0,
      compiledFiles: [],
    };

    if (!existsSync(this.rawDir)) {
      logger.info('raw 鐩綍涓嶅瓨鍦紝璺宠繃缂栬瘧', { rawDir: this.rawDir });
      return result;
    }

    await mkdir(this.knowledgeRoot, { recursive: true });

    const rawFiles = await this.collectRawFiles();
    result.totalFound = rawFiles.length;

    if (rawFiles.length === 0) return result;

    // W9: 寮€濮嬬紪璇戣繘搴﹁拷韪猏n    startCompileProgress(rawFiles.length);

    // 鍔犺浇缂栬瘧鐘舵€佸揩鐓э紝鐢ㄤ簬璺宠繃鏃犲彉鏇存枃浠禱n    const compileState = await this.loadCompileState();
    const newState: CompileState = { lastCompileAt: Date.now(), docs: {} };

    // 娓呯悊宸插垹闄?raw 鏂囦欢鐨勭紪璇戜骇鐗‐n    const cleanedCount = await this.cleanupDeletedRawFiles(
      new Set(rawFiles),
      compileState
    );
    if (cleanedCount > 0) {
      logger.info('宸叉竻鐞嗗凡鍒犻櫎 raw 鏂囦欢鐨勭紪璇戜骇鐗?, { cleanedCount });
    }

    // 妫€鏌ユ槸鍚︽湁鍙敤 Provider锛歰ptions.model 鏄惧紡鎸囧畾鏃朵笉妫€鏌n    if (!model && providerRegistry.size === 0) {
      const errMsg =
        '鏈壘鍒板彲鐢ㄤ緵搴斿晢锛岃烦杩囩紪璇戙€傝閫氳繃 /provider 鍛戒护閰嶇疆渚涘簲鍟嗭紙濡?deepseek/openai锛夈€?;
      logger.error('鐭ヨ瘑缂栬瘧澶辫触', { error: errMsg });
      result.errors.push(errMsg);
      abortCompileProgress(errMsg);
      return result;
    }

    for (const rawFile of rawFiles) {
      try {
        let needsCompile = force || (await this.needsRecompile(rawFile));

        // 澧為噺浼樺寲锛氶€氳繃缂栬瘧鐘舵€佸揩鐓ц烦杩?mtime 鏈彉鏇寸殑鏂囦欢
        if (!force && !needsCompile) {
          const rawStat = await stat(rawFile);
          const prevState = compileState?.docs[rawFile];
          if (prevState && prevState.mtime === rawStat.mtimeMs) {
            // mtime 瀹屽叏涓€鑷达紝涓斿凡鏈夌紪璇戜骇鐗╋紝鍙互瀹夊叏璺宠繃
            result.skipped++;
            newState.docs[rawFile] = prevState;
            updateCompileProgress(result.compiled + result.skipped);
            continue;
          }
          // mtime 鍙樻洿浜嗕絾 needsRecompile 杩斿洖 false锛堝彲鑳界紪璇戜骇鐗╀粛鏇存柊锛塡n          // 淇濆畧绛栫暐锛氫粛闇€妫€鏌ワ紝浣嗕笉闇€瑕佸己鍒堕噸缂栬瘧
          needsCompile = false;
        }

        if (!needsCompile) {
          // 璁板綍褰撳墠 mtime 鍒版柊蹇収锛堝嵆浣胯烦杩囦篃瑕佽褰曪紝閬垮厤涓嬫閲嶅鍒ゆ柇锛塡n          try {
            const rawStat = await stat(rawFile);
            newState.docs[rawFile] = {
              mtime: rawStat.mtimeMs,
              compiledAt: compileState?.docs[rawFile]?.compiledAt ?? Date.now(),
            };
          } catch (err) {
            // stat 澶辫触蹇界暐
          }
          result.skipped++;
          updateCompileProgress(result.compiled + result.skipped);
          continue;
        }

        const pages = await this.compileFile(rawFile, model);
        result.compiled++;
        result.pagesCreated += pages.length;
        result.compiledFiles.push(...pages);

        // 缂栬瘧鎴愬姛锛岃褰曞埌蹇収
        try {
          const rawStat = await stat(rawFile);
          newState.docs[rawFile] = {
            mtime: rawStat.mtimeMs,
            compiledAt: Date.now(),
          };
        } catch (err) {
          // stat 澶辫触蹇界暐
        }

        updateCompileProgress(result.compiled + result.skipped);
        logger.info('鏂囦欢缂栬瘧瀹屾垚', { file: rawFile, pages: pages.length });
      } catch (error) {
        const errMsg = error instanceof Error ? error.message : String(error);
        result.errors.push(`${rawFile}: ${errMsg}`);
        result.skipped++;
        updateCompileProgress(result.compiled + result.skipped, errMsg);
        logger.error('鏂囦欢缂栬瘧澶辫触', { file: rawFile, error: errMsg });
      }
    }

    // W9: 缂栬瘧瀹屾垚
    finishCompileProgress();

    // 鎸佷箙鍖栫紪璇戠姸鎬佸揩鐓n    await this.saveCompileState(newState);

    // many-to-many: 鍏ㄩ儴缂栬瘧瀹屾垚鍚庢洿鏂扮储寮昞n    if (result.pagesCreated > 0) {
      await this.indexManager.updateIndexMd();
      await this.indexManager.appendLog({
        timestamp: Date.now(),
        action: 'compile',
        source: 'KnowledgeCompiler',
        pages: [],
        detail: `many-to-many 缂栬瘧: ${result.compiled} 涓簮鏂囦欢 鈫?${result.pagesCreated} 涓〉闈,
      });
    }

    // 缂栬瘧鍚庤嚜鍔ㄨ繍琛?lint 妫€鏌n    const shouldLint = options.lint !== false;
    if (shouldLint && result.pagesCreated > 0) {
      try {
        const linter = new WikiLinter(defaultRules);
        const lintReport = await linter.run(this.knowledgeRoot);
        const { error, warning } = lintReport.summary;
        if (error > 0 || warning > 0) {
          logger.warn(`缂栬瘧鍚?lint 鍙戠幇 ${error} 涓敊璇? ${warning} 涓鍛奰, {
            lintSummary: lintReport.summary,
          });
          // 灏?lint 缁撴灉杩藉姞鍒?log.md
          await this.indexManager.appendLog({
            timestamp: Date.now(),
            action: 'lint',
            source: 'KnowledgeCompiler',
            pages: [],
            detail: `lint: ${error} errors, ${warning} warnings`,
          });
        } else {
          logger.info('缂栬瘧鍚?lint 妫€鏌ラ€氳繃');
        }
      } catch (lintError) {
        await handleError(lintError, {
          module: 'knowledge:compiler',
          action: 'post_lint',
        });
      }
    }

    // LLM 鍥捐氨鑷姩鎻愬彇锛堢紪璇戝悗锛塡n    if (this.graphExtractor && result.pagesCreated > 0) {
      logger.info('寮€濮嬪浘璋辫嚜鍔ㄦ彁鍙?);
      try {
        // 瀵圭紪璇戜骇鍑虹殑椤甸潰杩涜鍥捐氨鎻愬彇
        for (const compiledFile of result.compiledFiles ?? []) {
          try {
            const content = await readFile(compiledFile, 'utf-8');
            await this.graphExtractor.extract(content, 'knowledge');
          } catch {
            // 鍗曚釜鏂囦欢鎻愬彇澶辫触涓嶉樆濉瀄n          }
        }
      } catch (err) {
        void handleError(err, {
          module: 'knowledge:compiler',
          action: 'graph_extract',
        });
      }
    }

    logger.info(
      `many-to-many 缂栬瘧瀹屾垚: ${result.compiled} 涓簮鏂囦欢, ` +
        `${result.pagesCreated} 涓〉闈? ${result.skipped} 涓烦杩? ` +
        `${result.errors.length} 涓敊璇痐
    );

    return result;
  }

  /**
   * 鏀堕泦 raw 鐩綍涓殑鍙紪璇戞枃浠禱n   */
  private async collectRawFiles(): Promise<string[]> {
    const files: string[] = [];
    const rawFiles = await readdir(this.rawDir);

    for (const file of rawFiles) {
      // 璺宠繃浼翠荆鍏冩暟鎹枃浠禱n      if (file.endsWith('.meta.json')) continue;

      const ext = file.slice(file.lastIndexOf('.')).toLowerCase();
      if (COMPILABLE_EXTENSIONS.has(ext)) {
        files.push(join(this.rawDir, file));
      }
    }

    return files.sort();
  }

  /**
   * 鍒ゆ柇鏄惁闇€瑕侀噸缂栬瘧锛坢any-to-many 鎰熺煡锛塡n   * 妫€鏌?.meta.json 涓褰曠殑 pages 鍒楄〃锛屼换涓€椤甸潰缂哄け鎴栬繃鏃跺氨閲嶇紪璇慭n   */
  private async needsRecompile(rawFile: string): Promise<boolean> {
    const metaFile = `${rawFile}.meta.json`;
    if (!existsSync(metaFile)) return true;

    try {
      const metaContent = await readFile(metaFile, 'utf-8');
      const meta = JSON.parse(metaContent);
      const pages: string[] = meta.pages;
      if (!pages || pages.length === 0) return true;

      const rawStat = await stat(rawFile);
      for (const pagePath of pages) {
        if (!existsSync(pagePath)) return true;
        const pageStat = await stat(pagePath);
        if (rawStat.mtimeMs > pageStat.mtimeMs) return true;
      }
      return false;
    } catch (err) {
      return true;
    }
  }

  /**
   * 鑾峰彇涓绘憳瑕侀〉鐨勭洰鏍囪矾寰勶紙many-to-many 涓殑"涓诲叆鍙ｉ〉"锛塡n   */
  private getWikiTargetPath(rawFile: string): string {
    const baseName = rawFile.replace(
      /\.(txt|json|csv|tsv|xml|yaml|yml)$/,
      '.md'
    );
    const fileName = baseName.split(/[\\/]/).pop() || 'untitled.md';
    return join(this.knowledgeRoot, fileName);
  }

  /**
   * 缂栬瘧鍗曚釜鏂囦欢 鈫?浜у嚭澶氫釜 wiki 椤甸潰锛坢any-to-many锛塡n   *
   * 璋冪敤 LLM 鐢熸垚澶氶〉鍐呭锛堜互 PAGE_BREAK 鍒嗛殧锛夛紝
   * 姣忛〉鍐欏叆鐙珛鏂囦欢锛屽苟鏇存柊 companion .meta.json 璁板綍 pages 鍒楄〃
   *
   * @returns 鐢熸垚鐨勬墍鏈夐〉闈㈡枃浠惰矾寰勫垪琛╘n   */
  private async compileFile(
    rawFile: string,
    model?: string
  ): Promise<string[]> {
    const rawContent = await readFile(rawFile, 'utf-8');
    const targetPath = this.getWikiTargetPath(rawFile);
    const fileName =
      targetPath.split(/[\\/]/).pop()?.replace(/\.md$/, '') || 'untitled';

    // many-to-many: 璋冪敤 LLM 鐢熸垚澶氶〉鍐呭
    const pagesContent = await this.generateManyPages(
      fileName,
      rawContent,
      targetPath,
      model
    );

    // 鍐欏叆鎵€鏈夐〉闈n    const writtenPages: string[] = [];
    for (const { filePath, content } of pagesContent) {
      const finalContent = await this.injectOriginalFileMeta(
        rawFile,
        content,
        filePath
      );
      await mkdir(dirname(filePath), { recursive: true });
      await writeFile(filePath, finalContent, 'utf-8');
      writtenPages.push(filePath);
    }

    // 鏇存柊 companion .meta.json 璁板綍 pages 鍒楄〃
    const metaFile = `${rawFile}.meta.json`;
    const meta = { pages: writtenPages, updatedAt: Date.now() };
    await writeFile(metaFile, JSON.stringify(meta, null, 2), 'utf-8');

    // 娉ㄥ唽缂栬瘧鍚庣殑鐭ヨ瘑鏂囨。鍒?FileRegistry
    try {
      const registry = FileRegistry.getInstance();
      await registry.initDatabase();
      for (const pagePath of writtenPages) {
        await registry.registerFile({
          originalName: pagePath.split(/[\\/]/).pop() || 'page.md',
          content:
            pagesContent.find((p) => p.filePath === pagePath)?.content || '',
          source: FileSource.AUTO_INGEST,
          sourceId: rawFile.split(/[\\/]/).pop() || 'raw',
          description: `鐭ヨ瘑缂栬瘧: ${pagePath.split(/[\\/]/).pop()}`,
          mimeType: 'text/markdown',
          storeZone: 'inbound',
        });
      }
    } catch (err) {
      // 娉ㄥ唽澶辫触涓嶅奖鍝嶇紪璇戜富娴佺▼
    }

    return writtenPages;
  }

  /**
   * 浠?companion .meta.json 璇诲彇鍘熷鏂囦欢淇℃伅骞舵敞鍏?frontmatter
   *
   * @param rawFile    婧愭枃浠惰矾寰刓n   * @param wikiContent  寰呮敞鍏ョ殑 wiki 鍐呭
   * @param _targetPath  鐩爣鏂囦欢璺緞锛堝綋鍓嶄粎鐢ㄤ簬绛惧悕涓€鑷达紝棰勭暀鎵╁睍鐢級
   */
  private async injectOriginalFileMeta(
    rawFile: string,
    wikiContent: string,
    _targetPath?: string
  ): Promise<string> {
    const metaFile = `${rawFile}.meta.json`;
    if (!existsSync(metaFile)) return wikiContent;

    try {
      const metaContent = await readFile(metaFile, 'utf-8');
      const meta = JSON.parse(metaContent);

      if (meta.originalFile || meta.originalFormat) {
        const lines = wikiContent.split('\n');
        let fmEnd = -1;
        if (lines[0]?.trim() === '---') {
          fmEnd = lines.indexOf('---', 1);
        }
        if (fmEnd !== -1) {
          const fmLines = lines.slice(1, fmEnd);
          const hasOriginalFile = fmLines.some((l) =>
            l.startsWith('originalFile:')
          );
          const hasOriginalFormat = fmLines.some((l) =>
            l.startsWith('originalFormat:')
          );

          if (!hasOriginalFile && meta.originalFile) {
            fmLines.splice(1, 0, `originalFile: "${meta.originalFile}"`);
          }
          if (!hasOriginalFormat && meta.originalFormat) {
            fmLines.splice(2, 0, `originalFormat: "${meta.originalFormat}"`);
          }

          return ['---', ...fmLines, '---', ...lines.slice(fmEnd + 1)].join(
            '\n'
          );
        }
      }
    } catch (err) {
      // 鍏冩暟鎹枃浠舵崯鍧忔垨缂哄け锛屽拷鐣n    }

    return wikiContent;
  }

  /**
   * 澶氶〉 LLM 鐢熸垚锛坢any-to-many锛塡n   *
   * 灏嗕竴鏉?raw 婧愭枃浠跺彂閫佺粰 LLM锛岃姹備骇鍑哄涓嫭绔?wiki 椤甸潰锛歕n   *   - 绗竴椤典负涓绘憳瑕侀〉锛堟杩?鑳屾櫙/鏍稿績姒傚康锛塡n   *   鍚庣画椤典负鍏宠仈鐨勫疄浣?姒傚康/鏈椤甸潰
