  /**
   * 浠?frontmatter 鍧椾腑鎻愬彇鎸囧畾瀛楁鍊糪n   */
  private extractFrontmatterField(block: string, field: string): string | null {
    const match = block.match(/^---\n([\s\S]*?)\n---/);
    if (!match) return null;
    const fm = match[1];
    const lineMatch = fm.match(new RegExp(`^${field}:\\s*(.+)`, 'm'));
    return lineMatch ? lineMatch[1].trim().replace(/^"(.*)"$/, '$1') : null;
  }

  /**
   * 娓呯悊宸插垹闄?raw 鏂囦欢鐨勭紪璇戜骇鐗‐n   * 瀵规瘮褰撳墠 raw 鏂囦欢闆嗗悎涓庣紪璇戠姸鎬佸揩鐓э紝鍒犻櫎瀛ゅ効 .meta.json 鍜屽搴旂殑缂栬瘧椤甸潰
   */
  private async cleanupDeletedRawFiles(
    currentRawFiles: Set<string>,
    compileState: CompileState | null
  ): Promise<number> {
    if (!compileState || Object.keys(compileState.docs).length === 0) return 0;

    const { unlink } = await import('fs/promises');
    const { existsSync } = await import('fs');
    let cleaned = 0;

    for (const [rawFilePath] of Object.entries(compileState.docs)) {
      // raw 鏂囦欢宸蹭笉瀛樺湪 鈫?娓呯悊缂栬瘧浜х墿
      if (currentRawFiles.has(rawFilePath)) continue;
      if (!existsSync(rawFilePath)) {
        // 鍒犻櫎 .meta.json
        const metaFile = `${rawFilePath}.meta.json`;
        try {
          if (existsSync(metaFile)) {
            const metaContent = await readFile(metaFile, 'utf-8');
            const meta = JSON.parse(metaContent);
            const pages: string[] = meta.pages || [];
            // 鍒犻櫎鎵€鏈夌紪璇戦〉闈n            for (const pagePath of pages) {
              if (existsSync(pagePath)) {
                await unlink(pagePath);
              }
            }
            await unlink(metaFile);
            cleaned += pages.length + 1; // pages + meta file
            logger.info('宸叉竻鐞嗗垹闄ゆ枃浠剁殑缂栬瘧浜х墿', {
              rawFile: rawFilePath,
              pagesRemoved: pages.length,
            });
          }
        } catch (err) {
          // 娓呯悊澶辫触涓嶉樆濉炵紪璇慭n        }
      }
    }
    return cleaned;
  }

  /**
   * 鍔犺浇缂栬瘧鐘舵€佸揩鐓n   */
  private async loadCompileState(): Promise<CompileState | null> {
    try {
      if (!existsSync(COMPILE_STATE_PATH)) return null;
      const raw = await readFile(COMPILE_STATE_PATH, 'utf-8');
      return JSON.parse(raw) as CompileState;
    } catch (err) {
      return null;
    }
  }

  /**
   * 鎸佷箙鍖栫紪璇戠姸鎬佸揩鐓n   */
  private async saveCompileState(state: CompileState): Promise<void> {
    try {
      const dir = dirname(COMPILE_STATE_PATH);
      if (!existsSync(dir)) {
        await mkdir(dir, { recursive: true });
      }
      await writeFile(
        COMPILE_STATE_PATH,
        JSON.stringify(state, null, 2),
        'utf-8'
      );
    } catch (error) {
      logger.warning('缂栬瘧鐘舵€佸揩鐓т繚瀛樺け璐?, { error: String(error) });
    }
  }
}

/**
 * 涓€閿墽琛岀煡璇嗙紪璇慭n */
export async function runKnowledgeCompile(
  aiService: AIService,
  options?: CompileOptions
): Promise<CompileResult> {
  const compiler = new KnowledgeCompiler(aiService);
  return compiler.compile(options);
}

/**
 * 鐭ヨ瘑搴撳仴搴锋鏌ュ櫒 (KnowledgeLinter)
 * 瀵规爣 CC/OpenClaw 鏂囨。妫€鏌ュ疄璺碉紝瀵圭煡璇嗗簱鍋?6 绫昏瘖鏂細
 *   A. 缁撴瀯瀹屾暣鎬?鈥?frontmatter/title 蹇呭～瀛楁
 *   B. 鏂伴矞搴?鈥?90 澶╂湭鏇存柊鐨勬枃妗n *   C. 鏂摼妫€娴?鈥?[[鍐呴儴閾炬帴]] 鐩爣涓嶅彲杈綷n *   D. 涓€鑷存€ч棶棰?(LLM) 鈥?鍙€夛紝闇€ AI 鏈嶅姟
 *   E. 璐ㄩ噺璇勫垎 (LLM) 鈥?鍙€夛紝闇€ AI 鏈嶅姟
 *   F. 鍏宠仈鎬?鈥?瀛ょ珛鏂囨。锛堟棤鍏ラ摼锛塡n */
import { readdir, readFile, stat } from 'fs/promises';
import { join, relative } from 'path';
import { existsSync } from 'fs';
import { Logger, LogLevel } from '@modules/monitoring';
import type { AIService } from '@modules/ai';
import { AIMessageRole } from '@modules/ai';
import { resolvePyappHome } from '@modules/core';

const logger = new Logger({
  module: 'knowledge:knowledgeLinter',
  level: LogLevel.INFO,
});

export interface LintResult {
  /** 鏂囨。鎬绘暟 */
  totalDocs: number;
  /** 鍚勮瘖鏂被鍒殑闂鍒楄〃 */
  issues: LintIssue[];
  /** 姹囨€荤粺璁?*/
  summary: {
    totalIssues: number;
    byCategory: Record<string, number>;
    bySeverity: Record<string, number>;
  };
}

export interface LintIssue {
  category:
    | 'structure'
    | 'freshness'
    | 'broken_link'
    | 'consistency'
    | 'quality'
    | 'isolation';
  severity: 'error' | 'warning' | 'info';
  docPath: string;
  message: string;
  detail?: string;
}

/**
 * 鑾峰彇鐢ㄦ埛鐭ヨ瘑搴撴牴鐩綍
 */
function getKnowledgeRoot(): string {
  return join(resolvePyappHome(), 'knowledge');
}

/**
 * 瑙ｆ瀽 Markdown frontmatter
 */
function parseFrontmatter(content: string): {
  frontmatter: Record<string, string>;
  body: string;
} {
  const frontmatter: Record<string, string> = {};
  let body = content;

  if (content.startsWith('---')) {
    const endIndex = content.indexOf('---', 3);
    if (endIndex !== -1) {
      const fmText = content.slice(3, endIndex).trim();
      body = content.slice(endIndex + 3).trim();
      for (const line of fmText.split('\n')) {
        const colonIndex = line.indexOf(':');
        if (colonIndex !== -1) {
          const key = line.slice(0, colonIndex).trim();
          const value = line.slice(colonIndex + 1).trim();
          frontmatter[key] = value;
        }
      }
    }
  }

  return { frontmatter, body };
}

/**
 * 鎻愬彇鏂囨。涓殑 [[鍐呴儴閾炬帴]]
 */
function extractWikiLinks(content: string): string[] {
  const links: string[] = [];
  const regex = /\[\[([^\]]+)\]\]/g;
  let match: RegExpExecArray | null;
  while ((match = regex.exec(content)) !== null) {
    const link = match[1].split('|')[0].split('#')[0].trim();
    if (link) links.push(link);
  }
  return links;
}

/**
 * 鐭ヨ瘑搴撳仴搴锋鏌ュ櫒
 */
export class KnowledgeLinter {
  private knowledgeRoot: string;
  private aiService?: AIService;

  constructor(aiService?: AIService) {
    this.knowledgeRoot = getKnowledgeRoot();
    this.aiService = aiService;
  }

  /**
   * 鎵ц鍏ㄩ儴璇婃柇妫€鏌n   */
  async lintAll(): Promise<LintResult> {
    const issues: LintIssue[] = [];
    const docFiles = await this.collectDocFiles();

    if (docFiles.length === 0) {
      return {
        totalDocs: 0,
        issues: [],
        summary: { totalIssues: 0, byCategory: {}, bySeverity: {} },
      };
    }

    // A. 缁撴瀯瀹屾暣鎬ф鏌n    const structureIssues = await this.checkStructure(docFiles);
    issues.push(...structureIssues);

    // B. 鏂伴矞搴︽鏌n    const freshnessIssues = await this.checkFreshness(docFiles);
    issues.push(...freshnessIssues);

    // C. 鏂摼妫€娴媆n    const brokenLinkIssues = await this.checkBrokenLinks(docFiles);
    issues.push(...brokenLinkIssues);

    // D. 涓€鑷存€ч棶棰?(LLM)
    if (this.aiService) {
      const consistencyIssues = await this.checkConsistency(docFiles);
      issues.push(...consistencyIssues);
    }

    // E. 璐ㄩ噺璇勫垎 (LLM)
    if (this.aiService) {
      const qualityIssues = await this.checkQuality(docFiles);
      issues.push(...qualityIssues);
    }

    // F. 鍏宠仈鎬ф鏌n    const isolationIssues = await this.checkIsolation(docFiles);
    issues.push(...isolationIssues);

    return this.buildResult(docFiles.length, issues);
  }

  /**
   * 鏀堕泦鐭ヨ瘑搴撲腑鐨勬墍鏈?Markdown 鏂囦欢
   */
  private async collectDocFiles(): Promise<string[]> {
    const files: string[] = [];

    async function walk(dir: string): Promise<void> {
      let entries;
      try {
        entries = await readdir(dir, { withFileTypes: true });
      } catch (err) {
        return;
      }
      for (const entry of entries) {
        const fullPath = join(dir, entry.name);
        if (entry.isDirectory()) {
          await walk(fullPath);
        } else if (entry.isFile() && entry.name.endsWith('.md')) {
          files.push(fullPath);
        }
      }
    }

    await walk(this.knowledgeRoot);
    return files;
  }

  /**
   * A. 缁撴瀯瀹屾暣鎬ф鏌n   */
  private async checkStructure(docFiles: string[]): Promise<LintIssue[]> {
    const issues: LintIssue[] = [];

    for (const filePath of docFiles) {
      const relPath = relative(this.knowledgeRoot, filePath);
      try {
        const content = await readFile(filePath, 'utf-8');
        const { frontmatter, body } = parseFrontmatter(content);

        if (!frontmatter.title && !content.startsWith('#')) {
          issues.push({
            category: 'structure',
            severity: 'error',
            docPath: relPath,
            message: '鏂囨。缂哄皯鏍囬锛坒rontmatter title 鎴?h1 鏍囬锛?,
          });
        }

        if (!body || body.trim().length === 0) {
          issues.push({
            category: 'structure',
            severity: 'warning',
            docPath: relPath,
            message: '鏂囨。姝ｆ枃涓虹┖',
          });
        }

        if (content.length > 50000) {
          issues.push({
            category: 'structure',
            severity: 'warning',
            docPath: relPath,
            message: `鏂囨。杩囬暱 (${content.length} 瀛楃)锛屽缓璁媶鍒哷,
          });
        }
      } catch (error) {
        issues.push({
          category: 'structure',
          severity: 'error',
          docPath: relPath,
          message: `鏃犳硶璇诲彇鏂囨。: ${error instanceof Error ? error.message : String(error)}`,
        });
      }
    }

    return issues;
  }

  /**
   * B. 鏂伴矞搴︽鏌n   */
  private async checkFreshness(docFiles: string[]): Promise<LintIssue[]> {
    const issues: LintIssue[] = [];
    const now = Date.now();
    const staledDays = 90;
    const staleThreshold = staledDays * 24 * 60 * 60 * 1000;

    for (const filePath of docFiles) {
      const relPath = relative(this.knowledgeRoot, filePath);
      try {
        const stats = await stat(filePath);
        const age = now - stats.mtimeMs;

        if (age > staleThreshold) {
          const daysOld = Math.floor(age / (24 * 60 * 60 * 1000));
          issues.push({
            category: 'freshness',
            severity: 'warning',
            docPath: relPath,
            message: `鏂囨。宸?${daysOld} 澶╂湭鏇存柊锛堣秴杩?${staledDays} 澶╅槇鍊硷級`,
            detail: `鏈€鍚庝慨鏀? ${stats.mtime.toISOString()}`,
          });
        }
      } catch (err) {
        // 蹇界暐鏃犳硶 stat 鐨勬枃浠禱n      }
    }

    return issues;
  }

  /**
   * C. 鏂摼妫€娴媆n   */
  private async checkBrokenLinks(docFiles: string[]): Promise<LintIssue[]> {
    const issues: LintIssue[] = [];

    for (const filePath of docFiles) {
      const relPath = relative(this.knowledgeRoot, filePath);
      try {
        const content = await readFile(filePath, 'utf-8');
        const links = extractWikiLinks(content);

        for (const link of links) {
          const linkFile = link.endsWith('.md') ? link : `${link}.md`;
          const targetPath = join(this.knowledgeRoot, linkFile);

          if (!existsSync(targetPath)) {
            issues.push({
              category: 'broken_link',
              severity: 'error',
              docPath: relPath,
              message: `鏂摼: [[${link}]] -> ${linkFile} 鏂囦欢涓嶅瓨鍦╜,
            });
          }
        }
      } catch (err) {
        // 蹇界暐鏃犳硶璇诲彇鐨勬枃浠禱n      }
    }

    return issues;
  }

  /**
   * D. 涓€鑷存€ч棶棰樻鏌?(LLM)
   */
  private async checkConsistency(docFiles: string[]): Promise<LintIssue[]> {
    if (!this.aiService) return [];

    const issues: LintIssue[] = [];
    const contentMap = new Map<string, string>();

    for (const filePath of docFiles) {
      const relPath = relative(this.knowledgeRoot, filePath);
      try {
        const content = await readFile(filePath, 'utf-8');
        contentMap.set(relPath, content);
      } catch (err) {
        // 蹇界暐鏃犳硶璇诲彇鐨勬枃浠禱n      }
    }

    if (contentMap.size < 2) return [];

    const allContent = Array.from(contentMap.entries())
      .slice(0, 10)
      .map(([path, content]) => `--- ${path} ---\n${content.slice(0, 3000)}`)
      .join('\n\n');

    try {
      const response = await this.aiService.generate([
        {
          role: AIMessageRole.SYSTEM,
          content:
            '浣犳槸鐭ヨ瘑搴撲竴鑷存€ф鏌ュ姪鎵嬨€傚垎鏋愪互涓嬪涓枃妗ｏ紝鎵惧嚭鍐呭鐭涚浘鎴栦笉涓€鑷寸殑鍦版柟銆? +
            '浠呰緭鍑虹煕鐩剧偣锛屾瘡琛屼竴鏉★紝鏍煎紡: "鏂囨。璺緞: 鐭涚浘鎻忚堪"銆傚鏋滄病鏈夌煕鐩撅紝杈撳嚭 "鏃犵煕鐩綷

瀹屾暣鎬?娓呮櫚搴?缁撴瀯"銆備緥濡? "85/70/90"銆?,
            timestamp: Date.now(),
          },
          {
            role: AIMessageRole.USER,
            content: `鏂囨。: ${relPath}\n\n${content.slice(0, 2000)}`,
            timestamp: Date.now(),
          },
        ]);

        const scoreStr = response.content.trim();
        if (/^\d{1,3}\/\d{1,3}\/\d{1,3}$/.test(scoreStr)) {
          const [completeness, clarity, structure] = scoreStr
            .split('/')
            .map(Number);
          if (completeness < 50 || clarity < 50 || structure < 50) {
            issues.push({
              category: 'quality',
              severity: 'info',
              docPath: relPath,
              message: `璐ㄩ噺璇勫垎鍋忎綆 (瀹屾暣鎬?${completeness}, 娓呮櫚搴?${clarity}, 缁撴瀯:${structure})`,
              detail: '寤鸿琛ュ厖鍐呭銆佷紭鍖栬〃杈炬垨鏀瑰杽缁撴瀯',
            });
          }
        }
      } catch (err) {
        // 蹇界暐 LLM 璋冪敤澶辫触
      }
    }

    return issues;
  }

  /**
   * F. 鍏宠仈鎬ф鏌?鈥?瀛ょ珛鏂囨。妫€娴媆n   */
  private async checkIsolation(docFiles: string[]): Promise<LintIssue[]> {
    const issues: LintIssue[] = [];
    const inboundLinks = new Set<string>();
    const docNames = new Set(
      docFiles.map((f) => relative(this.knowledgeRoot, f))
    );

    for (const filePath of docFiles) {
      try {
        const content = await readFile(filePath, 'utf-8');
        const links = extractWikiLinks(content);
        for (const link of links) {
          inboundLinks.add(
            link.endsWith('.md')
              ? link.toLowerCase()
              : `${link}.md`.toLowerCase()
          );
        }
      } catch (err) {
        // 蹇界暐鏃犳硶璇诲彇鐨勬枃浠禱n      }
    }

    for (const filePath of docFiles) {
      const relPath = relative(this.knowledgeRoot, filePath);
      const fileName = relPath.toLowerCase();

      const hasInbound = Array.from(inboundLinks).some(
        (link) => fileName === link || fileName.endsWith(`/${link}`)
      );

      if (!hasInbound && docNames.size > 1) {
        issues.push({
          category: 'isolation',
          severity: 'info',
          docPath: relPath,
          message: '瀛ょ珛鏂囨。锛氭病鏈夎鍏朵粬浠讳綍鏂囨。寮曠敤',
          detail: '寤鸿鍦ㄧ浉鍏虫枃妗ｄ腑娣诲姞瀵规湰鏂囨。鐨?[[寮曠敤]]',
        });
      }
    }

    return issues;
  }

  /**
   * 鏋勫缓妫€鏌ョ粨鏋淺n   */
  private buildResult(totalDocs: number, issues: LintIssue[]): LintResult {
    const byCategory: Record<string, number> = {};
    const bySeverity: Record<string, number> = {};

    for (const issue of issues) {
      byCategory[issue.category] = (byCategory[issue.category] || 0) + 1;
      bySeverity[issue.severity] = (bySeverity[issue.severity] || 0) + 1;
    }

    return {
      totalDocs,
      issues,
      summary: {
        totalIssues: issues.length,
        byCategory,
        bySeverity,
      },
    };
  }
}

/**
 * 涓€閿墽琛岀煡璇嗗簱鍋ュ悍妫€鏌n */
export async function runKnowledgeLint(
  aiService?: AIService
): Promise<LintResult> {
  const linter = new KnowledgeLinter(aiService);
  const result = await linter.lintAll();
  return result;
}

/**
 * 鏍煎紡鍖栨鏌ョ粨鏋滀负鍙鏂囨湰
 */
export function formatLintResult(result: LintResult): string {
  const lines: string[] = [];
  const emojis: Record<string, string> = {
    structure: '馃搻',
    freshness: '鈴?,
    broken_link: '馃敆',
    consistency: '鈿栵笍',
    quality: '猸?,
    isolation: '馃攳',
  };
  const severityLabels: Record<string, string> = {
    error: '馃敶 閿欒',
    warning: '馃煛 璀﹀憡',
    info: '馃數 鎻愮ず',
  };

  lines.push(`馃搵 鐭ヨ瘑搴撳仴搴锋鏌ユ姤鍛奰);
  lines.push(
    `鍏辨鏌?${result.totalDocs} 涓枃妗ｏ紝鍙戠幇 ${result.summary.totalIssues} 涓棶棰榒
  );
  lines.push('');

  // 姹囨€籠n  lines.push('--- 姹囨€?---');
  for (const [cat, count] of Object.entries(result.summary.byCategory)) {
    lines.push(`  ${emojis[cat] || '馃搫'} ${cat}: ${count} 涓棶棰榒);
  }
  for (const [sev, count] of Object.entries(result.summary.bySeverity)) {
    lines.push(`  ${severityLabels[sev] || sev}: ${count} 涓猔);
  }
  lines.push('');

  // 璇︾粏淇℃伅
  if (result.issues.length > 0) {
    lines.push('--- 璇︾粏淇℃伅 ---');
    const sorted = [...result.issues].sort((a, b) => {
      const sevOrder = { error: 0, warning: 1, info: 2 };
      return (sevOrder[a.severity] ?? 3) - (sevOrder[b.severity] ?? 3);
    });

    for (const issue of sorted) {
      lines.push(
        `  ${emojis[issue.category] || ''} ${severityLabels[issue.severity] || issue.severity}: ${issue.docPath}`
      );
      lines.push(`    ${issue.message}`);
      if (issue.detail) {
        lines.push(`    璇︽儏: ${issue.detail}`);
      }
    }
  } else {
    lines.push('鉁?娌℃湁鍙戠幇闂锛?);
  }

  return lines.join('\n');
}

