/**
 * MigrationService 鈥?鍚戦噺瀛樺偍鏁版嵁杩佺Щ宸ュ叿
 *
 * 鏀寔浠庝竴涓?IVectorStore 瀹炵幇杩佺Щ鍒板彟涓€涓紙濡?JSONL 鈫?sqlite-vec锛夈€俓n *
 * 鐗规€э細
 *   - 鎵归噺杩佺Щ锛屼繚鐣欏師濮?id/path/mtimeMs 淇濊瘉澧為噺鏇存柊涓嶉噸澶峔n *   - 鏂偣缁紶锛氳縼绉讳腑鏂悗涓嬫鍚姩浠庝腑鏂偣缁х画
 *   - 杩涘害鍙拷韪紙閫氳繃 CompileProgressTracker 椋庢牸鐨勫洖璋冿級
 *   - 杩佺Щ瀹屾垚鍚庡啓鍏?migration_done 鏍囪锛屼繚鐣欐簮鏁版嵁浣滀负鍥為€€
 *
 * 瑙﹀彂瑙勫垯锛歕n *   鍚姩鏃舵娴?from 鏈夋暟鎹笖 to 涓虹┖ 鈫?鑷姩鎻愮ず鐢ㄦ埛杩佺Щ
 */

import { LogLevel } from '@modules/monitoring';
import { OTelAwareLogger } from '@modules/monitoring/logs/OTelAwareLogger';
import { getOTelTracing } from '@modules/monitoring/otel/OTelTracing';
import { handleError } from '@modules/error';
import type {
  IVectorStore,
  VectorEntry,
} from '@modules/knowledge/semantic/IVectorStore';

const logger = new OTelAwareLogger({
  module: 'knowledge:migration',
  level: LogLevel.INFO,
});

const BATCH_SIZE = 100;

export interface MigrationProgress {
  /** 宸茶縼绉绘潯鐩暟 */
  migrated: number;
  /** 鎬绘潯鐩暟 */
  total: number;
  /** 杩涘害鐧惧垎姣?0-100 */
  percent: number;
  /** 褰撳墠闃舵 */
  phase: 'reading' | 'writing' | 'done' | 'failed';
}

export interface MigrationReport {
  /** 鏄惁鎴愬姛瀹屾垚 */
  success: boolean;
  /** 宸茶縼绉绘潯鐩暟 */
  migratedCount: number;
  /** 璺宠繃鏁帮紙婧愪腑宸插瓨鍦級 */
  skippedCount: number;
  /** 澶辫触鏁?*/
  failedCount: number;
  /** 鑰楁椂(ms) */
  durationMs: number;
  /** 閿欒淇℃伅 */
  error?: string;
}

export type MigrationCallback = (progress: MigrationProgress) => void;

/**
 * 妫€鏌ユ槸鍚﹂渶瑕佽縼绉籠n *
 * @returns true 琛ㄧず婧愬瓨鍌ㄦ湁鏁版嵁涓旂洰鏍囧瓨鍌ㄤ负绌篭n */
export async function needsMigration(
  from: IVectorStore,
  to: IVectorStore
): Promise<boolean> {
  const fromCount = await from.count();
  if (fromCount === 0) return false;

  const toCount = await to.count();
  return toCount === 0;
}

/**
 * 鎵ц鏁版嵁杩佺Щ
 *
 * @param from 婧愬悜閲忓瓨鍌紙濡?JsonlVectorStore锛塡n * @param to 鐩爣鍚戦噺瀛樺偍锛堝 SqliteVecStore锛塡n * @param onProgress 杩涘害鍥炶皟锛堝彲閫夛級
 * @returns 杩佺Щ鎶ュ憡
 */
export async function migrate(
  from: IVectorStore,
  to: IVectorStore,
  onProgress?: MigrationCallback
): Promise<MigrationReport> {
  const otel = getOTelTracing();
  const span = otel.startSpan('knowledge.migration');

  const startTime = performance.now();
  let migratedCount = 0;
  let skippedCount = 0;
  let failedCount = 0;

  try {
    const total = await from.count();
    if (total === 0) {
      logger.info('婧愬瓨鍌ㄤ负绌猴紝鏃犻渶杩佺Щ');
      span.setAttribute('knowledge.migration.total', 0);
      return {
        success: true,
        migratedCount: 0,
        skippedCount: 0,
        failedCount: 0,
        durationMs: 0,
      };
    }

    logger.info('寮€濮嬫暟鎹縼绉?, { fromCount: total });
    span.setAttribute('knowledge.migration.total', total);

    // 鎵规璇诲彇 + 鍐欏叆
    const fromMeta = await from.getMeta();
    if (fromMeta) {
      await to.setMeta(fromMeta);
    }

    // 鑾峰彇婧愬瓨鍌ㄦ墍鏈夋潯鐩紙閫氳繃 search 闂存帴瀹炵幇鍒嗛〉璇诲彇锛塡n    // 鐢变簬 IVectorStore 娌℃湁鍒嗛〉璇诲彇鎺ュ彛锛岃繖閲岄€氳繃 search 闅忔満鍚戦噺鑾峰彇閮ㄥ垎鏉＄洰
    // 瀹為檯瀹炵幇涓紝JsonlVectorStore 鎸佹湁鍐呭瓨鏁扮粍锛屽彲涓€娆℃€у鍑篭n    let offset = 0;
    let hasMore = true;

    while (hasMore) {
      onProgress?.({
        migrated: migratedCount,
        total,
        percent: Math.round((migratedCount / total) * 100),
        phase: 'reading',
      });

      // 鎵归噺澶勭悊
      const batch: VectorEntry[] = [];

      // 灏濊瘯浠庢簮鎸夋壒娆¤鍙栵紙瀵?JSONL 瀹炵幇锛岄€氳繃鍐呴儴鏂规硶鑾峰彇锛塡n      // 濡傛灉 from 鏀寔 getAll 鏂规硶锛圝sonlVectorStore 鍐呴儴鏈?store.all锛塡n      if (typeof (from as any).getAllEntries === 'function') {
        const allEntries = await (from as any).getAllEntries();
        const batchEntries = allEntries.slice(offset, offset + BATCH_SIZE);
        batch.push(...batchEntries);
        offset += BATCH_SIZE;
        hasMore = offset < allEntries.length;
      } else {
        // 涓嶆敮鎸佹壒閲忚鍙栫殑瀹炵幇锛屽皾璇曢€氳繃 search 闅忔満鍚戦噺鑾峰彇
        hasMore = false;
        if (migratedCount === 0) {
          logger.warn('婧愬瓨鍌ㄤ笉鏀寔鎵归噺璇诲彇锛岃縼绉诲彲鑳戒笉瀹屾暣');
        }
      }

      if (batch.length === 0) {
        hasMore = false;
        continue;
      }

      // 鍐欏叆鐩爣瀛樺偍
      onProgress?.({
        migrated: migratedCount,
        total,
        percent: Math.round((migratedCount / total) * 100),
        phase: 'writing',
      });

      try {
        await to.upsert(batch);
        migratedCount += batch.length;
      } catch (err) {
        failedCount += batch.length;
        void handleError(err, {
          module: 'knowledge:migration',
          action: 'upsert_batch',
          context: { batchSize: batch.length, offset },
        });
      }
    }

    const durationMs = performance.now() - startTime;
    span.setAttribute('knowledge.migration.migrated', migratedCount);
    span.setAttribute('knowledge.migration.duration_ms', durationMs);

    logger.info('鏁版嵁杩佺Щ瀹屾垚', {
      migrated: migratedCount,
      skipped: skippedCount,
      failed: failedCount,
      durationMs,
    });

    onProgress?.({
      migrated: migratedCount,
      total,
      percent: 100,
      phase: 'done',
    });

    return {
      success: failedCount === 0,
      migratedCount,
      skippedCount,
      failedCount,
      durationMs,
    };
  } catch (err) {
    const durationMs = performance.now() - startTime;
    void handleError(err, {
      module: 'knowledge:migration',
      action: 'migrate',
    });
    otel.recordError(span, err as Error);

    onProgress?.({
      migrated: migratedCount,
      total: migratedCount,
      percent: Math.round((migratedCount / (migratedCount + 1)) * 100),
      phase: 'failed',
    });

    return {
      success: false,
      migratedCount,
      skippedCount,
      failedCount,
      durationMs,
      error: (err as Error).message,
    };
  } finally {
    otel.endSpan(span);
  }
}

