/**
 * 鏌ヨ鍙嶅摵绠￠亾 鈥?QueryFeedbackPipeline
 *
 * 浠庢煡璇㈡棩蹇椾腑鎻愬彇楂橀璇濋锛岃嚜鍔ㄥ弽鍝虹煡璇嗗簱锛歕n *   1. 璇诲彇 query_logs 琛ㄤ腑鏈€杩戠殑鏌ヨ璁板綍
 *   2. 鍒嗘瀽楂橀涓婚 / 鐭ヨ瘑鐐筡n *   3. 璋冪敤 LLM 鐢熸垚 wiki 椤甸潰
 *   4. 鍐欏叆 knowledge/ 鐩綍骞舵洿鏂扮储寮昞n *
 * 渚濊禆锛歈ueryLogStore + LLM + IndexManager
 */

import { writeFile } from 'fs/promises';
import { join } from 'path';
import { existsSync } from 'fs';
import { Logger, LogLevel } from '@modules/monitoring';
import { handleError } from '@modules/error';
import type { AIService, AIMessage } from '@modules/ai';
import { AIMessageRole } from '@modules/ai';
import { getQueryLogStore } from '@modules/query/QueryLogStore';
import { resolveKnowledgeDir, resolveDomainDir } from '@modules/core';
import { IndexManager } from './IndexManager';
import { KnowledgeGraph } from './graph/KnowledgeGraph';

const logger = new Logger({
  module: 'knowledge:queryFeedbackPipeline',
  level: LogLevel.INFO,
});

/** 鍙嶅摵閰嶇疆 */
export interface FeedbackConfig {
  /** 鍒嗘瀽绐楀彛锛堟绉掞級锛岄粯璁?7 澶?*/
  windowMs: number;
  /** 鏈€灏忔煡璇㈡鏁版墠绠楃儹鐐癸紝榛樿 3 */
  minQueryCount: number;
  /** 涓€娆℃渶澶氱敓鎴愮殑椤甸潰鏁?*/
  maxPages: number;
}

/** 鍙嶅摵缁撴灉 */
export interface FeedbackResult {
  /** 鍙戠幇鐨勪富棰樻暟 */
  topicsFound: number;
  /** 鏂板缓鐨勯〉闈㈡暟 */
  pagesCreated: number;
  /** 鏇存柊鐨勯〉闈㈡暟 */
  pagesUpdated: number;
  /** 閿欒鏁?*/
  errors: number;
  /** 璇︽儏 */
  detail: string[];
}

const DEFAULT_CONFIG: FeedbackConfig = {
  windowMs: 7 * 24 * 60 * 60 * 1000,
  minQueryCount: 3,
  maxPages: 5,
};

/**
 * 鏌ヨ鍙嶅摵绠￠亾
 *
 * Domain-First 妯″紡涓嬶紝閫氳繃 domainName 鎸囧畾鍩燂細
 *   鐢熸垚鐨勬柊椤甸潰鍐欏叆 domains/{domain}/锛岀储寮曠鐞嗗櫒瀵瑰簲鍩焅n */
export class QueryFeedbackPipeline {
  private aiService: AIService;
  private config: FeedbackConfig;
  private knowledgeRoot: string;
  private indexManager: IndexManager;
  private domainName?: string;

  /**
   * @param aiService LLM 鏈嶅姟
   * @param config 閰嶇疆
   * @param knowledgeRoot 鐭ヨ瘑搴撴牴鐩綍
   * @param domainName 鍩熷悕绉帮紙鍙€夛級銆傛寚瀹氬悗鍙嶅摵鍐欏叆鍩熺洰褰昞n   */
  constructor(
    aiService: AIService,
    config?: Partial<FeedbackConfig>,
    knowledgeRoot?: string,
    domainName?: string
  ) {
    this.aiService = aiService;
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.domainName = domainName;

    if (knowledgeRoot) {
      this.knowledgeRoot = knowledgeRoot;
    } else if (domainName) {
      this.knowledgeRoot = resolveDomainDir(domainName);
    } else {
      this.knowledgeRoot = resolveKnowledgeDir();
    }

    this.indexManager = new IndexManager(this.knowledgeRoot);
  }

  /**
   * 瀹炴椂鍙嶅摵锛氬皢鍗曚釜濂介棶绛斿淇濆瓨涓?wiki 椤甸潰
   * 鍦ㄧ敤鎴疯幏寰楁弧鎰忓洖绛斿悗绔嬪嵆璋冪敤锛岃€岄潪绛夊緟鎵瑰鐞哱n   *
   * @param query 鐢ㄦ埛闂
   * @param answer AI 鍥炵瓟鍐呭
   * @param kind 鍙€夊疄浣撶被鍨嬶紝榛樿"鐭ヨ瘑鏉＄洰"
   * @returns 鍒涘缓鐨勯〉闈?ID锛屽け璐ヨ繑鍥?undefined
   */
  async onGoodAnswer(
    query: string,
    answer: string,
    kind: string = '鐭ヨ瘑鏉＄洰'
  ): Promise<string | undefined> {
    const pageId = this.toPageId(query.slice(0, 40));
    const filename = pageId + '.md';
    const targetPath = join(this.knowledgeRoot, filename);
    const exists = existsSync(targetPath);

    try {
      // 鐢?LLM 灏嗛棶绛旂紪璇戜负缁撴瀯鍖?wiki 椤甸潰
      const content = await this.generateAnswerWikiContent(
        query,
        answer,
        pageId,
        kind,
        exists
      );

      await writeFile(targetPath, content, 'utf-8');

      // 鏇存柊绱㈠紩鍜屾棩蹇梊n      await this.indexManager.updateIndexMd();
      await this.indexManager.appendLog({
        timestamp: Date.now(),
        action: exists ? 'update' : 'compile',
        source: 'query-feedback-real-time',
        pages: [filename],
        detail: `瀹炴椂鍙嶅摵: "${query.slice(0, 30)}..."`,
      });

      // 鍦ㄧ煡璇嗗浘璋变腑娉ㄥ唽瀹炰綋
      try {
        const graph = new KnowledgeGraph();
        await graph.init();
        await graph.addEdge({
          from: `knowledge:entity:${pageId}`,
          to: `knowledge:topic:${this.toPageId(query.slice(0, 20))}`,
          type: 'relates_to',
          direction: 'directed',
          domain: this.domainName || '',
        });
      } catch (err) {
        // 鍥捐氨娉ㄥ唽澶辫触鏄潪鑷村懡鐨刓n      }

      logger.info('瀹炴椂鍙嶅摵瀹屾垚', {
        filename,
        isNew: !exists,
        query: query.slice(0, 30),
      });
      return pageId;
    } catch (e) {
      await handleError(e, {
        module: 'knowledge:feedback',
        action: 'on_good_answer',
        context: { query: query.slice(0, 30) },
      });
      return undefined;
    }
  }

  /**
   * 鐢?LLM 灏嗛棶绛斿缂栬瘧涓?wiki 椤甸潰鍐呭
   */
  private async generateAnswerWikiContent(
    query: string,
    answer: string,
    pageId: string,
    kind: string,
    isUpdate: boolean
  ): Promise<string> {
    const systemPrompt = `浣犳槸涓€涓煡璇嗗簱缂栬緫鍔╂墜銆傚皢浠ヤ笅闂瓟瀵圭紪璇戜负缁撴瀯鍖栫殑 Markdown wiki 椤甸潰銆俓n
${isUpdate ? '杩欐槸瀵瑰凡鏈夐〉闈㈢殑琛ュ厖鏇存柊锛岃淇濈暀鍘熸湁妗嗘灦骞跺彔鍔犳柊淇℃伅銆? : '鍒涘缓鏂伴〉闈€?}

杈撳嚭鏍煎紡瑕佹眰锛歕n1. 浠?YAML frontmatter 寮€澶达紝鍖呭惈: id, title, kind, tags, summary
2. 姝ｆ枃鐢?Markdown 鏍煎紡
3. 鎻愬彇闂瓟涓殑鍏抽敭鐭ヨ瘑鐐圭粍缁囦负缁撴瀯鍖栧唴瀹筡n4. 瀵圭浉鍏虫蹇垫坊鍔?[[]] Wiki 閾炬帴
5. 鏈熬娣诲姞 "## 鐩稿叧姒傚康" 灏忚妭

绀轰緥 frontmatter:
---
id: ${pageId}
title: ${query.slice(0, 30)}
kind: ${kind}
tags: []
summary: 绠€瑕佹憳瑕侊紝涓嶈秴杩?100 瀛梊n---`;

    const messages: AIMessage[] = [
      {
        role: AIMessageRole.SYSTEM,
        content: systemPrompt,
        timestamp: Date.now(),
      },
      {
        role: AIMessageRole.USER,
        content: `闂: ${query}\n\n鍥炵瓟: ${answer}`,
        timestamp: Date.now(),
      },
    ];

    const response = await this.aiService.generate(messages);
    return response.content.trim();
  }

  /**
   * 鎵ц鍙嶅摵锛氬垎鏋愭棩蹇?鈫?鐢熸垚鐭ヨ瘑椤甸潰 鈫?鏇存柊绱㈠紩
   */
  async run(): Promise<FeedbackResult> {
    const result: FeedbackResult = {
      topicsFound: 0,
      pagesCreated: 0,
      pagesUpdated: 0,
      errors: 0,
      detail: [],
    };

    try {
      // 1. 鑾峰彇鐑偣璇濋
      const topics = await this.extractHotTopics();
      result.topicsFound = topics.length;
      result.detail.push(`鍙戠幇 ${topics.length} 涓儹鐐硅瘽棰榒);

      if (topics.length === 0) return result;

      // 2. 妫€鏌ュ摢浜涜瘽棰樺凡鏈夌殑 wiki 椤甸潰
      const existingPages = await this.indexManager.listPages();
      const existingIds = new Set(
        existingPages.map((p) => p.replace(/\.md$/, ''))
      );

      // 3. 瀵规瘡涓儹鐐硅瘽棰樿皟鐢?LLM 鐢熸垚鐭ヨ瘑椤甸潰
      let pageCount = 0;
      for (const topic of topics) {
        if (pageCount >= this.config.maxPages) {
          result.detail.push(
            `杈惧埌鏈€澶ч〉闈㈡暟闄愬埗 (${this.config.maxPages})锛屽仠姝
          );
          break;
        }

        const pageId = this.toPageId(topic.name);
        const action = existingIds.has(pageId) ? 'update' : 'create';

        try {
          const content = await this.generateWikiContent(topic, action);
          const filename = pageId + '.md';
          const targetPath = join(this.knowledgeRoot, filename);

          await writeFile(targetPath, content, 'utf-8');

          if (action === 'create') {
            result.pagesCreated++;
          } else {
            result.pagesUpdated++;
          }

          pageCount++;
          result.detail.push(
            `${action === 'create' ? '鍒涘缓' : '鏇存柊'} 椤甸潰: ${filename}`
          );
        } catch (e) {
          result.errors++;
          result.detail.push(
            `澶勭悊璇濋 "${topic.name}" 澶辫触: ${(e as Error).message}`
          );
          logger.warn('璇濋澶勭悊澶辫触', { topic: topic.name, error: e });
        }
      }

      // 4. 鍦ㄧ煡璇嗗浘璋变腑娉ㄥ唽瀹炰綋
      if (result.pagesCreated + result.pagesUpdated > 0) {
        try {
          const graph = new KnowledgeGraph();
          await graph.init();
          for (const topic of topics) {
            const pageId = this.toPageId(topic.name);
            await graph.addEdge({
              from: `knowledge:topic:${pageId}`,
              to: `knowledge:batch:${Date.now()}`,
              type: 'relates_to',
              direction: 'directed',
              domain: this.domainName || '',
            });
          }
        } catch (err) {
          // 鍥捐氨娉ㄥ唽澶辫触鏄潪鑷村懡鐨刓n        }
      }

      // 5. 鏇存柊绱㈠紩鍜屾棩蹇梊n      await this.indexManager.updateIndexMd();
      await this.indexManager.appendLog({
        timestamp: Date.now(),
        action: 'compile',
        source: 'query-feedback-pipeline',
        pages: [],
        detail: `鍙嶅摵 ${result.pagesCreated} 涓柊椤甸潰, 鏇存柊 ${result.pagesUpdated} 涓〉闈,
      });
    } catch (e) {
      result.errors++;
      result.detail.push(`绠￠亾鎵ц澶辫触: ${(e as Error).message}`);
      await handleError(e, {
        module: 'knowledge:feedback',
        action: 'execute_pipeline',
      });
    }

    return result;
  }

  /**
   * 鍒嗘瀽鏌ヨ鏃ュ織鎻愬彇鐑偣璇濋
   */
  private async extractHotTopics(): Promise<
    Array<{ name: string; count: number }>
  > {
    const store = getQueryLogStore();
    const now = Date.now();
    const cutoff = now - this.config.windowMs;

    // 鑾峰彇鏈€杩戠殑鏌ヨ璁板綍
    const logs = await store.query({
      startTime: cutoff,
      endTime: now,
      limit: 500,
    });

    // 鎸?sessionId 鑱氬悎鏌ヨ锛屾彁鍙?query 绫诲瀷璁板綍
    const queryTexts: string[] = [];

    for (const log of logs) {
      // 浠?metadata 涓彁鍙栨煡璇㈡枃鏈琝n      if (log.type === 'query' && log.metadata) {
        const meta = log.metadata as Record<string, unknown>;
        if (typeof meta.query === 'string' && meta.query.trim()) {
          queryTexts.push(meta.query.trim());
        }
      }
    }

    if (queryTexts.length < this.config.minQueryCount) {
      return [];
    }

    // 浣跨敤 LLM 浠庢煡璇㈡棩蹇椾腑鎻愬彇鐑偣璇濋
    return await this.analyzeQueriesWithLLM(queryTexts);
  }

  /**
   * 鐢?LLM 鍒嗘瀽鏌ヨ鏂囨湰鎻愬彇璇濋
   */
  private async analyzeQueriesWithLLM(
    queries: string[]
  ): Promise<Array<{ name: string; count: number }>> {
    const sample = queries.slice(0, 100).join('\n');

    const systemPrompt = `浣犳槸涓€涓煡璇嗗簱鍒嗘瀽鍔╂墜銆傚垎鏋愪互涓嬬敤鎴锋煡璇㈠垪琛紝鎻愬彇鍑虹幇棰戠巼鏈€楂樼殑 3-5 涓煡璇嗙偣/璇濋銆俓n
