/**
 * RerankService 鈥?妫€绱㈢粨鏋滈噸鎺掑簭鏈嶅姟
 *
 * 閫氳繃 ModelRouter.resolve('reranking') 鑾峰彇鐢ㄦ埛閰嶇疆鐨勯噸鎺掑簭妯″瀷锛孿n * 璋冪敤 Provider 鐨?rerank API 瀵规绱㈢粨鏋滆繘琛屼簩娆＄簿鎺掋€俓n *
 * 浣跨敤鏂瑰紡锛歕n *   1. 鐢ㄦ埛鍦ㄣ€屾ā鍨嬬鐞?鈫?浠诲姟鍒嗗伐銆嶉厤缃?reranking 浠诲姟瀵瑰簲鐨勬ā鍨媆n *   2. RerankService 閫氳繃 modelRouter 鑷姩鑾峰彇閰嶇疆
 *   3. KnowledgeRouter.search() 铻嶅悎鍚庤嚜鍔ㄨ皟鐢?rerank()
 *
 * 闄嶇骇绛栫暐锛歕n *   - 鐢ㄦ埛鏈厤缃?reranking 妯″瀷 鈫?璺宠繃閲嶆帓搴忥紙INFO 鏃ュ織锛塡n *   - Provider 涓嶆敮鎸?rerank 鈫?璺宠繃閲嶆帓搴忥紙WARNING 鏃ュ織锛塡n *   - API 璋冪敤澶辫触 鈫?璺宠繃閲嶆帓搴忥紙ERROR 鏃ュ織锛塡n *
 * 绂佹纭紪鐮佹ā鍨嬪悕銆俓n */

import { modelRouter } from '@modules/ai';
import { providerRegistry } from '@modules/ai/providers/ProviderRegistry';
import type {
  RerankRequest,
  RerankResult,
} from '@modules/ai/providers/AIProvider';
import { LogLevel } from '@modules/monitoring';
import { OTelAwareLogger } from '@modules/monitoring/logs/OTelAwareLogger';
import { getOTelTracing } from '@modules/monitoring/otel/OTelTracing';

const logger = new OTelAwareLogger({
  module: 'knowledge:rerank',
  level: LogLevel.INFO,
});

/** 閲嶆帓搴忚緭鍏ユ枃妗?*/
export interface RerankDocument {
  id: string;
  content: string;
  score: number;
  metadata?: Record<string, unknown>;
}

/**
 * 瀵规绱㈢粨鏋滆繘琛岄噸鎺掑簭
 *
 * @param query 鍘熷鏌ヨ
 * @param docs 妫€绱㈢粨鏋滄枃妗ｅ垪琛╘n * @param topN 杩斿洖鏉℃暟锛岄粯璁ゅ彇鍏ㄩ儴
 * @returns 鎸?relevanceScore 闄嶅簭鎺掑垪鐨勬枃妗n */
export async function rerankDocs(
  query: string,
  docs: RerankDocument[],
  topN?: number
): Promise<RerankDocument[]> {
  if (docs.length === 0) return [];

  const otel = getOTelTracing();
  const span = otel.startSpan('knowledge.rerank', {
    'knowledge.rerank.doc_count': docs.length,
  });

  try {
    // 1. 閫氳繃 ModelRouter 鑾峰彇鐢ㄦ埛閰嶇疆鐨?reranking 妯″瀷
    const modelKey = modelRouter.resolve('reranking');
    if (!modelKey) {
      logger.info('閲嶆帓搴忚烦杩囷細鏈厤缃?reranking 浠诲姟妯″瀷');
      span.setAttribute('knowledge.rerank.skipped', 'not_configured');
      return docs;
    }

    // 2. 閫氳繃 ProviderRegistry 鑾峰彇 Provider
    const provider = providerRegistry.getByModel(modelKey);
    // 绫诲瀷瀹堝崼锛氭鏌?rerank 鏂规硶鏄惁瀛樺湪
    if (!provider || typeof (provider as any).rerank !== 'function') {
      logger.warn('閲嶆帓搴忚烦杩囷細Provider 涓嶆敮鎸?rerank', {
        model: modelKey,
      });
      span.setAttribute('knowledge.rerank.skipped', 'unsupported');
      return docs;
    }

    // 3. 璋冪敤 rerank API
    const contents = docs.map((d) => d.content);
    const request: RerankRequest = {
      query,
      documents: contents,
      topN: topN ?? Math.min(docs.length, 10),
      returnDocuments: false,
    };

    logger.info('璋冪敤閲嶆帓搴?, {
      model: modelKey,
      docCount: contents.length,
    });

    const result: RerankResult = await (provider as any).rerank(request);

    span.setAttribute('knowledge.rerank.result_count', result.results.length);

    // 4. 鎸?relevanceScore 閲嶆柊鎺掑簭
    return result.results
      .sort((a, b) => b.relevanceScore - a.relevanceScore)
      .map((r) => ({
        ...docs[r.index],
        score: r.relevanceScore,
      }));
  } catch (err) {
    logger.error('閲嶆帓搴忓け璐ワ紝闄嶇骇杩斿洖鍘熷缁撴灉', {
      error: (err as Error).message,
    });
    otel.recordError(span, err as Error);
    return docs;
  } finally {
    otel.endSpan(span);
  }
}

/** 鍏煎绫诲舰寮忕殑瀵煎嚭锛堢敤浜庢瀯閫犲嚱鏁版敞鍏ュ満鏅級 */
export class RerankService {
  async rerank(
    query: string,
    docs: RerankDocument[],
    topN?: number
  ): Promise<RerankDocument[]> {
    return rerankDocs(query, docs, topN);
  }
}

