/**
 * 璇箟绱㈠紩鏇存柊鍣╘n *
 * 鐩戝惉 knowledge:changed 浜嬩欢锛屽鏂板/鏇存柊鐨勭煡璇嗘枃浠惰繘琛屽垎鍧椼€佸祵鍏ワ紝
 * 骞跺皢缁撴灉澧為噺杩藉姞鍒?SemanticStore 涓€俓n */

import { readFile, stat } from 'fs/promises';
import { relative, resolve } from 'path';

import { LogLevel } from '@modules/monitoring';
import { OTelAwareLogger } from '@modules/monitoring/logs/OTelAwareLogger';
import { handleError } from '@modules/error';
import type { EventBus } from '@modules/core';
import type { EmbeddingManager } from '@modules/ai';
import { chunkText, autoChunk } from '@modules/knowledge/semantic/chunker';
import type { IndexEntry } from '@modules/knowledge/semantic/store';
import type { IVectorStore } from '@modules/knowledge/semantic/IVectorStore';
import { createVectorStore } from '@modules/knowledge/semantic/VectorStoreFactory';
import { JsonlVectorStore } from '@modules/knowledge/semantic/JsonlVectorStore';

const logger = new OTelAwareLogger({
  module: 'knowledge:semantic:updater',
  level: LogLevel.INFO,
});

/** 鐭ヨ瘑鍙樻洿浜嬩欢杞借嵎 */
export interface KnowledgeChangedEvent {
  action: 'created' | 'updated' | 'deleted';
  filePath: string;
}

/** SemanticIndexUpdater 閫夐」 */
export interface SemanticIndexUpdaterOptions {
  /** 绱㈠紩瀛樺偍鐩綍 */
  indexDir: string;
  /** 宓屽叆 Provider ID */
  embedProvider?: string;
  /** 宓屽叆妯″瀷鍚嶇О */
  embedModel?: string;
  /** 鍒嗗潡绐楀彛琛屾暟锛岄粯璁?60 */
  windowLines?: number;
  /** 鍒嗗潡閲嶅彔琛屾暟锛岄粯璁?12 */
  overlap?: number;
}

/**
 * 璇箟绱㈠紩鏇存柊鍣╘n *
 * 鐩戝惉浜嬩欢鎬荤嚎涓婄殑 knowledge:changed 浜嬩欢锛岃嚜鍔ㄥ皢鐭ヨ瘑鏂囦欢澧為噺绱㈠紩鍒?SemanticStore銆俓n * 鍒犻櫎浜嬩欢琚拷鐣ワ紙鐢卞叏閲忛噸寤烘垨瀹氭湡 GC 娓呯悊锛夈€俓n */
export class SemanticIndexUpdater {
  private store: IVectorStore;
  private embeddingManager: EmbeddingManager;
  private options: Required<SemanticIndexUpdaterOptions>;
  private initialized = false;

  constructor(
    embeddingManager: EmbeddingManager,
    options: SemanticIndexUpdaterOptions,
    eventBus?: EventBus
  ) {
    this.embeddingManager = embeddingManager;
    this.options = {
      embedProvider: 'local',
      embedModel: 'nomic-embed-text',
      windowLines: 60,
      overlap: 12,
      ...options,
    };

    // 浣跨敤宸ュ巶鍒涘缓鍚戦噺瀛樺偍锛堟牴鎹?VECTOR_STORE 鐜鍙橀噺閫夋嫨瀹炵幇锛塡n    this.store = createVectorStore(this.options.indexDir, {
      provider: this.options.embedProvider,
      model: this.options.embedModel,
    });

    eventBus?.subscribe('knowledge:changed', (event: unknown) => {
      const evt = event as KnowledgeChangedEvent;
      if (evt.action !== 'deleted') {
        this.appendIndex(evt.filePath).catch((err) => {
          void handleError(err, {
            module: 'knowledge:semantic',
            action: 'append_index',
            context: { filePath: evt.filePath },
          });
        });
      }
    });
  }

  /**
   * 鍒濆鍖栵細鍔犺浇宸叉湁绱㈠紩
   */
  async initialize(): Promise<void> {
    if (this.initialized) return;
    if (this.store instanceof JsonlVectorStore) {
      await this.store.initialize();
    }
    this.initialized = true;
  }

  /**
   * 瀵瑰崟涓煡璇嗘枃浠惰繘琛屽閲忕储寮昞n   */
  async appendIndex(filePath: string): Promise<void> {
    if (!this.initialized) {
      await this.initialize();
    }

    try {
      const content = await readFile(filePath, 'utf-8');
      const fileStat = await stat(filePath);

      // 浠庣粷瀵硅矾寰勬彁鍙栫浉瀵硅矾寰勶紙鐩稿浜?indexDir 鐨勭埗鐩綍锛塡n      const indexParent = resolve(this.options.indexDir, '..');
      const relPath = relative(indexParent, filePath).replace(/\\/g, '/');

      // 鍒嗗潡锛堜娇鐢ㄨ嚜閫傚簲绛栫暐锛氭爣棰樻劅鐭?鈫?琛岀獥鍙?fallback锛塡n      const chunks = autoChunk(content, relPath, {
        windowLines: this.options.windowLines,
        overlap: this.options.overlap,
      });

      if (chunks.length === 0) return;

      // 宓屽叆
      const entries: IndexEntry[] = [];
      const mtimeMs = fileStat.mtimeMs;

      for (const chunk of chunks) {
        try {
          const vec = await this.embeddingManager.embedOne(chunk.text);
          if (vec && vec.length > 0) {
            entries.push({
              path: chunk.path,
              startLine: chunk.startLine,
              endLine: chunk.endLine,
              text: chunk.text,
              embedding: new Float32Array(vec),
              mtimeMs,
            });
          }
        } catch (err) {
          logger.warn('鍒嗗潡宓屽叆澶辫触锛岃烦杩?, {
            path: chunk.path,
            error: String(err),
          });
        }
      }

      if (entries.length > 0) {
        // 鍏堝垹闄ゆ棫绱㈠紩锛屽啀鍐欏叆鏂扮储寮昞n        await this.store.deleteByPath(relPath);
        await this.store.upsert(
          entries.map((e) => ({
            id: `${e.path}#L${e.startLine}-L${e.endLine}`,
            path: e.path,
            startLine: e.startLine,
            endLine: e.endLine,
            text: e.text,
            embedding: e.embedding,
            mtimeMs: e.mtimeMs,
          }))
        );
        logger.info('璇箟绱㈠紩澧為噺鏇存柊瀹屾垚', {
          filePath,
          entriesAdded: entries.length,
        });
      }
    } catch (error) {
      const msg = error instanceof Error ? error.message : String(error);
      logger.error('璇箟绱㈠紩澧為噺鏇存柊澶辫触', { filePath, error: msg });
    }
  }
}

