  /** 寮哄埗閲嶆柊鎽勫彇锛屽嵆浣挎枃浠跺凡瀛樺湪 */
  force?: boolean;
  /** 鏄惁璺宠繃 AI 鍒嗙被锛堝揩閫熸ā寮忥級 */
  skipClassification?: boolean;
  /** 鑷畾涔夊垎绫?*/
