  /** 婧愭枃浠舵弿杩?*/
  description?: string;
}

/**
 * 闇€瑕佸交搴曡烦杩囩殑鏂囦欢鎵╁睍鍚嶏紙缂栬瘧浜х墿銆佸帇缂╁寘銆佸姩鎬佸簱绛夛級
 * 杩欎簺鏂囦欢鏀惧湪鐭ヨ瘑搴撲腑姣棤浠峰€硷紝鐩存帴璺宠繃
 */
const BINARY_SKIP_EXTENSIONS = new Set([
  '.exe',
  '.dll',
  '.so',
  '.dylib',
  '.o',
  '.obj',
  '.lib',
  '.zip',
  '.tar',
  '.gz',
  '.rar',
  '.7z',
  '.pyc',
  '.pyo',
  '.class',
  '.jar',
  '.wasm',
]);

/**
 * 浠呰惤搴撲絾涓嶈繘琛?AI 鍒嗙被鐨勫獟浣撴枃浠舵墿灞曞悕
 * 杩欎簺鏂囦欢浼氳澶嶅埗鍒?raw/ 鐩綍骞堕檮甯﹀厓鏁版嵁锛孿n * 浣嗕笉浼氬皾璇?AI 鍒嗙被锛圓I 鏃犳硶璇诲彇鍥剧墖/闊宠棰戝唴瀹癸級
 */
const MEDIA_ONLY_EXTENSIONS = new Set([
  '.jpg',
  '.jpeg',
  '.png',
  '.gif',
  '.bmp',
  '.webp',
  '.ico',
  '.mp3',
  '.wav',
  '.mp4',
  '.avi',
  '.mov',
  '.woff',
  '.woff2',
  '.ttf',
  '.eot',
]);

/**
 * 闇€瑕佽烦杩囩殑鐩綍妯″紡
 */
const SKIP_DIRECTORIES = [
  'node_modules',
  '.git',
  '.svn',
  '__pycache__',
  '.venv',
  'venv',
  'env',
  '.tox',
  'dist',
  'build',
  '.next',
  '.turbo',
  'target',
  'bin',
  'obj',
];

function isEditableTextFile(ext: string): boolean {
  const textExtensions = new Set([
    '.txt',
    '.md',
    '.markdown',
    '.rst',
    '.json',
    '.yaml',
    '.yml',
    '.xml',
    '.html',
    '.htm',
    '.css',
    '.scss',
    '.less',
    '.ts',
    '.tsx',
    '.js',
    '.jsx',
    '.mjs',
    '.cjs',
    '.py',
    '.rs',
    '.go',
    '.java',
    '.cpp',
    '.c',
    '.h',
    '.hpp',
    '.rb',
    '.php',
    '.swift',
    '.kt',
    '.scala',
    '.sh',
    '.bash',
    '.zsh',
    '.ps1',
    '.bat',
    '.cmd',
    '.toml',
    '.ini',
    '.cfg',
    '.conf',
    '.env',
    '.sql',
    '.graphql',
    '.proto',
    '.vue',
    '.svelte',
    '.astro',
    '.dockerfile',
    '.gitignore',
    '.editorconfig',
    '.svg',
  ]);
  return textExtensions.has(ext);
}

function shouldSkipFile(filePath: string): boolean {
  const ext = extname(filePath).toLowerCase();

  // 鐢ㄦ埛閰嶇疆鐧藉悕鍗曟ā寮忥細浠呰惤搴?include 鍒楄〃涓殑绫诲瀷
  const mergedConfig = configManager.getMergedConfig();
  const includeExts = mergedConfig['knowledge.ingest.include'] as
    | string[]
    | undefined;
  if (includeExts && Array.isArray(includeExts) && includeExts.length > 0) {
    return !includeExts.some((e: string) => e.toLowerCase() === ext);
  }

  // 鐢ㄦ埛閰嶇疆榛戝悕鍗曟ā寮忥細鍦ㄥ唴缃鍒欏熀纭€涓婇澶栨帓闄n  const excludeExts = mergedConfig['knowledge.ingest.exclude'] as
    | string[]
    | undefined;
  if (excludeExts && Array.isArray(excludeExts) && excludeExts.length > 0) {
    if (excludeExts.some((e: string) => e.toLowerCase() === ext)) return true;
  }

  // 鍐呯疆榛樿瑙勫垯
  if (BINARY_SKIP_EXTENSIONS.has(ext)) return true;
  if (SKIP_DIRECTORIES.some((dir) => filePath.includes(dir))) return true;

  return false;
}

function isMediaOnlyFile(filePath: string): boolean {
  const ext = extname(filePath).toLowerCase();
  return MEDIA_ONLY_EXTENSIONS.has(ext);
}

/**
 * 鏂囦欢鑷姩鎽勫彇鏈嶅姟
 *
 * @deprecated 瀹℃壒鑱岃矗宸茶縼绉昏嚦 KnowledgeImportTool锛屾湰鏈嶅姟淇濈暀鐢ㄤ簬鍚庡彴鑷姩鎽勫彇銆俓n *             瀵逛簬鐢ㄦ埛涓诲姩瑙﹀彂鐨勬枃浠跺鍏ワ紝璇蜂娇鐢?KnowledgeImportTool锛堝惈 Inbox 瀹℃壒锛夈€俓n */
export class FileIngestionService {
  private knowledgeRoot: string;
  private rawDir: string;
  private aiService: AIService | null = null;

  constructor(aiService?: AIService) {
    this.knowledgeRoot = join(resolvePyappHome(), 'knowledge');
    this.rawDir = join(this.knowledgeRoot, 'raw');
    this.aiService = aiService || null;
  }

  /**
   * 璁剧疆 AI 鏈嶅姟瀹炰緥
   */
  setAIService(service: AIService): void {
    this.aiService = service;
  }

  /**
   * 鎽勫彇鍗曚釜鏂囦欢
   * 灏嗘枃浠跺唴瀹瑰鍒跺埌鐭ヨ瘑搴?raw/ 鐩綍锛屽苟闄勫甫鍏冩暟鎹枃浠禱n   */
  async ingestFile(
    filePath: string,
    source: IngestionSource,
    options: IngestionOptions = {}
  ): Promise<IngestionResult> {
    const resolvedPath = resolve(filePath);

    if (shouldSkipFile(resolvedPath)) {
      return {
        success: false,
        rawPath: '',
        fileName: basename(resolvedPath),
        category: 'other',
        action: 'skipped',
        error: '鏂囦欢绫诲瀷琚烦杩囷紙浜岃繘鍒躲€佸ぇ鏂囦欢鎴栫郴缁熺洰褰曪級',
      };
    }

    if (!existsSync(resolvedPath)) {
      return {
        success: false,
        rawPath: '',
        fileName: basename(resolvedPath),
        category: 'other',
        action: 'error',
        error: `鏂囦欢涓嶅瓨鍦? ${resolvedPath}`,
      };
    }

    try {
      await mkdir(this.rawDir, { recursive: true });

      const fileName = basename(resolvedPath);
      const rawTargetPath = join(this.rawDir, fileName);

      if (!options.force && existsSync(rawTargetPath)) {
        return {
          success: true,
          rawPath: rawTargetPath,
          fileName,
          category: options.category || 'other',
          action: 'skipped',
        };
      }

      let category = options.category || 'other';

      if (isMediaOnlyFile(resolvedPath)) {
        // 濯掍綋鏂囦欢锛氭寜绫诲瀷鍒嗛厤榛樿鍒嗙被锛屼笉灏濊瘯 AI 鍒嗙被
        const mediaCategory = this.getMediaCategory(resolvedPath);
        category = options.category || mediaCategory;
      } else if (!options.skipClassification && this.aiService) {
        try {
          const content = await this.safeReadFile(resolvedPath);
          if (content) {
            category = await this.classifyContent(
              fileName,
              content.slice(0, 3000)
            );
          }
        } catch (err) {
          logger.warning('AI 鍒嗙被澶辫触锛屼娇鐢ㄩ粯璁ゅ垎绫?, { fileName });
        }
      }

      await copyFile(resolvedPath, rawTargetPath);

      await this.writeMetadata(fileName, {
        source,
        category,
        originalPath: resolvedPath,
        ingestedAt: new Date().toISOString(),
        description: options.description || '',
      });

      logger.info('鏂囦欢宸叉憚鍙栧埌鐭ヨ瘑搴?, {
        fileName,
        category,
        source,
        target: rawTargetPath,
      });

      return {
        success: true,
        rawPath: rawTargetPath,
        fileName,
        category,
        action: 'created',
      };
    } catch (error) {
      const errMsg = error instanceof Error ? error.message : String(error);
      await handleError(error, {
        module: 'knowledge:ingestion',
        action: 'ingest_file',
        context: { filePath },
      });
      return {
        success: false,
        rawPath: '',
        fileName: basename(resolvedPath),
        category: 'other',
        action: 'error',
        error: errMsg,
      };
    }
  }

  /**
   * 鎵归噺鎽勫彇澶氫釜鏂囦欢
   */
  async ingestFiles(
    filePaths: string[],
    source: IngestionSource,
    options: IngestionOptions = {}
  ): Promise<IngestionResult[]> {
    const results: IngestionResult[] = [];
    for (const filePath of filePaths) {
      const result = await this.ingestFile(filePath, source, options);
      results.push(result);
    }
    return results;
  }

  /**
   * 鑾峰彇 raw 鐩綍涓湭缂栬瘧鐨勬枃浠跺垪琛╘n   */
  async getUncompiledFiles(): Promise<string[]> {
    if (!existsSync(this.rawDir)) return [];

    const { readdir } = await import('fs/promises');
    const files = await readdir(this.rawDir);

    return files
      .filter((f) => f.endsWith('.txt') || f.endsWith('.md'))
      .map((f) => join(this.rawDir, f));
  }

  /**
   * 鑾峰彇 raw 鐩綍缁熻淇℃伅
   */
  async getStats(): Promise<{
    totalFiles: number;
    categories: Record<string, number>;
  }> {
    if (!existsSync(this.rawDir)) {
      return { totalFiles: 0, categories: {} };
    }

    const { readdir } = await import('fs/promises');
    const files = await readdir(this.rawDir);
    const metaFiles = files.filter((f) => f.endsWith('.meta.json'));
    const categories: Record<string, number> = {};

    for (const metaFile of metaFiles) {
      try {
        const content = await readFile(join(this.rawDir, metaFile), 'utf-8');
        const meta = JSON.parse(content);
        const cat = meta.category || 'other';
        categories[cat] = (categories[cat] || 0) + 1;
      } catch (err) {
        // 璺宠繃鎹熷潖鐨勫厓鏁版嵁鏂囦欢
      }
    }

    return {
      totalFiles: files.filter((f) => !f.endsWith('.meta.json')).length,
      categories,
    };
  }

  /**
   * 鏍规嵁濯掍綋鏂囦欢鎵╁睍鍚嶈幏鍙栭粯璁ゅ垎绫籠n   */
  private getMediaCategory(filePath: string): FileCategory {
    const ext = extname(filePath).toLowerCase();
    const imageExtensions = new Set([
      '.jpg',
      '.jpeg',
      '.png',
      '.gif',
      '.bmp',
      '.webp',
      '.ico',
    ]);
    const audioExtensions = new Set(['.mp3', '.wav']);
    const videoExtensions = new Set(['.mp4', '.avi', '.mov']);
    const fontExtensions = new Set(['.woff', '.woff2', '.ttf', '.eot']);

    if (imageExtensions.has(ext)) return 'reference';
    if (audioExtensions.has(ext)) return 'reference';
    if (videoExtensions.has(ext)) return 'reference';
    if (fontExtensions.has(ext)) return 'reference';

    return 'other';
  }

  /**
   * 浣跨敤 AI 瀵规枃浠跺唴瀹硅繘琛屽垎绫籠n   */
  private async classifyContent(
    fileName: string,
    contentPreview: string
  ): Promise<FileCategory> {
    if (!this.aiService) return 'reference';

    const systemPrompt = `浣犳槸涓€涓枃浠跺垎绫诲姪鎵嬨€傛牴鎹枃浠跺悕鍜屽唴瀹归瑙堬紝鍒ゆ柇鏂囦欢鏈€閫傚悎鐨勫垎绫汇€俓n
鍙€夌殑鍒嗙被锛歕n- documentation: 椤圭洰鏂囨。銆佹暀绋嬨€丄PI 鍙傝€冦€佽鏄庢枃浠禱n- note: 涓汉绗旇銆佸蹇樺綍銆佸涔犵瑪璁癨n- reference: 鍙傝€冭祫鏂欍€佹妧鏈墜鍐屻€佽鑼冩枃妗n- project: 椤圭洰璁″垝銆侀渶姹傛枃妗ｃ€佽璁℃枃妗n- code: 婧愪唬鐮佹枃浠讹紙铏界劧鍙兘琚烦杩囷級
- config: 閰嶇疆鏂囦欢銆佺幆澧冮厤缃€佷緷璧栭厤缃甛n- data: 鏁版嵁鏂囦欢銆丆SV銆佹棩蹇楁枃浠禱n- other: 鍏朵粬绫诲瀷

浠呰繑鍥炲垎绫诲悕绉帮紝涓嶈鏈夊叾浠栨枃瀛椼€俙;

    const messages: AIMessage[] = [
      {
        role: AIMessageRole.SYSTEM,
        content: systemPrompt,
        timestamp: Date.now(),
      },
      {
        role: AIMessageRole.USER,
        content: `鏂囦欢鍚? ${fileName}\n\n鍐呭棰勮:\n${contentPreview}`,
        timestamp: Date.now(),
      },
    ];

    try {
      const response = await this.aiService.generate(messages);
      const category = response.content.trim().toLowerCase() as FileCategory;
      const validCategories: FileCategory[] = [
        'documentation',
        'note',
        'reference',
        'project',
        'code',
        'config',
        'data',
        'other',
      ];
      return validCategories.includes(category) ? category : 'reference';
    } catch (err) {
      return 'reference';
    }
  }

  /**
   * 鍐欏叆鍏冩暟鎹枃浠禱n   */
  private async writeMetadata(
    fileName: string,
    metadata: {
      source: IngestionSource;
      category: FileCategory;
      originalPath: string;
      ingestedAt: string;
      description: string;
    }
  ): Promise<void> {
    const metaPath = join(this.rawDir, `${fileName}.meta.json`);
    await writeFile(metaPath, JSON.stringify(metadata, null, 2), 'utf-8');
  }

  /**
   * 瀹夊叏璇诲彇鏂囦欢锛堜粎鏂囨湰鏂囦欢锛塡n   */
  private async safeReadFile(filePath: string): Promise<string | null> {
    try {
      const ext = extname(filePath).toLowerCase();
      if (!isEditableTextFile(ext)) return null;

      const stats = await stat(filePath);
      if (stats.size > 1024 * 1024) return null;

      return await readFile(filePath, 'utf-8');
    } catch (err) {
      return null;
    }
  }
}

/**
 * 鑾峰彇榛樿鐨?FileIngestionService 瀹炰緥
