/** 鏍规嵁 Inbox 绫诲瀷鐢熸垚榛樿鎿嶄綔鎸夐挳 */
function _buildDefaultActions(type: InboxItemType): Array<{
  label: string;
  reply: string;
  style: 'primary' | 'danger' | 'secondary';
}> {
  if (type === 'approval') {
    return [
      { label: '鎵瑰噯', reply: 'approve', style: 'primary' },
      { label: '鎷掔粷', reply: 'reject', style: 'danger' },
    ];
  }
  if (type === 'question') {
    return [
      { label: '纭', reply: 'confirm', style: 'primary' },
      { label: '鍙栨秷', reply: 'cancel', style: 'secondary' },
    ];
  }
  return [
    { label: '鎺堟潈', reply: 'authorize', style: 'primary' },
    { label: '鎷掔粷', reply: 'deny', style: 'danger' },
  ];
}

/** 灏?Inbox block 娉ㄥ叆鍒拌亰澶╂秷鎭腑锛堥€氳繃 SessionGateway 鎸佷箙鍖栫绾匡級 */
async function _injectInboxBlock(
  sessionId: string,
  messageId: string | undefined,
  data: Record<string, unknown>
): Promise<void> {
  const { randomUUID } = await import('crypto');
  const { createSessionGateway } =
    await import('@modules/session/SessionGateway.js');

  const gateway = createSessionGateway();
  const allMessages = await gateway.getMessages(sessionId);

  // 濡傛灉鏈寚瀹?messageId锛岃嚜鍔ㄦ煡鎵捐浼氳瘽鏈€鏂扮殑鍔╂墜娑堟伅
  let targetMessageId = messageId;
  if (!targetMessageId) {
    const lastAssistant = allMessages
      .filter((m) => m.role === 'assistant')
      .pop();
    if (!lastAssistant) return;
    targetMessageId = lastAssistant.id;
  }

  // 璇诲彇褰撳墠娑堟伅骞惰拷鍔?inbox block
  const msg = allMessages.find((m) => m.id === targetMessageId);
  if (!msg) return;

  const existingBlocks = (msg.blocks ?? []) as unknown as Record<
    string,
    unknown
  >[];
  const updatedBlocks = [
    ...existingBlocks,
    {
      id: randomUUID(),
      type: 'inbox' as const,
      content: '',
      inboxData: data,
    },
  ];

  await gateway.updateMessage(sessionId, targetMessageId, {
    ...msg,
    blocks: updatedBlocks as any,
  });
}

