  /**
   * 寤惰繜鍒濆鍖?LLM 瀹㈡埛绔痋n   *
   * 纭繚 ChatManager 鐨?LLM 瀹㈡埛绔湪浣跨敤鍓嶅凡鍒濆鍖栥€俓n   * 鑻?ChatManager 宸叉湁 LLM 瀹㈡埛绔紙濡?REPL 璺緞宸茶皟鐢?initializeChatManager锛夛紝鍒欒烦杩囥€俓n   * 杩欐槸 HTTP API 璺緞涓?LLM 瀹㈡埛绔己澶辩殑琛ユ晳鏈哄埗銆俓n   */
  private async ensureLLMClientInitialized(): Promise<void> {
    if (this._llmReady) return;

    // 閫氳繃 try-catch 鎺㈡祴 ChatManager 鏄惁宸叉湁 LLM 瀹㈡埛绔痋n    try {
      this.chatManager.getLLMClient();
