   */
  async continueInteraction(
    sessionId: string,
    questionId: string,
    answers: string[]
  ): Promise<ChatResponse> {
    try {
      const message = await this.chatManager.continueInteraction(
        sessionId,
        questionId,
        answers
      );

      const content =
        typeof message.content === 'string'
          ? message.content
          : message.content
              .map((block) => ('value' in block ? block.value : ''))
              .join('');

      return {
        content,
        sessionId: message.sessionId || sessionId,
        messageId: message.id,
        finishReason: 'stop',
      };
    } catch (error) {
      const msg = error instanceof Error ? error.message : String(error);
      logger.error('continueInteraction 澶辫触', { error: msg });
      return {
        content: '',
        sessionId,
        messageId: '',
        finishReason: 'error',
      };
    }
  }

  /**
   * P0: 闄勪欢娓呯悊 鈥?鍒犻櫎娑堟伅鍚庢竻鐞嗗鍎块檮浠舵枃浠禱n   * 妫€鏌ュ紩鐢ㄨ鏁帮紝浠呭綋闄勪欢涓嶈浠讳綍鏈垹闄ゆ秷鎭紩鐢ㄦ椂鎵嶅垹闄ゆ枃浠禱n   */
  private async cleanupOrphanAttachments(
    sessionId: string,
    deletedMessageIds: string[]
  ): Promise<void> {
    try {
      const session = this.sessionManager.getSession(sessionId);
      if (!session) return;

      const allMessages = session.messages || [];
      const deletedSet = new Set(deletedMessageIds);

      // 鏀堕泦琚垹娑堟伅鐨勯檮浠?URL 鍒楄〃
      const deletedAttachments = new Map<
        string,
        { name: string; url: string }
      >();
      for (const msg of allMessages) {
        if (deletedSet.has(msg.id)) {
          const attachments = (msg as any).attachments as
            | Array<{ name: string; url: string }>
            | undefined;
          if (attachments) {
            for (const att of attachments) {
              if (att.url) {
                deletedAttachments.set(att.url, att);
              }
            }
          }
        }
      }

      if (deletedAttachments.size === 0) return;

      // 妫€鏌ュ墿浣欐秷鎭槸鍚﹀紩鐢ㄧ浉鍚岀殑闄勪欢锛堝紩鐢ㄨ鏁帮級
      const remainingRefs = new Set<string>();
      for (const msg of allMessages) {
        if (!deletedSet.has(msg.id)) {
          const attachments = (msg as any).attachments as
            | Array<{ url: string }>
            | undefined;
          if (attachments) {
            for (const att of attachments) {
              if (att.url) {
                remainingRefs.add(att.url);
              }
            }
          }
        }
      }

      // 娓呯悊闆跺紩鐢ㄩ檮浠禱n      const { unlink } = await import('fs/promises');
      let cleanedCount = 0;
      for (const [url, att] of deletedAttachments) {
        if (!remainingRefs.has(url)) {
          try {
            // 灏濊瘯浠?URL 瑙ｆ瀽鏂囦欢璺緞
            // URL 鏍煎紡鍙兘鏄?file:///path 鎴栫粷瀵硅矾寰刓n            let filePath = url;
            if (url.startsWith('file://')) {
              filePath = url.slice(7);
            }
            if (filePath.includes('attachments')) {
              await unlink(filePath);
              cleanedCount++;
            }
          } catch {
            // 鏂囦欢涓嶅瓨鍦ㄦ垨鏃犳硶鍒犻櫎锛岃烦杩嘰n          }
        }
      }

      if (cleanedCount > 0) {
        logger.info('闄勪欢娓呯悊瀹屾垚', {
          sessionId,
          deletedMessageCount: deletedMessageIds.length,
          cleanedAttachments: cleanedCount,
        });
      }
    } catch (err) {
      // 闈炲叧閿矾寰勶紝澶辫触涓嶅奖鍝嶄富娴佺▼
      logger.debug('闄勪欢娓呯悊寮傚父', {
        error: err instanceof Error ? err.message : String(err),
      });
    }
  }
}

