/**
 * 鍒ゆ柇娑堟伅鏄惁鍖呭惈澶嶆潅搴﹀叧閿瘝
 */
export function containsComplexKeywords(message: string): boolean {
  return COMPLEX_KEYWORDS.some((kw) => message.includes(kw));
}

// ============================================================
// 瑙掕壊涓撳睘 system prompt 妯℃澘
// ============================================================

